window.HSK_DATA["2"] = [{"id":"休息","hanzi":"休息","pinyin":"xiūxi","meaning_vi":"nghỉ ngơi","explanation":"休 = 亻(người) + 木 (cây): người tựa vào gốc cây nghỉ. 息 = 自 (mũi) + 心 (tim): hơi thở.","hsk_level":2,"tags":["dong-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"你休息吧。","pinyin":"Nǐ xiūxi ba.","vi":"Bạn nghỉ đi."},{"type":"simple","zh":"我周末在家休息。","pinyin":"Wǒ zhōumò zài jiā xiūxi.","vi":"Cuối tuần tôi nghỉ ngơi ở nhà."},{"type":"compound","zh":"你累了，先休息一下，然后再工作吧。","pinyin":"Nǐ lèi le, xiān xiūxi yíxià, ránhòu zài gōngzuò ba.","vi":"Bạn mệt rồi, nghỉ một chút đã rồi hãy làm tiếp."}],"related":[{"hanzi":"休假","pinyin":"xiūjià","vi":"Nghỉ phép"},{"hanzi":"退休","pinyin":"tuìxiū","vi":"Nghỉ hưu"},{"hanzi":"睡觉","pinyin":"shuìjiào","vi":"Đi ngủ"},{"hanzi":"消息","pinyin":"xiāoxi","vi":"Tin tức"},{"hanzi":"累","pinyin":"lèi","vi":"Mệt"}]},{"id":"旅游","hanzi":"旅游","pinyin":"lǚyóu","meaning_vi":"du lịch","explanation":"旅 (đi xa) + 游 (dạo chơi, bộ thủy 氵).","hsk_level":2,"tags":["dong-tu","du-lich"],"image":"✈️","examples":[{"type":"basic","zh":"我喜欢旅游。","pinyin":"Wǒ xǐhuan lǚyóu.","vi":"Tôi thích du lịch."},{"type":"simple","zh":"暑假我们全家去海边旅游。","pinyin":"Shǔjià wǒmen quán jiāqù hǎibiān lǚyóu.","vi":"Kỳ nghỉ hè cả nhà tôi đi du lịch biển."},{"type":"compound","zh":"我很想去旅游，可是最近没有时间。","pinyin":"Wǒ hěn xiǎng qù lǚyóu, kěshì zuìjìn méiyǒu shíjiān.","vi":"Tôi rất muốn đi du lịch nhưng dạo này không có thời gian."}],"related":[{"hanzi":"旅行","pinyin":"lǚxíng","vi":"Du lịch, chuyến đi"},{"hanzi":"旅馆","pinyin":"lǚguǎn","vi":"Nhà nghỉ"},{"hanzi":"游客","pinyin":"yóukè","vi":"Du khách"},{"hanzi":"导游","pinyin":"dǎoyóu","vi":"Hướng dẫn viên"},{"hanzi":"游泳","pinyin":"yóuyǒng","vi":"Bơi lội"}],"traditional":"旅遊"},{"id":"准备","hanzi":"准备","pinyin":"zhǔnbèi","meaning_vi":"chuẩn bị","explanation":"准 (chuẩn xác) + 备 (sẵn sàng). Có thể kèm danh từ hoặc động từ.","hsk_level":2,"tags":["dong-tu"],"image":"🎒","examples":[{"type":"basic","zh":"我准备好了。","pinyin":"Wǒ zhǔnbèihǎo le.","vi":"Tôi chuẩn bị xong rồi."},{"type":"simple","zh":"我们正在准备明天的汉语考试。","pinyin":"Wǒmen zhèngzài zhǔnbèi míngtiān de Hànyǔ kǎoshì.","vi":"Chúng tôi đang chuẩn bị cho kỳ thi tiếng Trung ngày mai."},{"type":"compound","zh":"因为下个月要去中国旅游，所以我最近一直在准备行李。","pinyin":"Yīnwèi xiàgeyuè yào qù Zhōngguó lǚyóu, suǒyǐ wǒ zuìjìn yìzhí zài zhǔnbèi xíngli.","vi":"Vì tháng sau phải đi Trung Quốc du lịch nên dạo này tôi cứ chuẩn bị hành lý suốt."}],"related":[{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"Chính xác"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"Tiêu chuẩn"},{"hanzi":"预备","pinyin":"yùbèi","vi":"Dự bị"},{"hanzi":"设备","pinyin":"shèbèi","vi":"Thiết bị"}],"traditional":"準備"},{"id":"开始","hanzi":"开始","pinyin":"kāishǐ","meaning_vi":"bắt đầu","explanation":"开 (mở) + 始 (khởi đầu). Đối nghĩa với 结束 (kết thúc).","hsk_level":2,"tags":["dong-tu"],"image":"▶️","examples":[{"type":"basic","zh":"现在开始上课。","pinyin":"Xiànzài kāishǐ shàngkè.","vi":"Bây giờ bắt đầu vào học."},{"type":"simple","zh":"我们学校每天早上八点开始上课。","pinyin":"Wǒmen xuéxiào měitiān zǎoshang bā diǎn kāishǐ shàngkè.","vi":"Trường chúng tôi mỗi sáng bắt đầu vào học lúc 8 giờ."},{"type":"compound","zh":"虽然我去年才开始学习汉语，但是现在已经能看懂中文报纸了。","pinyin":"Suīrán wǒ qùnián cái kāishǐ xuéxí Hànyǔ, dànshì xiànzài yǐjīng néng kàndǒng Zhōngwén bàozhǐ le.","vi":"Tuy năm ngoái tôi mới bắt đầu học tiếng Trung nhưng giờ đã có thể đọc hiểu báo tiếng Trung rồi."}],"related":[{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"开","pinyin":"kāi","vi":"Mở/Bắt đầu"},{"hanzi":"始终","pinyin":"shǐzhōng","vi":"Trước sau như một"},{"hanzi":"开始吧","pinyin":"kāishǐba","vi":"Bắt đầu thôi"},{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"}],"traditional":"開始"},{"id":"结束","hanzi":"结束","pinyin":"jiéshù","meaning_vi":"kết thúc","explanation":"结 (kết lại) + 束 (bó lại). Đối nghĩa với 开始 (bắt đầu).","hsk_level":2,"tags":["dong-tu"],"image":"⏹️","examples":[{"type":"basic","zh":"电影已经结束了。","pinyin":"Diànyǐng yǐjīng jiéshù le.","vi":"Bộ phim đã kết thúc rồi."},{"type":"simple","zh":"今天的会议下午五点准时结束。","pinyin":"Jīntiān de huìyì xiàwǔ wǔ diǎn zhǔnshí jiéshù.","vi":"Cuộc họp hôm nay kết thúc đúng 5 giờ chiều."},{"type":"compound","zh":"会议结束以后，大家一起去饭馆吃饭了。","pinyin":"Huìyì jiéshù yǐhòu, dàjiā yìqǐ qù fànguǎn chīfàn le.","vi":"Sau khi cuộc họp kết thúc, mọi người cùng nhau đi nhà hàng ăn cơm."}],"related":[{"hanzi":"开始","pinyin":"kāishǐ","vi":"Bắt đầu"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"Kết hôn"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"Kết quả"},{"hanzi":"束","pinyin":"shù","vi":"Bó/Kết thúc"},{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"}],"traditional":"結束"},{"id":"希望","hanzi":"希望","pinyin":"xīwàng","meaning_vi":"hy vọng, mong muốn","explanation":"希 + 望 (nhìn ngóng). Vừa là động từ vừa là danh từ.","hsk_level":2,"tags":["dong-tu","cam-xuc"],"image":"🌟","examples":[{"type":"basic","zh":"我希望明天天气好。","pinyin":"Wǒ xīwàng míngtiān tiānqì hǎo.","vi":"Tôi hy vọng ngày mai thời tiết đẹp."},{"type":"simple","zh":"爸爸妈妈都希望我能考上一所好大学。","pinyin":"Bàba māma dōu xīwàng wǒ néng kǎoshàng yì suǒ hǎo dàxué.","vi":"Bố mẹ đều hy vọng tôi có thể thi đỗ một trường đại học tốt."},{"type":"compound","zh":"虽然学习汉语有很多困难，但是我希望明年能通过HSK三级考试。","pinyin":"Suī rán xué xí hàn yǔ yǒu hěn duō kùn nan, dàn shì wǒ xī wàng míng nián néng tōng guò HSK sān jí kǎo shì.","vi":"Tuy học tiếng Trung có nhiều khó khăn nhưng tôi hy vọng năm sau có thể đỗ kỳ thi HSK cấp 3."}],"related":[{"hanzi":"盼望","pinyin":"pànwàng","vi":"Mong ngóng"},{"hanzi":"愿望","pinyin":"yuànwàng","vi":"Nguyện vọng"},{"hanzi":"失望","pinyin":"shīwàng","vi":"Thất vọng"},{"hanzi":"想","pinyin":"xiǎng","vi":"Muốn"},{"hanzi":"看望","pinyin":"kànwàng","vi":"Thăm hỏi"}]},{"id":"相信","hanzi":"相信","pinyin":"xiāngxìn","meaning_vi":"tin tưởng","explanation":"相 (lẫn nhau) + 信 (tin cậy, bộ nhân 亻+ 言).","hsk_level":2,"tags":["dong-tu","cam-xuc"],"image":"🤝","examples":[{"type":"basic","zh":"我相信你的话。","pinyin":"Wǒ xiāngxìn nǐ dehuà.","vi":"Tôi tin lời nói của bạn."},{"type":"simple","zh":"老师非常相信每一个学生的能力。","pinyin":"Lǎoshī fēicháng xiāngxìn měi yí ge xuésheng de nénglì.","vi":"Thầy giáo vô cùng tin tưởng năng lực của từng học sinh."},{"type":"compound","zh":"只要你每天坚持努力练习，我相信你一定能把汉语学好。","pinyin":"Zhǐyào nǐ měitiān jiānchí nǔlì liànxí, wǒ xiāngxìn nǐ yídìng néng bǎ Hànyǔ xuéhǎo.","vi":"Chỉ cần mỗi ngày bạn kiên trì nỗ lực luyện tập, tôi tin bạn nhất định sẽ học giỏi tiếng Trung."}],"related":[{"hanzi":"信心","pinyin":"xìnxīn","vi":"Tự tin"},{"hanzi":"信息","pinyin":"xìnxī","vi":"Thông tin"},{"hanzi":"短信","pinyin":"duǎnxìn","vi":"Tin nhắn"},{"hanzi":"相互","pinyin":"xiānghù","vi":"Lẫn nhau"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"Nghi ngờ"}]},{"id":"以为","hanzi":"以为","pinyin":"yǐwéi","meaning_vi":"tưởng rằng, cho rằng","explanation":"Thường dùng khi suy nghĩ trước đó không đúng với thực tế.","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"我以为他已经回家了。","pinyin":"Wǒ yǐwéi tā yǐjīng huíjiā le.","vi":"Tôi cứ tưởng anh ấy đã về nhà rồi."},{"type":"simple","zh":"大家本来以为今天会下雨，没想到太阳出来了。","pinyin":"Dàjiā běnlái yǐwéi jīntiān huì xiàyǔ, méi xiǎngdào tàiyáng chūlái le.","vi":"Mọi người vốn tưởng hôm nay sẽ mưa, không ngờ trời lại nắng."},{"type":"compound","zh":"刚开始学汉语的时候，我以为汉字很难写，后来才发现其实很有规律。","pinyin":"Gāng kāishǐ xué Hànyǔ de shíhou, wǒ yǐwéi hànzì hěn nán xiě, hòulái cái fāxiàn qíshí hěn yǒuguīlǜ.","vi":"Lúc mới bắt đầu học tiếng Trung, tôi cứ tưởng chữ Hán rất khó viết, sau này mới phát hiện thực ra rất có quy luật."}],"related":[{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"觉得","pinyin":"juéde","vi":"Cảm thấy"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"}],"traditional":"以為"},{"id":"认为","hanzi":"认为","pinyin":"rènwéi","meaning_vi":"cho rằng, nhận thấy","explanation":"认 (nhận biết) + 为 (là). Nêu quan điểm cá nhân một cách chắc chắn.","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"💭","examples":[{"type":"basic","zh":"我认为这个方法很好。","pinyin":"Wǒ rènwéi zhè ge fāngfǎ hěn hǎo.","vi":"Tôi cho rằng phương pháp này rất tốt."},{"type":"simple","zh":"很多专家认为每天运动对身体健康非常重要。","pinyin":"Hěn duō zhuānjiā rènwéi měitiān yùndòng duì shēntǐ jiànkāng fēicháng zhòngyào.","vi":"Nhiều chuyên gia cho rằng vận động mỗi ngày vô cùng quan trọng đối với sức khỏe."},{"type":"compound","zh":"虽然别人觉得这份工作很辛苦，但是我认为它能让我学到很多东西。","pinyin":"Suīrán biérén juéde zhè fèn gōngzuò hěn xīnkǔ, dànshì wǒ rènwéi tā néng ràng wǒ xuédào hěn duō dōngxi.","vi":"Tuy người khác thấy công việc này vất vả nhưng tôi cho rằng nó giúp tôi học được rất nhiều điều."}],"related":[{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"},{"hanzi":"觉得","pinyin":"juéde","vi":"Cảm thấy"},{"hanzi":"认识","pinyin":"rènshi","vi":"Quen biết"},{"hanzi":"认真","pinyin":"rènzhēn","vi":"Nghiêm túc"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"}],"traditional":"認為"},{"id":"同意","hanzi":"同意","pinyin":"tóngyì","meaning_vi":"đồng ý","explanation":"同 (cùng) + 意 (ý kiến) → cùng chung ý kiến.","hsk_level":2,"tags":["dong-tu","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"我同意你的意见。","pinyin":"Wǒ tóngyì nǐ de yìjiàn.","vi":"Tôi đồng ý với ý kiến của bạn."},{"type":"simple","zh":"爸爸妈妈已经同意让我去中国留学了。","pinyin":"Bàba māma yǐjīng tóngyì ràng wǒqù Zhōngguó liúxué le.","vi":"Bố mẹ đã đồng ý cho tôi đi Trung Quốc du học rồi."},{"type":"compound","zh":"大家都同意周末去爬山，所以我们要提前准备好水和食物。","pinyin":"Dàjiā dōu tóngyì zhōumò qù páshān, suǒyǐ wǒmen yào tíqián zhǔnbèihǎo shuǐ hé shíwù.","vi":"Mọi người đều đồng ý cuối tuần đi leo núi nên chúng ta phải chuẩn bị sẵn nước và đồ ăn."}],"related":[{"hanzi":"同学","pinyin":"tóngxué","vi":"Bạn học"},{"hanzi":"同事","pinyin":"tóngshì","vi":"Đồng nghiệp"},{"hanzi":"不同","pinyin":"bùtóng","vi":"Khác nhau"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"},{"hanzi":"满意","pinyin":"mǎnyì","vi":"Hài lòng"}]},{"id":"决定","hanzi":"决定","pinyin":"juédìng","meaning_vi":"quyết định","explanation":"决 (quyết đoán) + 定 (ổn định). Vừa là động từ vừa là danh từ.","hsk_level":2,"tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"我决定明天去北京。","pinyin":"Wǒ juédìng míngtiān qù Běijīng.","vi":"Tôi quyết định ngày mai đi Bắc Kinh."},{"type":"simple","zh":"大学毕业以后，他决定留在这座城市工作。","pinyin":"Dàxué bìyè yǐhòu, tā juédìng liú zài zhè zuò chéngshì gōngzuò.","vi":"Sau khi tốt nghiệp đại học, anh ấy quyết định ở lại thành phố này làm việc."},{"type":"compound","zh":"因为外面的雨越下越大，所以我们决定取消今天的公园散步计划。","pinyin":"Yīnwèi wàimiàn de yǔ yuè xià yuè dà, suǒyǐ wǒmen juédìng qǔxiāo jīntiān de gōngyuán sànbù jìhuà.","vi":"Vì mưa bên ngoài càng lúc càng to nên chúng tôi quyết định hủy kế hoạch đi dạo công viên hôm nay."}],"related":[{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"决心","pinyin":"juéxīn","vi":"Quyết tâm"},{"hanzi":"定","pinyin":"dìng","vi":"Định"}],"traditional":"決定"},{"id":"选择","hanzi":"选择","pinyin":"xuǎnzé","meaning_vi":"lựa chọn","explanation":"选 (tuyển chọn) + 择 (chọn lọc). Vừa là động từ vừa là danh từ.","hsk_level":2,"tags":["dong-tu"],"image":"🔀","examples":[{"type":"basic","zh":"你可以自己选择。","pinyin":"Nǐ kěyǐ zìjǐ xuǎnzé.","vi":"Bạn có thể tự mình lựa chọn."},{"type":"simple","zh":"现在年轻人在找工作的时候有很多不同的选择。","pinyin":"Xiànzài niánqīngrén zài zhǎogōngzuò de shíhou yǒu hěn duō bùtóng de xuǎnzé.","vi":"Người trẻ hiện nay khi tìm việc làm có rất nhiều lựa chọn khác nhau."},{"type":"compound","zh":"因为坐飞机比坐火车快得多，所以我最后选择了坐飞机去上海。","pinyin":"Yīnwèi zuòfēijī bǐ zuò huǒchē kuài de duō, suǒyǐ wǒ zuìhòu xuǎnzéle zuòfēijī qù Shànghǎi.","vi":"Vì đi máy bay nhanh hơn đi tàu hỏa nhiều nên cuối cùng tôi đã chọn đi máy bay tới Thượng Hải."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"选手","pinyin":"xuǎnshǒu","vi":"Tuyển thủ"},{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"Tuyển chọn"},{"hanzi":"选","pinyin":"xuǎn","vi":"Chọn"},{"hanzi":"择","pinyin":"zé","vi":"Lựa"}],"traditional":"選擇"},{"id":"参加","hanzi":"参加","pinyin":"cānjiā","meaning_vi":"tham gia","explanation":"参 + 加 (thêm vào). Dùng cho hoạt động, cuộc thi, hội nghị.","hsk_level":2,"tags":["dong-tu"],"image":"🙋‍♂️","examples":[{"type":"basic","zh":"我想参加这个活动。","pinyin":"Wǒ xiǎng cānjiā zhè ge huódòng.","vi":"Tôi muốn tham gia hoạt động này."},{"type":"simple","zh":"下个星期学校要举行汉语比赛，很多留学生都报名参加了。","pinyin":"Xiàge xīngqī xuéxiào yào jǔxíng Hànyǔ bǐsài, hěn duō liúxuésheng dōu bàomíng cānjiā le.","vi":"Tuần sau trường sẽ tổ chức cuộc thi tiếng Trung, rất nhiều du học sinh đã đăng ký tham gia."},{"type":"compound","zh":"虽然他平时工作很忙，但是每次同学聚会他都会尽量参加。","pinyin":"Suīrán tā píngshí gōngzuò hěn máng, dànshì měi cì tóngxué jùhuì tā dōuhuì jǐnliàng cānjiā.","vi":"Tuy bình thường anh ấy làm việc rất bận nhưng lần nào họp lớp anh ấy cũng cố gắng tham gia."}],"related":[{"hanzi":"参观","pinyin":"cānguān","vi":"Tham quan"},{"hanzi":"参考","pinyin":"cānkǎo","vi":"Tham khảo"},{"hanzi":"加入","pinyin":"jiārù","vi":"Gia nhập"},{"hanzi":"加班","pinyin":"jiābān","vi":"Tăng ca"},{"hanzi":"加","pinyin":"jiā","vi":"Thêm"}],"traditional":"參加"},{"id":"介绍","hanzi":"介绍","pinyin":"jièshào","meaning_vi":"giới thiệu","explanation":"介 (ở giữa làm cầu nối) + 绍 (nối tiếp).","hsk_level":2,"tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"我来介绍一下自己。","pinyin":"Wǒ lái jièshào yíxià zìjǐ.","vi":"Tôi xin tự giới thiệu một chút về bản thân."},{"type":"simple","zh":"王老师热情地向大家介绍了新来的越南留学生。","pinyin":"Wáng lǎoshī rèqíng de xiàng dàjiā jièshàole xīn lái de Yuènán liúxuésheng.","vi":"Thầy Vương nhiệt tình giới thiệu với mọi người du học sinh Việt Nam mới đến."},{"type":"compound","zh":"如果你对这家公司感兴趣，我可以帮你介绍一位在那里工作的朋友。","pinyin":"Rúguǒ nǐ duì zhè jiā gōngsī gǎnxìngqù, wǒ kěyǐ bāng nǐ jièshào yí wèi zài nàlǐ gōngzuò de péngyou.","vi":"Nếu bạn hứng thú với công ty này, tôi có thể giới thiệu giúp bạn một người bạn làm việc ở đó."}],"related":[{"hanzi":"自我介绍","pinyin":"zìwǒjièshào","vi":"Tự giới thiệu"},{"hanzi":"中介","pinyin":"zhōngjiè","vi":"Môi giới"},{"hanzi":"认识","pinyin":"rènshi","vi":"Làm quen"},{"hanzi":"推荐","pinyin":"tuījiàn","vi":"Tiến cử"},{"hanzi":"说明","pinyin":"shuōmíng","vi":"Giải thích"}],"traditional":"介紹"},{"id":"了解","hanzi":"了解","pinyin":"liǎojiě","meaning_vi":"hiểu rõ, tìm hiểu","explanation":"了 (rõ ràng) + 解 (giải thích/tháo gỡ).","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"🔍","examples":[{"type":"basic","zh":"我很了解他。","pinyin":"Wǒ hěn liǎojiě tā.","vi":"Tôi rất hiểu rõ anh ấy."},{"type":"simple","zh":"通过看中国电影，我们可以更好地了解中国文化。","pinyin":"Tōngguò kàn Zhōngguó diànyǐng, wǒmen kěyǐ gèng hǎo de liǎojiě Zhōngguó wénhuà.","vi":"Thông qua việc xem phim Trung Quốc, chúng ta có thể hiểu rõ hơn về văn hóa Trung Quốc."},{"type":"compound","zh":"虽然我们刚刚认识不久，但是我已经很了解他的性格和习惯了。","pinyin":"Suīrán wǒmen gānggāng rènshi bùjiǔ, dànshì wǒ yǐjīng hěn liǎojiě tā de xìnggé hé xíguàn le.","vi":"Tuy chúng tôi mới quen nhau chưa lâu nhưng tôi đã hiểu rất rõ tính cách và thói quen của anh ấy rồi."}],"related":[{"hanzi":"理解","pinyin":"lǐjiě","vi":"Lý giải/Hiểu"},{"hanzi":"解决","pinyin":"jiějué","vi":"Giải quyết"},{"hanzi":"知道","pinyin":"zhīdao","vi":"Biết"},{"hanzi":"明白","pinyin":"míngbai","vi":"Hiểu rõ"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"}],"traditional":"瞭解"},{"id":"明白","hanzi":"明白","pinyin":"míngbai","meaning_vi":"hiểu, hiểu rõ; rõ ràng, dễ hiểu","explanation":"明 (sáng tỏ) + 白 (trắng/rõ).","hsk_level":2,"tags":["dong-tu","tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"我明白你的意思了。","pinyin":"Wǒ míngbai nǐ de yìsi le.","vi":"Tôi hiểu ý của bạn rồi."},{"type":"simple","zh":"老师把语法规则讲得非常清楚，大家都听明白了。","pinyin":"Lǎoshī bǎ yǔfǎ guīzé jiǎng de fēicháng qīngchu, dàjiā dōu tīng míngbai le.","vi":"Thầy giáo giảng quy tắc ngữ pháp vô cùng rõ ràng, mọi người đều nghe hiểu hết."},{"type":"compound","zh":"如果有不明白的地方，请随时举手问老师，不要不好意思。","pinyin":"Rúguǒ yǒu bù míngbai de dìfang, qǐng suíshí jǔshǒu wèn lǎoshī, bú yàobù hǎoyìsi.","vi":"Nếu có chỗ nào chưa hiểu rõ thì xin cứ giơ tay hỏi thầy giáo bất cứ lúc nào, đừng ngại."}],"related":[{"hanzi":"明天","pinyin":"míngtiān","vi":"Ngày mai"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"Sáng sủa"},{"hanzi":"白","pinyin":"bái","vi":"Trắng/Rõ"},{"hanzi":"懂","pinyin":"dǒng","vi":"Hiểu"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"}]},{"id":"记得","hanzi":"记得","pinyin":"jìde","meaning_vi":"nhớ, còn nhớ","explanation":"记 (ghi nhớ, bộ ngôn 讠) + 得. Đối nghĩa với 忘记 (quên).","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"我还记得他的名字。","pinyin":"Wǒ hái jìde tā de míngzi.","vi":"Tôi vẫn còn nhớ tên của anh ấy."},{"type":"simple","zh":"出门的时候，你一定要记得带手机和钥匙。","pinyin":"Chūmén de shíhou, nǐ yídìngyào jìde dài shǒujī hé yàoshi.","vi":"Lúc ra khỏi nhà, bạn nhất định phải nhớ mang theo điện thoại và chìa khóa."},{"type":"compound","zh":"虽然我们已经好几年没见面了，但是我依然清楚地记得我们一起学习的日子。","pinyin":"Suīrán wǒmen yǐjīng hǎojǐnián méi jiànmiàn le, dànshì wǒ yīrán qīngchu de jìde wǒmen yìqǐ xuéxí de rìzi.","vi":"Tuy chúng tôi đã mấy năm không gặp nhau nhưng tôi vẫn nhớ rõ những ngày tháng cùng học tập."}],"related":[{"hanzi":"忘记","pinyin":"wàngjì","vi":"Quên mất"},{"hanzi":"记住","pinyin":"jìzhu","vi":"Nhớ kỹ"},{"hanzi":"日记","pinyin":"rìjì","vi":"Nhật ký"},{"hanzi":"笔记本","pinyin":"bǐjìběn","vi":"Sổ tay"},{"hanzi":"觉得","pinyin":"juéde","vi":"Cảm thấy"}],"traditional":"記得"},{"id":"忘记","hanzi":"忘记","pinyin":"wàngjì","meaning_vi":"quên mất","explanation":"忘 (quên) + 记 (ghi nhớ). Đối nghĩa với 记得 (nhớ).","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"🤦","examples":[{"type":"basic","zh":"我忘记带伞了。","pinyin":"Wǒ wàngjì dài sǎn le.","vi":"Tôi quên mang theo ô rồi."},{"type":"simple","zh":"他今天工作太忙，竟然忘记吃午饭了。","pinyin":"Tā jīntiān gōngzuò tài máng, jìngrán wàngjì chī wǔfàn le.","vi":"Hôm nay anh ấy làm việc bận quá, vậy mà lại quên mất cả ăn trưa."},{"type":"compound","zh":"不管以后走到哪里，我都不会忘记王老师对我的关心和帮助。","pinyin":"Bùguǎn yǐhòu zǒu dào nǎlǐ, wǒ dōu bú huì wàngjì Wáng lǎoshī duì wǒ de guānxīn hé bāngzhù.","vi":"Bất kể sau này đi tới đâu, tôi cũng sẽ không bao giờ quên sự quan tâm và giúp đỡ của thầy Vương."}],"related":[{"hanzi":"记得","pinyin":"jìde","vi":"Nhớ"},{"hanzi":"忘","pinyin":"wàng","vi":"Quên"},{"hanzi":"记住","pinyin":"jìzhu","vi":"Nhớ kỹ"},{"hanzi":"日记","pinyin":"rìjì","vi":"Nhật ký"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"Bất cẩn"}],"traditional":"忘記"},{"id":"担心","hanzi":"担心","pinyin":"dānxīn","meaning_vi":"lo lắng","explanation":"担 (gánh vác) + 心 (tâm trí). Động từ ly hợp (别担心 - đừng lo).","hsk_level":2,"tags":["dong-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"妈妈很担心我。","pinyin":"Māma hěn dānxīn wǒ.","vi":"Mẹ rất lo lắng cho tôi."},{"type":"simple","zh":"你别担心，这次考试的题目并不难，你一定能通过。","pinyin":"Nǐ biédānxīn, zhè cì kǎoshì de tímù bìng bùnán, nǐ yídìng néng tōngguò.","vi":"Bạn đừng lo lắng, đề thi lần này không hề khó, bạn nhất định sẽ đỗ."},{"type":"compound","zh":"因为哥哥很晚还没有回家，所以爸爸妈妈都非常担心他的安全。","pinyin":"Yīnwèi gēge hěn wǎn hái méiyǒu huíjiā, suǒyǐ bàba māma dōu fēicháng dānxīn tā de ānquán.","vi":"Vì anh trai khuya rồi vẫn chưa về nhà nên bố mẹ đều vô cùng lo lắng cho sự an toàn của anh ấy."}],"related":[{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"关心","pinyin":"guānxīn","vi":"Quan tâm"},{"hanzi":"放心","pinyin":"fàngxīn","vi":"Yên tâm"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"Cẩn thận"},{"hanzi":"着急","pinyin":"zháojí","vi":"Sốt ruột"}],"traditional":"擔心"},{"id":"害怕","hanzi":"害怕","pinyin":"hàipà","meaning_vi":"sợ hãi, e sợ","explanation":"害 + 怕 (bộ tâm đứng 忄).","hsk_level":2,"tags":["dong-tu","cam-xuc"],"image":"😨","examples":[{"type":"basic","zh":"小狗有点儿害怕。","pinyin":"Xiǎogǒu yǒudiǎnr hàipà.","vi":"Chú chó nhỏ hơi sợ hãi một chút."},{"type":"simple","zh":"我妹妹非常害怕一个人待在黑漆漆的房间里。","pinyin":"Wǒ mèimei fēicháng hàipà yígerén dāi zài hēi qī qī de fángjiān lǐ.","vi":"Em gái tôi vô cùng sợ ở một mình trong căn phòng tối om."},{"type":"compound","zh":"学习汉语的时候不要害怕犯错误，只有多说多练才能进步。","pinyin":"Xuéxí Hànyǔ de shíhou bú yào hàipà fàn cuòwù, zhǐyǒu duō shuō duō liàn cáinéng jìnbù.","vi":"Khi học tiếng Trung đừng sợ mắc lỗi, chỉ có nói nhiều luyện nhiều mới tiến bộ được."}],"related":[{"hanzi":"可怕","pinyin":"kěpà","vi":"Đáng sợ"},{"hanzi":"怕","pinyin":"pà","vi":"Sợ"},{"hanzi":"担心","pinyin":"dānxīn","vi":"Lo lắng"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"Dũng cảm"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"Ngại ngùng"}]},{"id":"感动","hanzi":"感动","pinyin":"gǎndòng","meaning_vi":"cảm động","explanation":"感 (cảm nhận) + 动 (rung động).","hsk_level":2,"tags":["dong-tu","tinh-tu"],"image":"🥹","examples":[{"type":"basic","zh":"我非常感动。","pinyin":"Wǒ fēicháng gǎndòng.","vi":"Tôi vô cùng cảm động."},{"type":"simple","zh":"看了这个关于母爱的电影以后，大家都非常感动。","pinyin":"Kànle zhè ge guānyú mǔ'ài de diànyǐng yǐhòu, dàjiā dōu fēicháng gǎndòng.","vi":"Sau khi xem xong bộ phim về tình mẫu tử này, ai nấy đều vô cùng cảm động."},{"type":"compound","zh":"在我生病住院的时候，同学们每天都来看望我，让我觉得特别感动。","pinyin":"Zài wǒ shēngbìng zhùyuàn de shíhou, tóngxuémen měitiān dōu lái kànwàng wǒ, ràng wǒ juéde tèbié gǎndòng.","vi":"Lúc tôi bị ốm nằm viện, các bạn học ngày nào cũng đến thăm khiến tôi cảm thấy đặc biệt cảm động."}],"related":[{"hanzi":"感谢","pinyin":"gǎnxiè","vi":"Cảm tạ"},{"hanzi":"感冒","pinyin":"gǎnmào","vi":"Cảm cúm"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"激动","pinyin":"jīdòng","vi":"Xúc động"},{"hanzi":"感谢信","pinyin":"gǎnxièxìn","vi":"Thư cảm ơn"}],"traditional":"感動"},{"id":"照顾","hanzi":"照顾","pinyin":"zhàogu","meaning_vi":"chăm sóc","explanation":"照 (chiếu rọi/quan tâm) + 顾 (ngoái nhìn).","hsk_level":2,"tags":["dong-tu","gia-dinh"],"image":"🤗","examples":[{"type":"basic","zh":"姐姐在照顾妹妹。","pinyin":"Jiějie zài zhàogu mèimei.","vi":"Chị gái đang chăm sóc em gái."},{"type":"simple","zh":"爸爸妈妈上班的时候，都是奶奶在家照顾我和弟弟。","pinyin":"Bàba māma shàngbān de shíhou, dōu shì nǎinai zài jiā zhàogu wǒ hé dìdi.","vi":"Lúc bố mẹ đi làm, đều là bà nội ở nhà chăm sóc tôi và em trai."},{"type":"compound","zh":"一个人在国外留学的时候，一定要学会照顾好自己的身体和生活。","pinyin":"Yígerén zài guówài liúxué de shíhou, yídìngyào xuéhuì zhàogu hǎo zìjǐ de shēntǐ hé shēnghuó.","vi":"Khi đi du học ở nước ngoài một mình, nhất định phải học cách tự chăm sóc tốt sức khỏe và cuộc sống của bản thân."}],"related":[{"hanzi":"照片","pinyin":"zhàopiàn","vi":"Bức ảnh"},{"hanzi":"护照","pinyin":"hùzhào","vi":"Hộ chiếu"},{"hanzi":"关心","pinyin":"guānxīn","vi":"Quan tâm"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"顾客","pinyin":"gùkè","vi":"Khách hàng"}],"traditional":"照顧"},{"id":"保护","hanzi":"保护","pinyin":"bǎohù","meaning_vi":"bảo vệ","explanation":"保 (giữ gìn) + 护 (che chở).","hsk_level":2,"tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"我们要保护环境。","pinyin":"Wǒmen yào bǎohù huánjìng.","vi":"Chúng ta phải bảo vệ môi trường."},{"type":"simple","zh":"每天在电脑前工作太久，要注意保护好自己的眼睛。","pinyin":"Měitiān zài diànnǎo qián gōngzuò tài jiǔ, yào zhùyì bǎohù hǎo zìjǐ de yǎnjing.","vi":"Mỗi ngày làm việc trước máy tính quá lâu, phải chú ý bảo vệ tốt đôi mắt của mình."},{"type":"compound","zh":"保护动物和爱护环境是每个公民都应该承担的责任。","pinyin":"Bǎohù dòngwù hé àihù huánjìng shì měi ge gōngmín dōu yīnggāi chéngdān de zérèn.","vi":"Bảo vệ động vật và giữ gìn môi trường là trách nhiệm mà mỗi công dân đều nên gánh vác."}],"related":[{"hanzi":"护照","pinyin":"hùzhào","vi":"Hộ chiếu"},{"hanzi":"护士","pinyin":"hùshi","vi":"Y tá"},{"hanzi":"保证","pinyin":"bǎozhèng","vi":"Bảo đảm"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"}],"traditional":"保護"},{"id":"帮助","hanzi":"帮助","pinyin":"bāngzhù","meaning_vi":"giúp đỡ","explanation":"帮 (giúp) + 助 (trợ giúp). Vừa là động từ vừa là danh từ.","hsk_level":2,"tags":["dong-tu","giao-tiep"],"image":"🤲","examples":[{"type":"basic","zh":"谢谢你的帮助！","pinyin":"Xièxie nǐ de bāngzhù!","vi":"Cảm ơn sự giúp đỡ của bạn!"},{"type":"simple","zh":"同学们在学习上经常互相帮助，一起进步。","pinyin":"Tóngxuémen zài xuéxí shàng jīngcháng hùxiāng bāngzhù, yìqǐ jìnbù.","vi":"Các bạn học trong học tập thường xuyên giúp đỡ lẫn nhau để cùng tiến bộ."},{"type":"compound","zh":"如果没有王老师的耐心帮助，我的汉语水平不可能提高得这么快。","pinyin":"Rúguǒ méiyǒu Wáng lǎoshī de nàixīn bāngzhù, wǒ de Hànyǔ shuǐpíng bù kěnéng tígāo de zhème kuài.","vi":"Nếu không có sự giúp đỡ kiên nhẫn của thầy Vương thì trình độ tiếng Trung của tôi không thể tiến bộ nhanh như vậy."}],"related":[{"hanzi":"帮","pinyin":"bāng","vi":"Giúp"},{"hanzi":"帮忙","pinyin":"bāngmáng","vi":"Giúp một tay"},{"hanzi":"助手","pinyin":"zhùshǒu","vi":"Trợ lý"},{"hanzi":"互助","pinyin":"hùzhù","vi":"Tương trợ"},{"hanzi":"谢谢","pinyin":"xièxie","vi":"Cảm ơn"}],"traditional":"幫助"},{"id":"解决","hanzi":"解决","pinyin":"jiějué","meaning_vi":"giải quyết","explanation":"解 (tháo gỡ) + 决 (quyết định). Thường đi với 问题 (giải quyết vấn đề).","hsk_level":2,"tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"问题已经解决了。","pinyin":"Wèntí yǐjīng jiějué le.","vi":"Vấn đề đã được giải quyết rồi."},{"type":"simple","zh":"我们正在想办法解决这个技术上的难题。","pinyin":"Wǒmen zhèngzài xiǎngbànfǎ jiějué zhè ge jìshù shàng de nántí.","vi":"Chúng tôi đang tìm cách giải quyết bài toán khó về mặt kỹ thuật này."},{"type":"compound","zh":"只要大家团结合作、认真讨论，再复杂的问题也能顺利解决。","pinyin":"Zhǐyào dàjiā tuánjié hézuò, rènzhēn tǎolùn, zài fùzá de wèntí yě néng shùnlì jiějué.","vi":"Chỉ cần mọi người đoàn kết hợp tác và nghiêm túc thảo luận thì vấn đề phức tạp đến mấy cũng giải quyết suôn sẻ."}],"related":[{"hanzi":"了解","pinyin":"liǎojiě","vi":"Hiểu rõ"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"解释","pinyin":"jiěshì","vi":"Giải thích"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"Biện pháp"}],"traditional":"解決"},{"id":"完成","hanzi":"完成","pinyin":"wánchéng","meaning_vi":"hoàn thành","explanation":"完 (xong) + 成 (thành công).","hsk_level":2,"tags":["dong-tu","cong-viec"],"image":"🏁","examples":[{"type":"basic","zh":"我完成作业了。","pinyin":"Wǒ wánchéng zuòyè le.","vi":"Tôi hoàn thành bài tập rồi."},{"type":"simple","zh":"他每天晚上都会按时完成老师布置的所有作业。","pinyin":"Tā měitiān wǎnshang dōuhuì ànshí wánchéng lǎoshī bùzhì de suǒyǒu zuòyè.","vi":"Mỗi tối cậu ấy đều hoàn thành đúng hạn tất cả bài tập thầy giáo giao."},{"type":"compound","zh":"虽然这项工作任务很重，但是我们一定会努力按时完成。","pinyin":"Suīrán zhè xiàng gōngzuò rènwu hěn zhòng, dànshì wǒmen yídìng huì nǔlì ànshí wánchéng.","vi":"Tuy nhiệm vụ công việc này rất nặng nhưng chúng tôi nhất định sẽ nỗ lực hoàn thành đúng hạn."}],"related":[{"hanzi":"完全","pinyin":"wánquán","vi":"Hoàn toàn"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"做完","pinyin":"zuòwán","vi":"Làm xong"}]},{"id":"提高","hanzi":"提高","pinyin":"tígāo","meaning_vi":"nâng cao","explanation":"提 (nâng lên) + 高 (cao). Dùng cho 提高水平 (nâng cao trình độ).","hsk_level":2,"tags":["dong-tu","hoc-tap"],"image":"📈","examples":[{"type":"basic","zh":"我的汉语提高了。","pinyin":"Wǒ de Hànyǔ tígāo le.","vi":"Tiếng Trung của tôi đã tiến bộ rồi."},{"type":"simple","zh":"多跟中国人聊天可以快速提高我们的汉语口语水平。","pinyin":"Duō gēn Zhōngguórén liáotiān kěyǐ kuàisù tígāo wǒmen de Hànyǔ kǒuyǔ shuǐpíng.","vi":"Trò chuyện nhiều với người Trung Quốc có thể nhanh chóng nâng cao trình độ khẩu ngữ tiếng Trung của chúng ta."},{"type":"compound","zh":"自从每天坚持听中文新闻以后，我的汉语听力水平提高了很多。","pinyin":"Zìcóng měitiān jiānchí tīng Zhōngwén xīnwén yǐhòu, wǒ de Hànyǔ tīnglì shuǐpíng tígāole hěn duō.","vi":"Kể từ khi kiên trì nghe tin tức tiếng Trung mỗi ngày, trình độ nghe tiếng Trung của tôi đã nâng cao lên rất nhiều."}],"related":[{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"提醒","pinyin":"tíxǐng","vi":"Nhắc nhở"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"进步","pinyin":"jìnbù","vi":"Tiến bộ"}]},{"id":"复习","hanzi":"复习","pinyin":"fùxí","meaning_vi":"ôn tập","explanation":"复 (lặp lại) + 习 (luyện tập).","hsk_level":2,"tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我在复习生词。","pinyin":"Wǒ zài fùxí shēngcí.","vi":"Tôi đang ôn tập từ mới."},{"type":"simple","zh":"每天晚上睡觉前，我都会把当天学过的课文复习一遍。","pinyin":"Měitiān wǎnshang shuìjiào qián, wǒ dōuhuì bǎ dàngtiān xuéguo de kèwén fùxí yíbiàn.","vi":"Mỗi tối trước khi đi ngủ, tôi đều ôn lại một lượt bài khóa đã học trong ngày."},{"type":"compound","zh":"因为下个星期就要期末考试了，所以大家最近都在图书馆认真复习。","pinyin":"Yīnwèi xiàge xīngqī jiùyào qīmò kǎoshì le, suǒyǐ dàjiā zuìjìn dōu zài túshūguǎn rènzhēn fùxí.","vi":"Vì tuần sau là thi cuối kỳ rồi nên dạo này mọi người đều chăm chỉ ôn tập ở thư viện."}],"related":[{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"},{"hanzi":"预习","pinyin":"yùxí","vi":"Chuẩn bị bài"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"}],"traditional":"複習"},{"id":"练习","hanzi":"练习","pinyin":"liànxí","meaning_vi":"luyện tập; bài tập","explanation":"练 (rèn luyện) + 习 (thực hành).","hsk_level":2,"tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"请大家做练习。","pinyin":"Qǐng dàjiā zuò liànxí.","vi":"Xin mọi người làm bài tập."},{"type":"simple","zh":"学习写汉字需要每天不断地练习，不能偷懒。","pinyin":"Xuéxí xiě hànzì xūyào měitiān búduàn de liànxí, bù néng tōulǎn.","vi":"Học viết chữ Hán cần phải luyện tập không ngừng mỗi ngày, không thể lười biếng."},{"type":"compound","zh":"虽然发音练习有点儿枯燥，但是只要坚持下去就能说出一口标准汉语。","pinyin":"Suīrán fāyīn liànxí yǒudiǎnr kūzào, dànshì zhǐyào jiānchí xiàqù jiù néng shuōchū yìkǒu biāozhǔn Hànyǔ.","vi":"Tuy luyện phát âm hơi khô khan một chút nhưng chỉ cần kiên trì thì sẽ nói được tiếng Trung chuẩn."}],"related":[{"hanzi":"复习","pinyin":"fùxí","vi":"Ôn tập"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"训练","pinyin":"xùnliàn","vi":"Huấn luyện"},{"hanzi":"作业","pinyin":"zuòyè","vi":"Bài tập"},{"hanzi":"习惯","pinyin":"xíguàn","vi":"Thói quen"}],"traditional":"練習"},{"id":"检查","hanzi":"检查","pinyin":"jiǎnchá","meaning_vi":"kiểm tra","explanation":"检 (xem xét) + 查 (tra cứu).","hsk_level":2,"tags":["dong-tu"],"image":"🔎","examples":[{"type":"basic","zh":"医生在给他检查身体。","pinyin":"Yīshēng zài gěi tā jiǎnchá shēntǐ.","vi":"Bác sĩ đang khám sức khỏe cho anh ấy."},{"type":"simple","zh":"做完考试题目以后，一定要认真检查一遍再交卷。","pinyin":"Zuòwán kǎoshì tímù yǐhòu, yídìngyào rènzhēn jiǎnchá yíbiàn zài jiāojuàn.","vi":"Sau khi làm xong đề thi, nhất định phải kiểm tra kỹ lại một lượt rồi mới nộp bài."},{"type":"compound","zh":"爸爸每年都会带爷爷奶奶去大医院做一次全面的身体健康检查。","pinyin":"Bàba měinián dōuhuì dài yéye nǎinai qù dà yīyuàn zuò yí cì quánmiàn de shēntǐ jiànkāng jiǎnchá.","vi":"Bố hằng năm đều đưa ông bà nội đến bệnh viện lớn kiểm tra sức khỏe tổng quát một lần."}],"related":[{"hanzi":"警察","pinyin":"jǐngchá","vi":"Cảnh sát"},{"hanzi":"查","pinyin":"chá","vi":"Tra cứu"},{"hanzi":"体检","pinyin":"tǐjiǎn","vi":"Khám sức khỏe"},{"hanzi":"观察","pinyin":"guānchá","vi":"Quan sát"},{"hanzi":"作业","pinyin":"zuòyè","vi":"Bài tập"}],"traditional":"檢查"},{"id":"发现","hanzi":"发现","pinyin":"fāxiàn","meaning_vi":"phát hiện","explanation":"发 (mở ra) + 现 (hiện ra).","hsk_level":2,"tags":["dong-tu","nhan-thuc"],"image":"👀","examples":[{"type":"basic","zh":"我发现了一个秘密。","pinyin":"Wǒ fāxiànle yí ge mìmì.","vi":"Tôi đã phát hiện ra một bí mật."},{"type":"simple","zh":"我今天早上起床的时候，突然发现外面下雪了。","pinyin":"Wǒ jīntiān zǎoshang qǐchuáng de shíhou, tūrán fāxiàn wàimiàn xiàxuě le.","vi":"Sáng nay lúc thức dậy, tôi đột nhiên phát hiện bên ngoài tuyết rơi rồi."},{"type":"compound","zh":"只要我们仔细观察生活，就会发现身边其实有很多美好的事物。","pinyin":"Zhǐyào wǒmen zǐxì guānchá shēnghuó, jiù huì fāxiàn shēnbiān qíshí yǒu hěn duō měihǎo de shìwù.","vi":"Chỉ cần chúng ta quan sát kỹ cuộc sống thì sẽ phát hiện xung quanh thực ra có rất nhiều điều tốt đẹp."}],"related":[{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"},{"hanzi":"发烧","pinyin":"fāshāo","vi":"Phát sốt"},{"hanzi":"出现","pinyin":"chūxiàn","vi":"Xuất hiện"},{"hanzi":"找到","pinyin":"zhǎodào","vi":"Tìm thấy"}],"traditional":"發現"},{"id":"变化","hanzi":"变化","pinyin":"biànhuà","meaning_vi":"thay đổi, biến hóa","explanation":"变 (biến đổi) + 化 (hóa thành). Vừa là động từ vừa là danh từ.","hsk_level":2,"tags":["dong-tu","danh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"北京的变化很大。","pinyin":"Běijīng de biànhuà hěn dà.","vi":"Sự thay đổi của Bắc Kinh rất lớn."},{"type":"simple","zh":"这几年我的家乡变化很大。","pinyin":"Zhè jǐ nián wǒ de jiāxiāng biànhuà hěn dà.","vi":"Mấy năm nay quê tôi thay đổi rất nhiều."},{"type":"compound","zh":"秋天到了，天气变化很快，早晚很凉，大家要注意增减衣服。","pinyin":"Qiūtiān dào le, tiānqì biànhuà hěn kuài, zǎowǎn hěn liáng, dàjiā yào zhùyì zēngjiǎn yīfu.","vi":"Mùa thu đến rồi, thời tiết thay đổi rất nhanh, sáng tối se lạnh, mọi người chú ý mặc thêm hoặc bớt áo."}],"related":[{"hanzi":"变成","pinyin":"biànchéng","vi":"Biến thành"},{"hanzi":"文化","pinyin":"wénhuà","vi":"Văn hóa"},{"hanzi":"变","pinyin":"biàn","vi":"Thay đổi"},{"hanzi":"化学","pinyin":"huàxué","vi":"Hóa học"},{"hanzi":"发展","pinyin":"fāzhǎn","vi":"Phát triển"}],"traditional":"變化"},{"id":"搬","hanzi":"搬","pinyin":"bān","meaning_vi":"chuyển, dọn (nhà/đồ)","explanation":"Bộ tài gảy 扌+ 般. Dùng trong 搬家 (chuyển nhà).","hsk_level":2,"tags":["dong-tu","nha-cua"],"image":"📦","examples":[{"type":"basic","zh":"我们要搬家了。","pinyin":"Wǒmen yào bānjiā le.","vi":"Chúng tôi sắp chuyển nhà rồi."},{"type":"simple","zh":"张先生一家上个月刚刚搬到学校附近的新房子里。","pinyin":"Zhāng xiānsheng yìjiā shànggeyuè gānggāng bān dào xuéxiào fùjìn de xīnfáng zi lǐ.","vi":"Gia đình ông Trương tháng trước vừa mới chuyển đến căn nhà mới ở gần trường học."},{"type":"compound","zh":"这张桌子太重了，我一个人搬不动，你能过来帮我一下吗？","pinyin":"Zhè zhāng zhuōzi tài zhòng le, wǒ yígerén bān búdòng, nǐ néng guòlái bāng wǒ yíxià ma?","vi":"Cái bàn này nặng quá, một mình tôi bê không nổi, bạn có thể lại đây giúp tôi một tay không?"}],"related":[{"hanzi":"搬家","pinyin":"bānjiā","vi":"Chuyển nhà"},{"hanzi":"一般","pinyin":"yìbān","vi":"Bình thường"},{"hanzi":"拿","pinyin":"ná","vi":"Cầm"},{"hanzi":"放","pinyin":"fàng","vi":"Đặt"},{"hanzi":"房子","pinyin":"fángzi","vi":"Ngôi nhà"}]},{"id":"带","hanzi":"带","pinyin":"dài","meaning_vi":"mang theo, dẫn theo","explanation":"Dùng cho đồ vật mang bên người (带伞 - mang ô) hoặc dẫn người.","hsk_level":2,"tags":["dong-tu"],"image":"👜","examples":[{"type":"basic","zh":"别忘了带手机。","pinyin":"Bié wàngle dài shǒujī.","vi":"Đừng quên mang theo điện thoại."},{"type":"simple","zh":"天气预报说下午有雨，你出门的时候记得带把伞。","pinyin":"Tiānqì yùbào shuō xiàwǔ yǒu yǔ, nǐ chūmén de shíhou jìde dài bǎ sǎn.","vi":"Dự báo thời tiết nói buổi chiều có mưa, lúc ra khỏi nhà bạn nhớ mang theo chiếc ô."},{"type":"compound","zh":"周末爸爸妈妈经常带着我和妹妹去郊外的公园野餐和玩耍。","pinyin":"Zhōumò bàba māma jīngcháng dàizhe wǒ hé mèimei qù jiāowài de gōngyuán yěcān hé wánshuǎ.","vi":"Cuối tuần bố mẹ thường dẫn tôi và em gái ra công viên ngoại ô dã ngoại và vui chơi."}],"related":[{"hanzi":"拿","pinyin":"ná","vi":"Cầm"},{"hanzi":"送","pinyin":"sòng","vi":"Tiễn/Tặng"},{"hanzi":"带路","pinyin":"dàilù","vi":"Dẫn đường"},{"hanzi":"皮带","pinyin":"pídài","vi":"Thắt lưng"},{"hanzi":"领带","pinyin":"lǐngdài","vi":"Cà vạt"}],"traditional":"帶"},{"id":"借","hanzi":"借","pinyin":"jiè","meaning_vi":"mượn, cho mượn","explanation":"Bộ nhân đứng 亻+ 昔. Dùng được cả hai chiều mượn vào và cho mượn.","hsk_level":2,"tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"我借了一本书。","pinyin":"Wǒ jièle yì běn shū.","vi":"Tôi đã mượn một quyển sách."},{"type":"simple","zh":"我昨天去学校图书馆借了两本关于中国历史的书。","pinyin":"Wǒ zuótiān qù xuéxiào túshūguǎn jièle liǎng běn guānyú Zhōngguó lìshǐ de shū.","vi":"Hôm qua tôi đã đến thư viện trường mượn hai quyển sách về lịch sử Trung Quốc."},{"type":"compound","zh":"因为今天出门忘带笔了，所以我向旁边的同学借了一支黑笔。","pinyin":"Yīnwèi jīntiān chūmén wàng dài bǐ le, suǒyǐ wǒ xiàng pángbiān de tóngxué jièle yì zhī hēi bǐ.","vi":"Vì hôm nay ra khỏi nhà quên mang bút nên tôi đã mượn bạn học ngồi cạnh một cây bút mực đen."}],"related":[{"hanzi":"还","pinyin":"huán","vi":"Trả lại"},{"hanzi":"借书","pinyin":"jièshū","vi":"Mượn sách"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"},{"hanzi":"给","pinyin":"gěi","vi":"Cho"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"}]},{"id":"换","hanzi":"换","pinyin":"huàn","meaning_vi":"đổi, thay đổi","explanation":"Bộ tài gảy 扌+ 奂. Dùng cho 换钱 (đổi tiền), 换衣服 (thay quần áo).","hsk_level":2,"tags":["dong-tu"],"image":"💱","examples":[{"type":"basic","zh":"我想换一件大的。","pinyin":"Wǒ xiǎng huàn yí jiàn dà de.","vi":"Tôi muốn đổi một chiếc cỡ lớn."},{"type":"simple","zh":"我去银行把五百美元换成了人民币。","pinyin":"Wǒqù yínháng bǎ wǔ bǎi měiyuán huànchéngle rénmínbì.","vi":"Tôi đã đến ngân hàng đổi 500 đô la Mỹ sang Nhân dân tệ."},{"type":"compound","zh":"因为这双运动鞋有点儿小，穿起来不舒服，所以我决定去商店换一双。","pinyin":"Yīnwèi zhè shuāng yùndòngxié yǒudiǎnr xiǎo, chuān qǐlái bù shūfu, suǒyǐ wǒ juédìng qù shāngdiàn huàn yì shuāng.","vi":"Vì đôi giày thể thao này hơi nhỏ, đi vào không thoải mái nên tôi quyết định ra cửa hàng đổi một đôi khác."}],"related":[{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"交换","pinyin":"jiāohuàn","vi":"Trao đổi"},{"hanzi":"换钱","pinyin":"huànqián","vi":"Đổi tiền"},{"hanzi":"银行","pinyin":"yínháng","vi":"Ngân hàng"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"}],"traditional":"換"},{"id":"花","hanzi":"花","pinyin":"huā","meaning_vi":"hoa; tiêu (tiền), tốn (thời gian)","explanation":"Động từ chỉ việc chi tiêu tiền bạc hoặc dành thời gian (花时间).","hsk_level":2,"tags":["dong-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"我花了二十块钱。","pinyin":"Wǒ huāle èrshí kuài qián.","vi":"Tôi đã tiêu hết 20 tệ."},{"type":"simple","zh":"我每天晚上都要花两个小时学习汉语和做作业。","pinyin":"Wǒ měitiān wǎn Shangdōu yào huā liǎng ge xiǎoshí xuéxí Hànyǔ hé zuò zuòyè.","vi":"Mỗi tối tôi đều dành hai tiếng đồng hồ để học tiếng Trung và làm bài tập."},{"type":"compound","zh":"虽然买这台新电脑花了我很多钱，但是它对我的工作非常有帮助。","pinyin":"Suīrán mǎi zhè tái xīn diàn nǎohuāle wǒ hěn duō qián, dànshì tā duì wǒ de gōngzuò fēicháng yǒubāngzhù.","vi":"Tuy mua chiếc máy tính mới này tốn của tôi rất nhiều tiền nhưng nó giúp ích rất nhiều cho công việc của tôi."}],"related":[{"hanzi":"花钱","pinyin":"huāqián","vi":"Tiêu tiền"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"钱","pinyin":"qián","vi":"Tiền"},{"hanzi":"花园","pinyin":"huāyuán","vi":"Vườn hoa"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"}]},{"id":"试","hanzi":"试","pinyin":"shì","meaning_vi":"thử","explanation":"Bộ ngôn 讠+ 式. Dùng trong 试衣服 (thử quần áo), 试试 (thử xem).","hsk_level":2,"tags":["dong-tu"],"image":"👗","examples":[{"type":"basic","zh":"我想试一下这件衣服。","pinyin":"Wǒ xiǎng shì yíxià zhè jiàn yīfu.","vi":"Tôi muốn thử chiếc áo này một chút."},{"type":"simple","zh":"你可以试试这双鞋。","pinyin":"Nǐ kěyǐ shìshi zhè shuāng xié.","vi":"Bạn có thể thử đôi giày này."},{"type":"compound","zh":"虽然这件事看起来有点儿难，但是只要你勇敢地去试一试，就一定有机会成功。","pinyin":"Suīrán zhè jiàn shì kànqǐlái yǒudiǎnr nán, dànshì zhǐyào nǐ yǒnggǎn de qù shìyishì, jiù yídìng yǒujī huì chénggōng.","vi":"Tuy việc này trông có vẻ hơi khó nhưng chỉ cần bạn dũng cảm thử sức thì nhất định sẽ có cơ hội thành công."}],"related":[{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"试试","pinyin":"shìshi","vi":"Thử xem"},{"hanzi":"面试","pinyin":"miànshì","vi":"Phỏng vấn"},{"hanzi":"测试","pinyin":"cèshì","vi":"Kiểm tra"},{"hanzi":"穿","pinyin":"chuān","vi":"Mặc"}],"traditional":"試"},{"id":"刷牙","hanzi":"刷牙","pinyin":"shuāyá","meaning_vi":"đánh răng","explanation":"刷 (chải) + 牙 (răng).","hsk_level":2,"tags":["dong-tu","sinh-hoat"],"image":"🪥","examples":[{"type":"basic","zh":"我每天早晚都刷牙。","pinyin":"Wǒ měitiān zǎowǎn dōu shuāyá.","vi":"Mỗi ngày sáng tối tôi đều đánh răng."},{"type":"simple","zh":"早上起床以后，我先刷牙洗脸，然后再去吃早饭。","pinyin":"Zǎoshang qǐchuáng yǐhòu, wǒ xiān shuāyá xǐliǎn, ránhòu zài qù chī zǎofàn.","vi":"Buổi sáng sau khi thức dậy, tôi đánh răng rửa mặt trước rồi sau đó mới đi ăn sáng."},{"type":"compound","zh":"医生告诉小朋友们，每天坚持早晚刷牙，牙齿才会健康漂亮。","pinyin":"Yīshēng gàosu xiǎo péngyoumen, měitiān jiānchí zǎowǎn shuāyá, yáchǐ cái huì jiànkāng piàoliang.","vi":"Bác sĩ dặn các bạn nhỏ mỗi ngày kiên trì đánh răng sáng tối thì răng mới khỏe đẹp."}],"related":[{"hanzi":"牙齿","pinyin":"yáchǐ","vi":"Răng"},{"hanzi":"洗脸","pinyin":"xǐliǎn","vi":"Rửa mặt"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"Tắm rửa"},{"hanzi":"起床","pinyin":"qǐchuáng","vi":"Thức dậy"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"Nhà vệ sinh"}]},{"id":"洗澡","hanzi":"洗澡","pinyin":"xǐzǎo","meaning_vi":"tắm, tắm rửa","explanation":"洗 (rửa) + 澡 (tắm, bộ thủy 氵). Động từ ly hợp.","hsk_level":2,"tags":["dong-tu","sinh-hoat"],"image":"🛁","examples":[{"type":"basic","zh":"弟弟正在洗澡。","pinyin":"Dìdi zhèngzài xǐzǎo.","vi":"Em trai đang tắm."},{"type":"simple","zh":"夏天每天运动出汗以后，洗个热水澡会觉得特别舒服。","pinyin":"Xiàtiān měitiān yùndòng chūhàn yǐhòu, xǐ ge rèshuǐzǎo huì juéde tèbié shūfu.","vi":"Mùa hè mỗi ngày sau khi vận động ra mồ hôi, tắm nước nóng một cái sẽ thấy đặc biệt sảng khoái."},{"type":"compound","zh":"他每天晚上下班回到家以后，总是先洗个澡，然后再坐下来吃晚饭。","pinyin":"Tā měitiān wǎnshang xiàbān huídào jiā yǐhòu, zǒngshì xiān xǐ ge zǎo, ránhòu zài zuò xiàlái chī wǎnfàn.","vi":"Mỗi tối sau khi tan làm về đến nhà, anh ấy luôn tắm rửa trước rồi mới ngồi xuống ăn cơm tối."}],"related":[{"hanzi":"洗","pinyin":"xǐ","vi":"Rửa/Giặt"},{"hanzi":"洗手","pinyin":"xǐshǒu","vi":"Rửa tay"},{"hanzi":"洗衣服","pinyin":"xǐyīfu","vi":"Giặt quần áo"},{"hanzi":"刷牙","pinyin":"shuāyá","vi":"Đánh răng"},{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"Nhà vệ sinh"}]},{"id":"散步","hanzi":"散步","pinyin":"sànbù","meaning_vi":"đi dạo, tản bộ","explanation":"散 (thư giãn) + 步 (bước đi). Động từ ly hợp.","hsk_level":2,"tags":["dong-tu","the-thao"],"image":"🚶","examples":[{"type":"basic","zh":"爷爷喜欢在公园散步。","pinyin":"Yéye xǐhuan zài gōngyuán sànbù.","vi":"Ông nội thích đi dạo trong công viên."},{"type":"simple","zh":"每天吃完晚饭以后，爸爸妈妈都会一起去河边散步。","pinyin":"Měitiān chīwán wǎnfàn yǐhòu, bàba māma dōuhuì yìqǐ qù hébiān sànbù.","vi":"Mỗi ngày sau khi ăn xong bữa tối, bố mẹ đều cùng nhau ra bờ sông đi dạo."},{"type":"compound","zh":"因为今天晚上月亮很圆、天气也很凉快，所以我们决定出去散散步。","pinyin":"Yīnwèi jīntiān wǎnshang yuèliang hěn yuán, tiānqì yě hěn liángkuai, suǒyǐ wǒmen juédìng chūqù sàn sanbù.","vi":"Vì tối nay trăng rất tròn và thời tiết cũng mát mẻ nên chúng tôi quyết định ra ngoài đi dạo một lát."}],"related":[{"hanzi":"走路","pinyin":"zǒulù","vi":"Đi bộ"},{"hanzi":"跑步","pinyin":"pǎobù","vi":"Chạy bộ"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"Công viên"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"休息","pinyin":"xiūxi","vi":"Nghỉ ngơi"}]},{"id":"爬山","hanzi":"爬山","pinyin":"páshān","meaning_vi":"leo núi","explanation":"爬 (trèo, bộ trảo 爪) + 山 (núi). Động từ ly hợp.","hsk_level":2,"tags":["dong-tu","the-thao"],"image":"🧗","examples":[{"type":"basic","zh":"周末我们去爬山吧！","pinyin":"Zhōumò wǒmen qù páshān ba!","vi":"Cuối tuần chúng ta đi leo núi nhé!"},{"type":"simple","zh":"秋天的香山风景特别美，很多北京人都喜欢去那里爬山。","pinyin":"Qiūtiān de xiāng shān fēngjǐng tèbié měi, hěn duō Běijīngrén dōu xǐhuan qù nàlǐ páshān.","vi":"Mùa thu phong cảnh Hương Sơn đặc biệt đẹp, rất nhiều người Bắc Kinh đều thích đến đó leo núi."},{"type":"compound","zh":"虽然爬山的时候出了很多汗、腿也很酸，但是看到山顶的风景觉得很值得。","pinyin":"Suīrán páshān de shíhou chūle hěn duō hàn, tuǐ yě hěn suān, dànshì kàndào shāndǐng de fēngjǐng juéde hěn zhíde.","vi":"Tuy lúc leo núi ra nhiều mồ hôi và chân cũng mỏi nhừ nhưng nhìn thấy cảnh đẹp trên đỉnh núi thì thấy rất xứng đáng."}],"related":[{"hanzi":"山","pinyin":"shān","vi":"Núi"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Thể thao"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"累","pinyin":"lèi","vi":"Mệt"}]},{"id":"踢足球","hanzi":"踢足球","pinyin":"tīzúqiú","meaning_vi":"đá bóng","explanation":"踢 (đá, bộ túc ⻊) + 足球 (bóng đá).","hsk_level":2,"tags":["dong-tu","the-thao"],"image":"⚽","examples":[{"type":"basic","zh":"哥哥喜欢踢足球。","pinyin":"Gēge xǐhuan tīzúqiú.","vi":"Anh trai thích đá bóng."},{"type":"simple","zh":"每天下午下课以后，操场上都有很多男生在踢足球。","pinyin":"Měitiān xiàwǔ xiàkè yǐhòu, cāochǎng Shangdōu yǒu hěn duō nánshēng zài tīzúqiú.","vi":"Mỗi chiều sau khi tan học, trên sân vận động đều có rất nhiều nam sinh đang đá bóng."},{"type":"compound","zh":"虽然外面天气有点儿冷，但是大家踢足球踢得非常热闹，一点儿也不觉得冷。","pinyin":"Suīrán wàimiàn tiānqì yǒudiǎnr lěng, dànshì dàjiā tīzúqiú tī de fēicháng rènao, yìdiǎnr yě bù juéde lěng.","vi":"Tuy thời tiết bên ngoài hơi lạnh nhưng mọi người đá bóng rất sôi nổi nên chẳng thấy lạnh chút nào."}],"related":[{"hanzi":"打篮球","pinyin":"dǎlánqiú","vi":"Chơi bóng rổ"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Thể thao"},{"hanzi":"足球","pinyin":"zúqiú","vi":"Bóng đá"},{"hanzi":"脚","pinyin":"jiǎo","vi":"Chân"},{"hanzi":"跑步","pinyin":"pǎobù","vi":"Chạy bộ"}]},{"id":"打篮球","hanzi":"打篮球","pinyin":"dǎlánqiú","meaning_vi":"chơi bóng rổ","explanation":"打 (chơi bằng tay) + 篮球 (bóng rổ).","hsk_level":2,"tags":["dong-tu","the-thao"],"image":"🏀","examples":[{"type":"basic","zh":"他每天都打篮球。","pinyin":"Tā měitiān dōu dǎlánqiú.","vi":"Ngày nào anh ấy cũng chơi bóng rổ."},{"type":"simple","zh":"我弟弟个子很高，他是学校篮球队的队员，打篮球打得特别好。","pinyin":"Wǒ dìdi gèzi hěn gāo, tā shì xuéxiào lánqiúduì de duìyuán, dǎlánqiú dǎ de tèbié hǎo.","vi":"Em trai tôi dáng người rất cao, em ấy là thành viên đội bóng rổ trường và chơi bóng rổ đặc biệt giỏi."},{"type":"compound","zh":"周末的时候，我经常和几个大学同学约好一起去体育馆打篮球。","pinyin":"Zhōumò de shíhou, wǒ jīngcháng hé jǐ ge dàxué tóngxué yuē hǎo yìqǐ qù tǐyùguǎn dǎlánqiú.","vi":"Vào cuối tuần, tôi thường hẹn với mấy bạn học đại học cùng đến nhà thi đấu chơi bóng rổ."}],"related":[{"hanzi":"踢足球","pinyin":"tīzúqiú","vi":"Đá bóng"},{"hanzi":"打","pinyin":"dǎ","vi":"Đánh/Chơi"},{"hanzi":"篮球","pinyin":"lánqiú","vi":"Bóng rổ"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"}],"traditional":"打籃球"},{"id":"骑","hanzi":"骑","pinyin":"qí","meaning_vi":"cưỡi, đi (xe đạp/xe máy)","explanation":"Bộ mã 马 (ngựa) + 奇. Dùng cho 骑自行车 (đi xe đạp).","hsk_level":2,"tags":["dong-tu","giao-thong"],"image":"🚲","examples":[{"type":"basic","zh":"我骑自行车去学校。","pinyin":"Wǒ qí zìxíngchē qù xuéxiào.","vi":"Tôi đi xe đạp đến trường."},{"type":"simple","zh":"现在中国很多城市都有共享单车，骑车出门非常方便。","pinyin":"Xiànzài Zhōngguó hěn duō chéngshì dōu yǒu gòngxiǎng dānchē, qíchē chūmén fēicháng fāngbiàn.","vi":"Hiện nay nhiều thành phố ở Trung Quốc đều có xe đạp dùng chung, đạp xe ra ngoài vô cùng tiện lợi."},{"type":"compound","zh":"因为今天早上天气特别好，所以我没有坐地铁，而是骑自行车去上班。","pinyin":"Yīnwèi jīntiān zǎoshang tiānqì tèbié hǎo, suǒyǐ wǒ méiyǒu zuò dìtiě, érshì qí zìxíngchē qù shàngbān.","vi":"Vì sáng nay thời tiết đặc biệt đẹp nên tôi không đi tàu điện ngầm mà đạp xe đi làm."}],"related":[{"hanzi":"自行车","pinyin":"zìxíngchē","vi":"Xe đạp"},{"hanzi":"骑车","pinyin":"qíchē","vi":"Đạp xe"},{"hanzi":"马","pinyin":"mǎ","vi":"Con ngựa"},{"hanzi":"开","pinyin":"kāi","vi":"Lái (xe)"},{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi/Đi"}],"traditional":"騎"},{"id":"欢迎","hanzi":"欢迎","pinyin":"huānyíng","meaning_vi":"hoan nghênh, chào đón","explanation":"欢 (vui vẻ) + 迎 (đón tiếp).","hsk_level":2,"tags":["dong-tu","giao-tiep"],"image":"🎊","examples":[{"type":"basic","zh":"欢迎你来我家！","pinyin":"Huānyíng nǐ lái wǒ jiā!","vi":"Chào mừng bạn đến nhà tôi!"},{"type":"simple","zh":"老师和同学们站在门口，热烈欢迎新来的留学生。","pinyin":"Lǎoshī hé tóngxuémen zhàn zài ménkǒu, rèliè huānyíng xīn lái de liúxuésheng.","vi":"Thầy giáo và các bạn học đứng ở cổng, nhiệt liệt chào đón các du học sinh mới đến."},{"type":"compound","zh":"王老师不仅课讲得好，而且对人非常热情，所以非常受学生欢迎。","pinyin":"Wáng lǎoshī bùjǐn kè jiǎng de hǎo, érqiě duì rén fēicháng rèqíng, suǒyǐ fēicháng shòu xuésheng huānyíng.","vi":"Thầy Vương không chỉ giảng bài hay mà đối với mọi người cũng rất nhiệt tình nên vô cùng được học sinh yêu mến."}],"related":[{"hanzi":"喜欢","pinyin":"xǐhuan","vi":"Thích"},{"hanzi":"迎接","pinyin":"yíngjiē","vi":"Nghênh đón"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"客人","pinyin":"kèrén","vi":"Khách"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"}],"traditional":"歡迎"},{"id":"祝","hanzi":"祝","pinyin":"zhù","meaning_vi":"chúc, cầu chúc","explanation":"Bộ thị 礻+ 兄. Dùng trong 祝你生日快乐 (Chúc bạn sinh nhật vui vẻ).","hsk_level":2,"tags":["dong-tu","giao-tiep"],"image":"🎂","examples":[{"type":"basic","zh":"祝你生日快乐！","pinyin":"Zhù nǐ shēngrì kuàilè!","vi":"Chúc bạn sinh nhật vui vẻ!"},{"type":"simple","zh":"新年到了，我祝爷爷奶奶身体健康，天天开心！","pinyin":"Xīnnián dào le, wǒ zhù yéye nǎinai shēntǐ jiànkāng, tiāntiān kāixīn!","vi":"Năm mới đến rồi, cháu chúc ông bà nội sức khỏe dồi dào, ngày nào cũng vui vẻ!"},{"type":"compound","zh":"明天你就要参加HSK考试了，祝你考试顺利，取得好成绩！","pinyin":"Míng tiān nǐ jiù yào cān jiā HSK kǎo shì le, zhù nǐ kǎo shì shùn lì, qǔ dé hǎo chéng jì!","vi":"Ngày mai bạn sẽ tham gia kỳ thi HSK rồi, chúc bạn thi cử suôn sẻ và đạt thành tích tốt!"}],"related":[{"hanzi":"祝福","pinyin":"zhùfú","vi":"Chúc phúc"},{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"Chúc mừng"},{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"}]},{"id":"结婚","hanzi":"结婚","pinyin":"jiéhūn","meaning_vi":"kết hôn, cưới","explanation":"结 (kết nối) + 婚 (hôn nhân, bộ nữ 女). Động từ ly hợp.","hsk_level":2,"tags":["dong-tu","gia-dinh"],"image":"💍","examples":[{"type":"basic","zh":"我姐姐下个月结婚。","pinyin":"Wǒ jiějie xiàgeyuè jiéhūn.","vi":"Chị gái tôi tháng sau kết hôn."},{"type":"simple","zh":"他们两个人认识五年了，今年春天终于决定结婚了。","pinyin":"Tāmen liǎng ge rén rènshi wǔ nián le, jīnnián chūntiān zhōngyú juédìng jiéhūn le.","vi":"Hai người họ quen nhau 5 năm rồi, mùa xuân năm nay cuối cùng cũng quyết định kết hôn."},{"type":"compound","zh":"虽然他们结婚以后工作都很忙，但是每天都会一起做晚饭、聊聊天。","pinyin":"Suīrán tāmen jiéhūn yǐhòu gōngzuò dōu hěn máng, dànshì měitiān dōuhuì yìqǐ zuò wǎnfàn, liáo liaotiān.","vi":"Tuy sau khi kết hôn công việc của họ đều rất bận nhưng ngày nào cũng cùng nhau nấu cơm tối và trò chuyện."}],"related":[{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"Chồng"},{"hanzi":"妻子","pinyin":"qīzi","vi":"Vợ"},{"hanzi":"结束","pinyin":"jiéshù","vi":"Kết thúc"},{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"Lễ cưới"},{"hanzi":"离婚","pinyin":"líhūn","vi":"Ly hôn"}],"traditional":"結婚"},{"id":"迟到","hanzi":"迟到","pinyin":"chídào","meaning_vi":"đến muộn, trễ giờ","explanation":"迟 (chậm trễ) + 到 (đến nơi).","hsk_level":2,"tags":["dong-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"对不起，我迟到了。","pinyin":"Duìbuqǐ, wǒ chídào le.","vi":"Xin lỗi, tôi đến muộn rồi."},{"type":"simple","zh":"我们学校规定早上八点上课，学生们从来不迟到。","pinyin":"Wǒmen xuéxiào guīdìng zǎoshang bā diǎn shàngkè, xuéshengmen cóngláibù chídào.","vi":"Trường chúng tôi quy định 8 giờ sáng vào học, các học sinh chưa bao giờ đi muộn."},{"type":"compound","zh":"因为今天早上下大雨，路上堵车很严重，所以我上班迟到了十分钟。","pinyin":"Yīnwèi jīntiān zǎo shangxià dàyǔ, lùshang dǔchē hěn yánzhòng, suǒyǐ wǒ shàngbān chídàole shí fēnzhōng.","vi":"Vì sáng nay trời mưa to, đường tắc nghiêm trọng nên tôi đi làm muộn 10 phút."}],"related":[{"hanzi":"到","pinyin":"dào","vi":"Đến"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"Đúng giờ"},{"hanzi":"早","pinyin":"zǎo","vi":"Sớm"},{"hanzi":"晚","pinyin":"wǎn","vi":"Muộn"},{"hanzi":"上班","pinyin":"shàngbān","vi":"Đi làm"}],"traditional":"遲到"},{"id":"离开","hanzi":"离开","pinyin":"líkāi","meaning_vi":"rời khỏi, chia tay","explanation":"离 (cách xa) + 开 (mở/rời đi).","hsk_level":2,"tags":["dong-tu","giao-thong"],"image":"🚪","examples":[{"type":"basic","zh":"他已经离开北京了。","pinyin":"Tā yǐjīng líkāi Běijīng le.","vi":"Anh ấy đã rời khỏi Bắc Kinh rồi."},{"type":"simple","zh":"离开教室以前，请大家检查一下有没有忘带自己的东西。","pinyin":"Líkāi jiàoshì yǐqián, qǐng dàjiā jiǎnchá yíxià yǒuméiyǒu wàng dài zìjǐ de dōngxi.","vi":"Trước khi rời khỏi phòng học, xin mọi người kiểm tra xem có để quên đồ của mình không."},{"type":"compound","zh":"虽然我已经离开大学很多年了，但是我经常想念那里的老师和同学。","pinyin":"Suīrán wǒ yǐjīng líkāi dàxué hěn duōnián le, dànshì wǒ jīngcháng xiǎngniàn nàlǐ de lǎoshī hé tóngxué.","vi":"Tuy tôi đã rời xa trường đại học nhiều năm rồi nhưng tôi thường xuyên nhớ thầy cô và bạn bè ở đó."}],"related":[{"hanzi":"离","pinyin":"lí","vi":"Cách xa"},{"hanzi":"开","pinyin":"kāi","vi":"Mở/Rời"},{"hanzi":"到达","pinyin":"dàodá","vi":"Đến nơi"},{"hanzi":"分别","pinyin":"fēnbié","vi":"Chia tay"},{"hanzi":"出发","pinyin":"chūfā","vi":"Xuất phát"}],"traditional":"離開"},{"id":"到达","hanzi":"到达","pinyin":"dàodá","meaning_vi":"đến nơi, đạt tới","explanation":"到 (đến) + 达 (tới đích).","hsk_level":2,"tags":["dong-tu","giao-thong"],"image":"🛬","examples":[{"type":"basic","zh":"飞机已经到达机场了。","pinyin":"Fēijī yǐjīng dàodá jīchǎng le.","vi":"Máy bay đã hạ cánh đến sân bay rồi."},{"type":"simple","zh":"我们今天上午十点准时到达了北京火车站。","pinyin":"Wǒmen jīntiān shàngwǔ shí diǎn zhǔnshí dàodále Běijīng huǒchēzhàn.","vi":"Chúng tôi đã đến ga tàu hỏa Bắc Kinh đúng 10 giờ sáng nay."},{"type":"compound","zh":"虽然路上遇到了大风雪，但是火车还是安全地到达了目的地。","pinyin":"Suīrán lùshang yùdàole dà fēngxuě, dànshì huǒchē háishi ānquán de dàodále mùdìdì.","vi":"Tuy trên đường gặp phải bão tuyết lớn nhưng đoàn tàu vẫn đến nơi an toàn."}],"related":[{"hanzi":"到","pinyin":"dào","vi":"Đến"},{"hanzi":"离开","pinyin":"líkāi","vi":"Rời khỏi"},{"hanzi":"表达","pinyin":"biǎodá","vi":"Biểu đạt"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","vi":"Ga tàu"}],"traditional":"到達"},{"id":"经过","hanzi":"经过","pinyin":"jīngguò","meaning_vi":"đi qua, trải qua","explanation":"经 (trải qua) + 过 (qua).","hsk_level":2,"tags":["dong-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"我每天上班都经过这里。","pinyin":"Wǒ měitiān shàngbān dōu jīngguò zhèlǐ.","vi":"Mỗi ngày đi làm tôi đều đi qua đây."},{"type":"simple","zh":"从我家去学校的路上，要经过一个大公园和一个超市。","pinyin":"Cóng wǒ jiāqù xuéxiào de lùshang, yào jīngguò yí ge dà gōngyuán hé yí ge chāoshì.","vi":"Trên đường từ nhà tôi đến trường phải đi ngang qua một công viên lớn và một siêu thị."},{"type":"compound","zh":"经过半年的努力学习，他的汉语听力和口语水平都有了很大提高。","pinyin":"Jīng guòbàn nián de nǔlì xuéxí, tā de Hànyǔ tīnglì hé kǒuyǔ shuǐpíng dōu yǒule hěn dà tígāo.","vi":"Trải qua nửa năm nỗ lực học tập, trình độ nghe và nói tiếng Trung của anh ấy đều tiến bộ rõ rệt."}],"related":[{"hanzi":"过","pinyin":"guo","vi":"Qua/Từng"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"经理","pinyin":"jīnglǐ","vi":"Giám đốc"},{"hanzi":"过去","pinyin":"guòqù","vi":"Quá khứ"},{"hanzi":"路过","pinyin":"lùguò","vi":"Đi ngang qua"}],"traditional":"經過"},{"id":"向","hanzi":"向","pinyin":"xiàng","meaning_vi":"hướng về, phía","explanation":"Vừa là giới từ chỉ phương hướng (向前走) vừa là danh từ.","hsk_level":2,"tags":["gioi-tu","phuong-huong"],"image":"🧭","examples":[{"type":"basic","zh":"请向前走。","pinyin":"Qǐng xiàng qián zǒu.","vi":"Xin mời đi về phía trước."},{"type":"simple","zh":"学生们站起来，微笑着向王老师问好。","pinyin":"Xuéshengmen zhànqǐlái, wēixiàozhe xiàng Wáng lǎoshī wènhǎo.","vi":"Các học sinh đứng dậy, mỉm cười chào thầy Vương."},{"type":"compound","zh":"在学习上遇到不懂的问题时，应该主动向老师和同学请教。","pinyin":"Zài xuéxí shàng yùdào bù dǒng de wèntí shí, yīnggāi zhǔ dòngxiàng lǎoshī hé tóngxué qǐngjiào.","vi":"Khi gặp vấn đề không hiểu trong học tập, nên chủ động thỉnh giáo thầy cô và bạn bè."}],"related":[{"hanzi":"往","pinyin":"wǎng","vi":"Về phía"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"前","pinyin":"qián","vi":"Trước"},{"hanzi":"后","pinyin":"hòu","vi":"Sau"},{"hanzi":"左","pinyin":"zuǒ","vi":"Trái"}]},{"id":"往","hanzi":"往","pinyin":"wǎng","meaning_vi":"về phía, hướng tới","explanation":"Bộ xích 彳+ 主. Dùng trong 往左拐 (rẽ trái), 往前走 (đi thẳng).","hsk_level":2,"tags":["gioi-tu","phuong-huong"],"image":"➡️","examples":[{"type":"basic","zh":"请往左拐。","pinyin":"Qǐng wǎng zuǒguǎi.","vi":"Xin mời rẽ về phía bên trái."},{"type":"simple","zh":"从地铁站出来以后，一直往前走两百米就能看到银行。","pinyin":"Cóng dìtiězhàn chūlái yǐhòu, yìzhí wǎng qián zǒu liǎng bǎimǐ jiù néng kàndào yínháng.","vi":"Sau khi ra khỏi ga tàu điện ngầm, đi thẳng về phía trước 200 mét là thấy ngân hàng."},{"type":"compound","zh":"你先往东走五分钟，看到红绿灯以后再往北拐，医院就在右边。","pinyin":"Nǐ xiān wǎng dōng zǒu wǔ fēnzhōng, kàndào hónglǜdēng yǐhòu zài wǎng běi guǎi, yīyuàn jiù zài yòubiān.","vi":"Bạn đi về hướng Đông 5 phút trước, thấy đèn giao thông rồi rẽ về hướng Bắc, bệnh viện ở ngay bên phải."}],"related":[{"hanzi":"向","pinyin":"xiàng","vi":"Hướng về"},{"hanzi":"来往","pinyin":"láiwǎng","vi":"Qua lại"},{"hanzi":"往往","pinyin":"wǎngwǎng","vi":"Thường thường"},{"hanzi":"去","pinyin":"qù","vi":"Đi"},{"hanzi":"走","pinyin":"zǒu","vi":"Đi"}]},{"id":"跟","hanzi":"跟","pinyin":"gēn","meaning_vi":"cùng với, theo","explanation":"Bộ túc ⻊+ 艮. Dùng giống 和 (跟我一起去) hoặc nghĩa 'đi theo'.","hsk_level":2,"tags":["gioi-tu","lien-tu"],"image":"👣","examples":[{"type":"basic","zh":"我跟你一起去。","pinyin":"Wǒ gēn nǐ yìqǐ qù.","vi":"Tôi đi cùng với bạn."},{"type":"simple","zh":"弟弟每个周末都喜欢跟爸爸一起去公园踢足球。","pinyin":"Dìdi měi ge zhōumò dōu xǐhuan gēn bàba yìqǐ qù gōngyuán tīzúqiú.","vi":"Em trai cuối tuần nào cũng thích cùng bố ra công viên đá bóng."},{"type":"compound","zh":"请大家跟着老师大声读课文，注意每一个汉字的声调。","pinyin":"Qǐng dàjiā gēnzhe lǎoshī dàshēng dú kèwén, zhùyì měi yí ge hànzì de shēngdiào.","vi":"Xin mọi người đọc to bài khóa theo thầy giáo, chú ý thanh điệu của từng chữ Hán."}],"related":[{"hanzi":"和","pinyin":"hé","vi":"Và/Với"},{"hanzi":"一起","pinyin":"yìqǐ","vi":"Cùng nhau"},{"hanzi":"从","pinyin":"cóng","vi":"Từ/Theo"},{"hanzi":"走","pinyin":"zǒu","vi":"Đi"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"}]},{"id":"比","hanzi":"比","pinyin":"bǐ","meaning_vi":"so với, so sánh","explanation":"Chữ tượng hình hai người đứng cạnh nhau để so cao thấp. Dùng trong câu so sánh A 比 B...","hsk_level":2,"tags":["gioi-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"哥哥比我高。","pinyin":"Gēge bǐ wǒ gāo.","vi":"Anh trai cao hơn tôi."},{"type":"simple","zh":"今天的天气比昨天暖和多了，太阳也出来了。","pinyin":"Jīntiān de tiānqì bǐ zuótiān nuǎnhuo duō le, tàiyáng yě chūlái le.","vi":"Thời tiết hôm nay ấm áp hơn hôm qua nhiều, mặt trời cũng ló ra rồi."},{"type":"compound","zh":"虽然坐飞机比坐火车贵一些，但是可以节省很多时间。","pinyin":"Suīrán zuòfēijī bǐ zuò huǒchē guì yìxiē, dànshì kěyǐ jiéshěng hěn duō shíjiān.","vi":"Tuy đi máy bay đắt hơn đi tàu hỏa một chút nhưng có thể tiết kiệm được rất nhiều thời gian."}],"related":[{"hanzi":"比较","pinyin":"bǐjiào","vi":"Tương đối/So sánh"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"Thi đấu"},{"hanzi":"比如","pinyin":"bǐrú","vi":"Ví dụ như"},{"hanzi":"更","pinyin":"gèng","vi":"Càng"},{"hanzi":"最","pinyin":"zuì","vi":"Nhất"}]},{"id":"为","hanzi":"为","pinyin":"wèi","meaning_vi":"cho, vì (ai/việc gì)","explanation":"Biểu thị mục đích hoặc đối tượng phục vụ (为你好).","hsk_level":2,"tags":["gioi-tu"],"image":"🎁","examples":[{"type":"basic","zh":"这是为你买的礼物。","pinyin":"Zhè shì wèi nǐ mǎi de lǐwù.","vi":"Đây là món quà mua tặng cho bạn."},{"type":"simple","zh":"妈妈每天早起为我们全家准备营养丰富的早饭。","pinyin":"Māma měitiān zǎoqǐ wèi wǒmen quánjiā zhǔnbèi yíngyǎng fēngfù de zǎofàn.","vi":"Mẹ mỗi ngày dậy sớm chuẩn bị bữa sáng giàu dinh dưỡng cho cả nhà chúng tôi."},{"type":"compound","zh":"我们都为你感到高兴，因为你终于通过了考试。","pinyin":"Wǒmen dōu wèi nǐ gǎndào gāoxìng, yīnwèi nǐ zhōngyú tōngguòle kǎoshì.","vi":"Chúng tôi đều mừng cho bạn vì cuối cùng bạn đã thi đỗ."}],"related":[{"hanzi":"为了","pinyin":"wèile","vi":"Để/Vì"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"为什么","pinyin":"wèishénme","vi":"Tại sao"},{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"}],"traditional":"為"},{"id":"为了","hanzi":"为了","pinyin":"wèile","meaning_vi":"để, vì (mục đích)","explanation":"为 + 了. Đứng đầu vế câu chỉ mục đích hành động.","hsk_level":2,"tags":["gioi-tu","lien-tu"],"image":"🎯","examples":[{"type":"basic","zh":"为了健康，我们要多运动。","pinyin":"Wèile jiànkāng, wǒmen yào duō yùndòng.","vi":"Vì sức khỏe, chúng ta phải vận động nhiều hơn."},{"type":"simple","zh":"为了准备下个月的HSK考试，他每天晚上都在图书馆学习。","pinyin":"Wèi le zhǔn bèi xià ge yuè de HSK kǎo shì, tā měi tiān wǎn shang dōu zài tú shū guǎn xué xí.","vi":"Để chuẩn bị cho kỳ thi HSK tháng sau, tối nào anh ấy cũng học ở thư viện."},{"type":"compound","zh":"为了能去中国留学，妹妹每天都坚持听中文广播和练习写汉字。","pinyin":"Wèile néng qù Zhōngguó liúxué, mèimei měitiān dōu jiānchí tīng Zhōngwén guǎngbō hé liànxí xiě hànzì.","vi":"Để có thể đi Trung Quốc du học, em gái ngày nào cũng kiên trì nghe đài tiếng Trung và luyện viết chữ Hán."}],"related":[{"hanzi":"为","pinyin":"wèi","vi":"Vì"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"Bởi vì"},{"hanzi":"了","pinyin":"le","vi":"Rồi"},{"hanzi":"目的","pinyin":"mùdì","vi":"Mục đích"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"}],"traditional":"為了"},{"id":"让","hanzi":"让","pinyin":"ràng","meaning_vi":"bảo, để cho; khiến, làm cho; nhường","explanation":"Bộ ngôn 讠+ 上. Động từ sai khiến (妈妈让我去买菜).","hsk_level":2,"tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"妈妈让我去买菜。","pinyin":"Māma ràng wǒqù mǎicài.","vi":"Mẹ bảo tôi đi mua thức ăn."},{"type":"simple","zh":"老师让我们每天回家以后都要认真复习今天学过的生词。","pinyin":"Lǎoshī ràng wǒmen měitiān huíjiā yǐhòu dōu yào rènzhēn fùxí jīntiān xuéguo de shēngcí.","vi":"Thầy giáo bảo chúng tôi mỗi ngày sau khi về nhà đều phải ôn tập kỹ từ mới đã học hôm nay."},{"type":"compound","zh":"这部电影的故事非常感人，让电影院里的很多观众都流下了眼泪。","pinyin":"Zhè bù diànyǐng de gùshi fēicháng gǎnrén, ràng diànyǐngyuàn lǐ de hěn duō guānzhòng dōu liú xiàle yǎnlèi.","vi":"Câu chuyện của bộ phim này vô cùng cảm động, khiến rất nhiều khán giả trong rạp rơi nước mắt."}],"related":[{"hanzi":"请","pinyin":"qǐng","vi":"Mời"},{"hanzi":"叫","pinyin":"jiào","vi":"Bảo/Gọi"},{"hanzi":"让座","pinyin":"ràngzuò","vi":"Nhường ghế"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"}],"traditional":"讓"},{"id":"被","hanzi":"被","pinyin":"bèi","meaning_vi":"bị, được (câu bị động)","explanation":"Bộ y 衤+ 皮. Dùng trong câu bị động chữ 被.","hsk_level":2,"tags":["gioi-tu"],"image":"🔄","examples":[{"type":"basic","zh":"苹果被弟弟吃了。","pinyin":"Píngguǒ bèi dìdi chī le.","vi":"Quả táo bị em trai ăn mất rồi."},{"type":"simple","zh":"我的自行车昨天不小心被别人骑走了。","pinyin":"Wǒ de zìxíngchē zuótiān bù xiǎoxīn bèi biérén qí zǒu le.","vi":"Chiếc xe đạp của tôi hôm qua vô tình bị người khác đạp đi mất rồi."},{"type":"compound","zh":"因为今天早上起床晚了，所以我到了公司以后被经理批评了一顿。","pinyin":"Yīnwèi jīntiān zǎoshang qǐchuáng wǎn le, suǒyǐ wǒ dàole gōngsī yǐhòu bèi jīnglǐ pīpíngle yí dùn.","vi":"Vì sáng nay thức dậy muộn nên sau khi đến công ty tôi đã bị giám đốc phê bình một trận."}],"related":[{"hanzi":"把","pinyin":"bǎ","vi":"Đem/Lấy"},{"hanzi":"给","pinyin":"gěi","vi":"Cho/Bị"},{"hanzi":"让","pinyin":"ràng","vi":"Khiến/Bảo"},{"hanzi":"被子","pinyin":"bèizi","vi":"Chăn"},{"hanzi":"别人","pinyin":"biérén","vi":"Người khác"}]},{"id":"快乐","hanzi":"快乐","pinyin":"kuàilè","meaning_vi":"vui vẻ, hạnh phúc","explanation":"快 (sảng khoái) + 乐 (vui mừng). Dùng trong 生日快乐, 新年快乐.","hsk_level":2,"tags":["tinh-tu","cam-xuc"],"image":"🥳","examples":[{"type":"basic","zh":"祝你新年快乐！","pinyin":"Zhù nǐ xīnnián kuàilè!","vi":"Chúc bạn năm mới vui vẻ!"},{"type":"simple","zh":"今天是妹妹的十岁生日，全家人在一起过得非常快乐。","pinyin":"Jīntiān shì mèimei de shí suì shēngrì, quán jiārén zài yìqǐ guòde fēicháng kuàilè.","vi":"Hôm nay là sinh nhật 10 tuổi của em gái, cả nhà quây quần bên nhau vô cùng hạnh phúc."},{"type":"compound","zh":"虽然我们的生活并不算很富裕，但是全家人身体健康、快快乐乐的就足够了。","pinyin":"Suīrán wǒmen de shēnghuó bìng búsuàn hěn fùyù, dànshì quán jiārén shēntǐ jiànkāng, kuài kuàilè lè de jiù zúgòu le.","vi":"Tuy cuộc sống của chúng tôi không tính là giàu có nhưng cả nhà khỏe mạnh, vui vẻ hạnh phúc là đủ rồi."}],"related":[{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh/Sảng khoái"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"Âm nhạc"},{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"}],"traditional":"快樂"},{"id":"开心","hanzi":"开心","pinyin":"kāixīn","meaning_vi":"vui vẻ, vui","explanation":"开 (mở) + 心 (trái tim).","hsk_level":2,"tags":["tinh-tu","cam-xuc"],"image":"😄","examples":[{"type":"basic","zh":"我今天很开心。","pinyin":"Wǒ jīntiān hěn kāixīn.","vi":"Hôm nay tôi rất vui."},{"type":"simple","zh":"周末和好朋友们一起去公园野餐，大家都玩得非常开心。","pinyin":"Zhōumò héhǎo péngyoumen yìqǐ qù gōngyuán yěcān, dàjiā dōu wán de fēicháng kāixīn.","vi":"Cuối tuần đi dã ngoại ở công viên cùng bạn thân, ai nấy đều chơi vô cùng vui vẻ."},{"type":"compound","zh":"听到自己顺利通过了HSK二级考试的消息，她开心地跳了起来。","pinyin":"Tīng dào zì jǐ shùn lì tōng guò le HSK èr jí kǎo shì de xiāo xi, tā kāi xīn de tiào le qǐ lái.","vi":"Nghe tin mình đã thi đỗ kỳ thi HSK cấp 2 một cách suôn sẻ, cô ấy vui mừng nhảy cẫng lên."}],"related":[{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Hạnh phúc"},{"hanzi":"担心","pinyin":"dānxīn","vi":"Lo lắng"},{"hanzi":"关心","pinyin":"guānxīn","vi":"Quan tâm"},{"hanzi":"开","pinyin":"kāi","vi":"Mở"}],"traditional":"開心"},{"id":"难过","hanzi":"难过","pinyin":"nánguò","meaning_vi":"buồn bã, khó chịu","explanation":"难 (khó) + 过 (trải qua).","hsk_level":2,"tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"他心里很难过。","pinyin":"Tā xīnlǐ hěn nánguò.","vi":"Trong lòng anh ấy rất buồn."},{"type":"simple","zh":"听到好朋友马上要回国的消息，我心里觉得有点儿难过。","pinyin":"Tīngdào hǎopéngyou mǎshàng yào huíguó de xiāoxi, wǒ xīnlǐ juéde yǒudiǎnr nánguò.","vi":"Nghe tin bạn thân sắp phải về nước, trong lòng tôi cảm thấy hơi buồn một chút."},{"type":"compound","zh":"虽然这次比赛没有拿到第一名，但是你不要难过，下次继续努力就行。","pinyin":"Suīrán zhè cì bǐsài méiyǒu nádào dìyīmíng, dànshì nǐ bú yào nánguò, xiàcì jìxù nǔlì jiù xíng.","vi":"Tuy cuộc thi lần này không giành được giải nhất nhưng bạn đừng buồn, lần sau tiếp tục cố gắng là được."}],"related":[{"hanzi":"难","pinyin":"nán","vi":"Khó"},{"hanzi":"过","pinyin":"guò","vi":"Qua/Trải qua"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"},{"hanzi":"哭","pinyin":"kū","vi":"Khóc"}],"traditional":"難過"},{"id":"生气","hanzi":"生气","pinyin":"shēngqì","meaning_vi":"tức giận, giận dữ","explanation":"生 (sinh ra) + 气 (khí/cơn giận). Động từ ly hợp.","hsk_level":2,"tags":["dong-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"老师生气了。","pinyin":"Lǎoshī shēngqì le.","vi":"Thầy giáo tức giận rồi."},{"type":"simple","zh":"因为弟弟不小心打碎了杯子，所以妈妈有点儿生气。","pinyin":"Yīnwèi dìdi bù xiǎoxīn dǎsuìle bēizi, suǒyǐ māma yǒudiǎnr shēngqì.","vi":"Vì em trai vô tình làm vỡ chiếc cốc nên mẹ hơi tức giận một chút."},{"type":"compound","zh":"遇到事情的时候要冷静沟通，经常生气不但不能解决问题，还会影响健康。","pinyin":"Yùdào shìqing de shíhou yào lěngjìng gōutōng, jīngcháng shēngqì búdàn bù néng jiějué wèntí, hái huì yǐngxiǎng jiànkāng.","vi":"Khi gặp chuyện cần bình tĩnh trao đổi, thường xuyên tức giận không những không giải quyết được vấn đề mà còn ảnh hưởng sức khỏe."}],"related":[{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"},{"hanzi":"空气","pinyin":"kōngqì","vi":"Không khí"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui vẻ"},{"hanzi":"客气","pinyin":"kèqi","vi":"Khách sáo"}],"traditional":"生氣"},{"id":"着急","hanzi":"着急","pinyin":"zháojí","meaning_vi":"lo lắng, vội vàng, sốt ruột","explanation":"着 (đọc zháo) + 急 (gấp gáp).","hsk_level":2,"tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"别着急，慢慢说。","pinyin":"Biézháojí, màn mànshuō.","vi":"Đừng vội, cứ từ từ nói."},{"type":"simple","zh":"火车还有十分钟就要开了，他还没到车站，大家都很着急。","pinyin":"Huǒchē háiyǒu shí fēnzhōng jiùyào kāi le, tā hái méi dào chēzhàn, dàjiā dōu hěn zháojí.","vi":"Tàu hỏa còn 10 phút nữa là chạy rồi mà anh ấy vẫn chưa tới ga, mọi người đều rất sốt ruột."},{"type":"compound","zh":"遇到困难的时候千万不要着急，只要冷静下来认真思考，总能找到办法。","pinyin":"Yùdào kùnnan de shíhou qiānwàn bú yào zháojí, zhǐyào lěngjìng xiàlái rènzhēn sīkǎo, zǒngnéng zhǎodào bànfǎ.","vi":"Lúc gặp khó khăn tuyệt đối đừng nóng vội, chỉ cần bình tĩnh lại suy nghĩ kỹ thì luôn tìm được cách giải quyết."}],"related":[{"hanzi":"急忙","pinyin":"jímáng","vi":"Vội vàng"},{"hanzi":"担心","pinyin":"dānxīn","vi":"Lo lắng"},{"hanzi":"着","pinyin":"zhe","vi":"Đang"},{"hanzi":"慢","pinyin":"màn","vi":"Chậm"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh"}],"traditional":"著急"},{"id":"认真","hanzi":"认真","pinyin":"rènzhēn","meaning_vi":"nghiêm túc, chăm chỉ","explanation":"认 (nhận thức) + 真 (chân thật).","hsk_level":2,"tags":["tinh-tu","hoc-tap"],"image":"🧐","examples":[{"type":"basic","zh":"他学习很认真。","pinyin":"Tā xuéxí hěn rènzhēn.","vi":"Cậu ấy học tập rất chăm chỉ."},{"type":"simple","zh":"王老师工作非常认真，每天都会仔细批改学生的作业。","pinyin":"Wáng lǎoshī gōngzuò fēicháng rènzhēn, měitiān dōuhuì zǐxì pīgǎi xuésheng de zuòyè.","vi":"Thầy Vương làm việc vô cùng nghiêm túc, ngày nào cũng chấm chữa bài tập của học sinh rất cẩn thận."},{"type":"compound","zh":"只要你上课认真听讲、下课认真复习，就一定能取得好成绩。","pinyin":"Zhǐyào nǐ shàngkè rènzhēn tīngjiǎng, xiàkè rènzhēn fùxí, jiù yídìng néng qǔdé hǎo chéngjì.","vi":"Chỉ cần bạn lên lớp chăm chỉ nghe giảng và tan học nghiêm túc ôn bài thì nhất định sẽ đạt thành tích tốt."}],"related":[{"hanzi":"认识","pinyin":"rènshi","vi":"Quen biết"},{"hanzi":"认为","pinyin":"rènwéi","vi":"Cho rằng"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"仔细","pinyin":"zǐxì","vi":"Cẩn thận"}],"traditional":"認真"},{"id":"努力","hanzi":"努力","pinyin":"nǔlì","meaning_vi":"nỗ lực, cố gắng","explanation":"努 (gắng sức) + 力 (sức lực). Vừa là tính từ vừa là động từ.","hsk_level":2,"tags":["tinh-tu","hoc-tap"],"image":"💪","examples":[{"type":"basic","zh":"我们要努力学习。","pinyin":"Wǒmen yào nǔlì xuéxí.","vi":"Chúng ta phải nỗ lực học tập."},{"type":"simple","zh":"他工作非常努力，去年得到了公司的表彰。","pinyin":"Tā gōngzuò fēicháng nǔlì, qùnián dédàole gōngsī de biǎozhāng.","vi":"Anh ấy làm việc vô cùng nỗ lực, năm ngoái đã nhận được khen thưởng của công ty."},{"type":"compound","zh":"只要你肯付出努力，不管遇到什么困难，最终都会收获成功。","pinyin":"Zhǐyào nǐ kěn fùchū nǔlì, bùguǎn yùdào shénme kùnnan, zuìzhōng dōuhuì shōuhuò chénggōng.","vi":"Chỉ cần bạn chịu bỏ ra nỗ lực, bất kể gặp khó khăn gì, cuối cùng cũng sẽ gặt hái thành công."}],"related":[{"hanzi":"认真","pinyin":"rènzhēn","vi":"Chăm chỉ"},{"hanzi":"能力","pinyin":"nénglì","vi":"Năng lực"},{"hanzi":"力量","pinyin":"lìliàng","vi":"Sức mạnh"},{"hanzi":"加油","pinyin":"jiāyóu","vi":"Cố lên"},{"hanzi":"成功","pinyin":"chénggōng","vi":"Thành công"}]},{"id":"聪明","hanzi":"聪明","pinyin":"cōngming","meaning_vi":"thông minh","explanation":"聪 (thính tai) + 明 (sáng mắt).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"这个孩子很聪明。","pinyin":"Zhè ge háizi hěn cōngming.","vi":"Đứa trẻ này rất thông minh."},{"type":"simple","zh":"小王不仅头脑聪明，而且做事情也非常勤快。","pinyin":"Xiǎo Wáng bùjǐn tóunǎo cōngming, érqiě zuò shìqing yě fēicháng qínkuài.","vi":"Tiểu Vương không chỉ đầu óc thông minh mà làm việc cũng rất siêng năng."},{"type":"compound","zh":"虽然他非常聪明，但是如果平时不努力复习，考试也很难拿高分。","pinyin":"Suīrán tā fēicháng cōngming, dànshì rúguǒ píngshí bù nǔlì fùxí, kǎoshì yě hěn nán ná gāofēn.","vi":"Tuy cậu ấy rất thông minh nhưng nếu bình thường không chịu khó ôn tập thì thi cử cũng khó đạt điểm cao."}],"related":[{"hanzi":"明白","pinyin":"míngbai","vi":"Hiểu rõ"},{"hanzi":"笨","pinyin":"bèn","vi":"Ngốc nghếch"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"Đáng yêu"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"},{"hanzi":"孩子","pinyin":"háizi","vi":"Trẻ em"}],"traditional":"聰明"},{"id":"热情","hanzi":"热情","pinyin":"rèqíng","meaning_vi":"nhiệt tình","explanation":"热 (nóng ấm) + 情 (tình cảm).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🤗","examples":[{"type":"basic","zh":"中国人非常热情。","pinyin":"Zhōngguórén fēicháng rèqíng.","vi":"Người Trung Quốc vô cùng nhiệt tình."},{"type":"simple","zh":"每次去朋友家做客，他父母都会非常热情地招待我。","pinyin":"Měi cì qù péngyou jiā zuòkè, tā fùmǔ dōuhuì fēicháng rèqíng de zhāodài wǒ.","vi":"Mỗi lần đến nhà bạn chơi, bố mẹ cậu ấy đều tiếp đón tôi vô cùng nhiệt tình."},{"type":"compound","zh":"这家饭店的服务员不仅态度热情，而且上菜的速度也很快。","pinyin":"Zhè jiā fàndiàn de fúwùyuán bùjǐn tàidù rèqíng, érqiě shàngcài de sùdù yě hěn kuài.","vi":"Nhân viên phục vụ của nhà hàng này không chỉ thái độ nhiệt tình mà tốc độ lên món cũng rất nhanh."}],"related":[{"hanzi":"热","pinyin":"rè","vi":"Nóng/Nhiệt"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"Tình cảm"},{"hanzi":"友好","pinyin":"yǒuhǎo","vi":"Thân thiện"},{"hanzi":"客气","pinyin":"kèqi","vi":"Khách sáo"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"Lạnh nhạt"}],"traditional":"熱情"},{"id":"友好","hanzi":"友好","pinyin":"yǒuhǎo","meaning_vi":"thân thiện, hữu nghị","explanation":"友 (bạn bè) + 好 (tốt đẹp).","hsk_level":2,"tags":["tinh-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"他们对我们很友好。","pinyin":"Tāmen duì wǒmen hěn yǒuhǎo.","vi":"Họ rất thân thiện với chúng tôi."},{"type":"simple","zh":"新同学对大家都很友好。","pinyin":"Xīn tóngxué duì dàjiā dōu hěn yǒuhǎo.","vi":"Bạn học mới rất thân thiện với mọi người."},{"type":"compound","zh":"新来的同事性格非常开朗友好，很快就和大家打成了一片。","pinyin":"Xīn lái de tóngshì xìnggé fēicháng kāilǎng yǒuhǎo, hěn kuài jiù hé dàjiā dǎ chéngle yípiàn.","vi":"Đồng nghiệp mới đến tính cách vô cùng cởi mở thân thiện, chẳng mấy chốc đã hòa đồng với mọi người."}],"related":[{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"},{"hanzi":"友谊","pinyin":"yǒuyì","vi":"Tình bạn"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"好","pinyin":"hǎo","vi":"Tốt"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"}]},{"id":"可爱","hanzi":"可爱","pinyin":"kě'ài","meaning_vi":"đáng yêu, dễ thương","explanation":"可 (đáng) + 爱 (yêu).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🥰","examples":[{"type":"basic","zh":"这只小猫真可爱！","pinyin":"Zhè zhī xiǎomāo zhēn kě'ài!","vi":"Chú mèo nhỏ này đáng yêu thật đấy!"},{"type":"simple","zh":"邻居家的小女孩长着一双大眼睛，看起来特别可爱。","pinyin":"Lín jūjiā de xiǎo nǚhái zhǎngzhe yì shuāng dà yǎnjing, kànqǐlái tèbié kě'ài.","vi":"Cô bé nhà hàng xóm có đôi mắt to tròn, trông đặc biệt đáng yêu."},{"type":"compound","zh":"我妹妹今年五岁，她说话的声音甜甜的，大家都觉得她非常可爱。","pinyin":"Wǒ mèimei jīnnián wǔ suì, tā shuōhuà de shēngyīn tiántián de, dàjiā dōu juéde tā fēicháng kě'ài.","vi":"Em gái tôi năm nay 5 tuổi, giọng nói của bé ngọt ngào, ai cũng thấy bé vô cùng đáng yêu."}],"related":[{"hanzi":"爱","pinyin":"ài","vi":"Yêu"},{"hanzi":"喜欢","pinyin":"xǐhuan","vi":"Thích"},{"hanzi":"漂亮","pinyin":"piàoliang","vi":"Xinh đẹp"},{"hanzi":"小","pinyin":"xiǎo","vi":"Nhỏ"},{"hanzi":"孩子","pinyin":"háizi","vi":"Trẻ em"}],"traditional":"可愛"},{"id":"帅","hanzi":"帅","pinyin":"shuài","meaning_vi":"đẹp trai, bảnh bao","explanation":"Dùng để khen nam giới đẹp trai (他很帅).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"😎","examples":[{"type":"basic","zh":"你哥哥真帅！","pinyin":"Nǐ gēge zhēn shuài!","vi":"Anh trai bạn đẹp trai thật đấy!"},{"type":"simple","zh":"他今天穿了一套黑色的西装，看起来非常帅气。","pinyin":"Tā jīntiān chuānle yítào hēisè de xīzhuāng, kànqǐlái fēicháng shuàiqì.","vi":"Hôm nay anh ấy mặc một bộ vest màu đen, trông vô cùng bảnh bao."},{"type":"compound","zh":"那个正在操场上打篮球的男生不仅长得帅，而且学习成绩也很好。","pinyin":"Nà ge zhèngzài cāochǎng shang dǎlánqiú de nánshēng bùjǐn zhǎngde shuài, érqiě xuéxí chéngjì yě hěn hǎo.","vi":"Nam sinh đang chơi bóng rổ trên sân vận động kia không những đẹp trai mà thành tích học tập cũng rất tốt."}],"related":[{"hanzi":"漂亮","pinyin":"piàoliang","vi":"Xinh đẹp"},{"hanzi":"好看","pinyin":"hǎokàn","vi":"Ưa nhìn"},{"hanzi":"男人","pinyin":"nánrén","vi":"Đàn ông"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"Trẻ tuổi"}],"traditional":"帥"},{"id":"年轻","hanzi":"年轻","pinyin":"niánqīng","meaning_vi":"trẻ, trẻ tuổi","explanation":"年 (tuổi tác) + 轻 (nhẹ) → tuổi đời còn trẻ.","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🧑","examples":[{"type":"basic","zh":"王老师很年轻。","pinyin":"Wáng lǎoshī hěn niánqīng.","vi":"Thầy Vương rất trẻ."},{"type":"simple","zh":"现在的年轻人喜欢通过手机在网上买东西和看新闻。","pinyin":"Xiànzài de niánqīngrén xǐhuan tōngguò shǒujī zài wǎngshang mǎidōngxi hé kàn xīnwén.","vi":"Giới trẻ hiện nay thích mua sắm và xem tin tức trên mạng qua điện thoại."},{"type":"compound","zh":"虽然李教授已经六十岁了，但是他心态很好，看起来依然很年轻。","pinyin":"Suīrán Lǐ jiàoshòu yǐjīng liùshí suì le, dànshì tā xīntài hěn hǎo, kànqǐlái yīrán hěn niánqīng.","vi":"Tuy giáo sư Lý đã 60 tuổi rồi nhưng tinh thần ông rất lạc quan, trông vẫn còn rất trẻ."}],"related":[{"hanzi":"年","pinyin":"nián","vi":"Năm/Tuổi"},{"hanzi":"老","pinyin":"lǎo","vi":"Già"},{"hanzi":"轻","pinyin":"qīng","vi":"Nhẹ"},{"hanzi":"年龄","pinyin":"niánlíng","vi":"Tuổi tác"},{"hanzi":"老人","pinyin":"lǎorén","vi":"Người già"}],"traditional":"年輕"},{"id":"胖","hanzi":"胖","pinyin":"pàng","meaning_vi":"béo, mập","explanation":"Bộ nguyệt ⺼(cơ thể) + 半. Đối nghĩa với 瘦 (gầy).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🐼","examples":[{"type":"basic","zh":"这只小猫有点儿胖。","pinyin":"Zhè zhī xiǎomāo yǒudiǎnr pàng.","vi":"Chú mèo nhỏ này hơi béo một chút."},{"type":"simple","zh":"因为最近每天吃很多甜食又不运动，所以我胖了三公斤。","pinyin":"Yīnwèi zuìjìn měitiān chī hěn duō tiánshí yòu bú yùndòng, suǒyǐ wǒ pàngle sān gōngjīn.","vi":"Vì dạo này ngày nào cũng ăn nhiều đồ ngọt lại không vận động nên tôi đã béo lên 3 kg."},{"type":"compound","zh":"医生说太胖对身体不好，建议他平时少吃肉、多吃蔬菜和水果。","pinyin":"Yīshēng shuō tài pàng duì shēntǐ bù hǎo, jiànyì tā píngshí shǎo chī ròu, duō chī shūcài hé shuǐguǒ.","vi":"Bác sĩ nói béo quá không tốt cho sức khỏe, khuyên anh ấy bình thường ăn ít thịt, ăn nhiều rau và trái cây."}],"related":[{"hanzi":"瘦","pinyin":"shòu","vi":"Gầy"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"矮","pinyin":"ǎi","vi":"Thấp"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"}]},{"id":"瘦","hanzi":"瘦","pinyin":"shòu","meaning_vi":"gầy, ốm","explanation":"Bộ nạch 疒+ 叟. Đối nghĩa với 胖 (béo).","hsk_level":2,"tags":["tinh-tu","con-nguoi"],"image":"🦒","examples":[{"type":"basic","zh":"他比以前瘦了。","pinyin":"Tā bǐ yǐqián shòu le.","vi":"Anh ấy gầy hơn trước đây rồi."},{"type":"simple","zh":"我姐姐每天坚持跑步和游泳，现在身材变得又健康又瘦。","pinyin":"Wǒ jiějie měitiān jiānchí pǎobù hé yóuyǒng, xiànzài shēncái biànde yòu jiànkāng yòu shòu.","vi":"Chị gái tôi ngày nào cũng kiên trì chạy bộ và bơi lội, giờ vóc dáng trở nên vừa khỏe mạnh vừa thon gọn."},{"type":"compound","zh":"因为前段时间生病住院，没什么胃口吃饭，所以他整个人瘦了一圈。","pinyin":"Yīnwèi qiánduàn shíjiān shēngbìng zhùyuàn, méi shénme wèikǒu chīfàn, suǒyǐ tā zhěng gerén shòule yìquān.","vi":"Vì thời gian trước bị ốm nằm viện, không có khẩu vị ăn uống nên cả người anh ấy gầy đi một vòng."}],"related":[{"hanzi":"胖","pinyin":"pàng","vi":"Béo"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"},{"hanzi":"矮","pinyin":"ǎi","vi":"Thấp"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"}]},{"id":"健康","hanzi":"健康","pinyin":"jiànkāng","meaning_vi":"khỏe mạnh, sức khỏe","explanation":"健 (khỏe) + 康 (an khang). Vừa là tính từ vừa là danh từ.","hsk_level":2,"tags":["tinh-tu","suc-khoe"],"image":"🥗","examples":[{"type":"basic","zh":"祝你身体健康！","pinyin":"Zhù nǐ shēntǐ jiànkāng!","vi":"Chúc bạn sức khỏe dồi dào!"},{"type":"simple","zh":"多吃新鲜蔬菜、早睡早起是保持身体健康的好习惯。","pinyin":"Duō chī xīnxiān shūcài, zǎo shuì zǎoqǐ shì bǎochí shēntǐ jiànkāng de hǎo xíguàn.","vi":"Ăn nhiều rau tươi, ngủ sớm dậy sớm là thói quen tốt để giữ gìn sức khỏe."},{"type":"compound","zh":"虽然工作和赚钱很重要，但是如果没有健康的身体，一切都没有意义。","pinyin":"Suīrán gōngzuò hé zhuànqián hěn zhòngyào, dànshì rúguǒ méiyǒu jiànkāng de shēntǐ, yíqiè dōu méiyǒu yìyì.","vi":"Tuy công việc và kiếm tiền rất quan trọng nhưng nếu không có cơ thể khỏe mạnh thì tất cả đều vô nghĩa."}],"related":[{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể/Sức khỏe"},{"hanzi":"运动","pinyin":"yùndòng","vi":"Vận động"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Thoải mái"},{"hanzi":"医疗","pinyin":"yīliáo","vi":"Y tế"}]},{"id":"舒服","hanzi":"舒服","pinyin":"shūfu","meaning_vi":"thoải mái, dễ chịu","explanation":"舒 (thư giãn) + 服 (thích ứng).","hsk_level":2,"tags":["tinh-tu","suc-khoe"],"image":"😌","examples":[{"type":"basic","zh":"今天我有点儿不舒服。","pinyin":"Jīntiān wǒ yǒudiǎnr bù shūfu.","vi":"Hôm nay tôi hơi không khỏe một chút."},{"type":"simple","zh":"这双新买的运动鞋非常合脚，穿起来特别舒服。","pinyin":"Zhè shuāng xīn mǎi de yùndòngxié fēicháng héjiǎo, chuān qǐlái tèbié shūfu.","vi":"Đôi giày thể thao mới mua này rất vừa chân, đi vào đặc biệt thoải mái."},{"type":"compound","zh":"因为昨天晚上着凉感冒了，所以我今天觉得头疼、浑身都不舒服。","pinyin":"Yīnwèi zuótiān wǎnshang zháoliáng gǎnmào le, suǒyǐ wǒ jīntiān juéde tóuténg, húnshēn dōu bù shūfu.","vi":"Vì tối hôm qua bị nhiễm lạnh cảm cúm nên hôm nay tôi thấy đau đầu, khắp người đều khó chịu."}],"related":[{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"Khỏe mạnh"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"凉快","pinyin":"liángkuai","vi":"Mát mẻ"},{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"Ấm áp"}]},{"id":"清楚","hanzi":"清楚","pinyin":"qīngchu","meaning_vi":"rõ ràng","explanation":"清 (trong sạch) + 楚 (rành mạch). Dùng trong 听清楚 (nghe rõ), 写清楚 (viết rõ).","hsk_level":2,"tags":["tinh-tu"],"image":"👓","examples":[{"type":"basic","zh":"我听清楚了。","pinyin":"Wǒ tīng qīngchu le.","vi":"Tôi nghe rõ rồi."},{"type":"simple","zh":"黑板上的字写得太小了，坐在后面的同学看不清楚。","pinyin":"Hēibǎn shang de zì xiě de tài xiǎo le, zuò zài hòumiàn de tóngxué kànbùqīng chu.","vi":"Chữ trên bảng đen viết nhỏ quá, các bạn ngồi phía sau nhìn không rõ."},{"type":"compound","zh":"请你把电话号码再说一遍，刚才信号不好，我没听清楚。","pinyin":"Qǐng nǐ bǎ diànhuà hàomǎ zàishuō yíbiàn, gāngcái xìnhào bù hǎo, wǒ méi tīng qīngchu.","vi":"Xin bạn hãy đọc lại số điện thoại thêm lần nữa, vừa nãy sóng yếu tôi nghe không rõ."}],"related":[{"hanzi":"明白","pinyin":"míngbai","vi":"Hiểu rõ"},{"hanzi":"懂","pinyin":"dǒng","vi":"Hiểu"},{"hanzi":"清洁","pinyin":"qīngjié","vi":"Sạch sẽ"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"模糊","pinyin":"móhu","vi":"Mơ hồ"}]},{"id":"简单","hanzi":"简单","pinyin":"jiǎndān","meaning_vi":"đơn giản","explanation":"简 (giản lược) + 单 (đơn chiếc). Đối nghĩa với 复杂 (phức tạp).","hsk_level":2,"tags":["tinh-tu","hoc-tap"],"image":"👌","examples":[{"type":"basic","zh":"这个问题很简单。","pinyin":"Zhè ge wèntí hěn jiǎndān.","vi":"Câu hỏi này rất đơn giản."},{"type":"simple","zh":"今天的考试题目比较简单，我只用了半个小时就做完了。","pinyin":"Jīntiān de kǎoshì tímù bǐjiào jiǎndān, wǒ zhǐ yòngle bàn ge xiǎoshí jiù zuò wánle.","vi":"Đề thi hôm nay tương đối đơn giản, tôi chỉ mất nửa tiếng đồng hồ là làm xong."},{"type":"compound","zh":"虽然做西红柿炒鸡蛋的步骤很简单，但是想要做得好吃也需要技巧。","pinyin":"Suīrán zuò xīhóngshì chǎojīdàn de bùzhòu hěn jiǎndān, dànshì xiǎngyào zuò de hǎochī yě xūyào jìqiǎo.","vi":"Tuy các bước làm món trứng xào cà chua rất đơn giản nhưng muốn làm ngon cũng cần bí quyết."}],"related":[{"hanzi":"容易","pinyin":"róngyì","vi":"Dễ dàng"},{"hanzi":"复杂","pinyin":"fùzá","vi":"Phức tạp"},{"hanzi":"难","pinyin":"nán","vi":"Khó"},{"hanzi":"菜单","pinyin":"càidān","vi":"Thực đơn"},{"hanzi":"简介","pinyin":"jiǎnjiè","vi":"Giới thiệu tóm tắt"}],"traditional":"簡單"},{"id":"重要","hanzi":"重要","pinyin":"zhòngyào","meaning_vi":"quan trọng","explanation":"重 (nặng/trọng) + 要 (cần thiết).","hsk_level":2,"tags":["tinh-tu"],"image":"❗","examples":[{"type":"basic","zh":"这件事很重要。","pinyin":"Zhè jiàn shì hěn zhòngyào.","vi":"Việc này rất quan trọng."},{"type":"simple","zh":"学习外语的时候，每天坚持练习听力和口语非常重要。","pinyin":"Xuéxí wàiyǔ de shíhou, měitiān jiānchí liànxí tīnglì hé kǒuyǔ fēicháng zhòngyào.","vi":"Khi học ngoại ngữ, việc kiên trì luyện nghe và nói mỗi ngày là vô cùng quan trọng."},{"type":"compound","zh":"因为明天上午有一个非常重要的会议，所以我今天晚上要早点儿休息。","pinyin":"Yīnwèi míngtiān shàngwǔ yǒu yí ge fēicháng zhòngyào de huìyì, suǒyǐ wǒ jīntiān wǎnshang yào zǎodiǎnr xiūxi.","vi":"Vì sáng mai có một cuộc họp vô cùng quan trọng nên tối nay tôi phải nghỉ ngơi sớm một chút."}],"related":[{"hanzi":"要","pinyin":"yào","vi":"Cần/Muốn"},{"hanzi":"主要","pinyin":"zhǔyào","vi":"Chủ yếu"},{"hanzi":"需要","pinyin":"xūyào","vi":"Cần thiết"},{"hanzi":"重","pinyin":"zhòng","vi":"Nặng/Trọng"},{"hanzi":"问题","pinyin":"wèntí","vi":"Vấn đề"}]},{"id":"特别","hanzi":"特别","pinyin":"tèbié","meaning_vi":"đặc biệt","explanation":"特 + 别 (khác). Vừa là tính từ vừa là phó từ chỉ mức độ cao.","hsk_level":2,"tags":["tinh-tu","pho-tu"],"image":"⭐","examples":[{"type":"basic","zh":"今天天气特别好。","pinyin":"Jīntiān tiānqì tèbié hǎo.","vi":"Hôm nay thời tiết đặc biệt đẹp."},{"type":"simple","zh":"我妈妈做的红烧鱼味道特别鲜美，客人们都很喜欢吃。","pinyin":"Wǒ māma zuò de hóngshāo yú wèidào tèbié xiānměi, kèrénmen dōu hěn xǐhuan chī.","vi":"Món cá kho mẹ tôi nấu hương vị đặc biệt tươi ngon, khách khứa đều rất thích ăn."},{"type":"compound","zh":"虽然这家小店看起来很普通，但是他们卖的牛肉面条却特别有名。","pinyin":"Suīrán zhè jiā xiǎodiàn kànqǐlái hěn pǔtōng, dànshì tāmen mài de niúròu miàntiáo què tèbié yǒumíng.","vi":"Tuy quán nhỏ này trông rất bình thường nhưng mì thịt bò họ bán lại đặc biệt nổi tiếng."}],"related":[{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"},{"hanzi":"别","pinyin":"bié","vi":"Khác/Đừng"},{"hanzi":"特殊","pinyin":"tèshū","vi":"Đặc thù"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"Đặc điểm"},{"hanzi":"一般","pinyin":"yìbān","vi":"Bình thường"}],"traditional":"特別"},{"id":"一般","hanzi":"一般","pinyin":"yìbān","meaning_vi":"bình thường, thông thường","explanation":"一 (một) + 般 (loại). Dùng để đánh giá mức độ trung bình hoặc thói quen chung.","hsk_level":2,"tags":["tinh-tu","pho-tu"],"image":"😐","examples":[{"type":"basic","zh":"这个电影很一般。","pinyin":"Zhè ge diànyǐng hěn yìbān.","vi":"Bộ phim này rất bình thường."},{"type":"simple","zh":"我每天晚上一般十一点左右睡觉，早上六点半起床。","pinyin":"Wǒ měitiān wǎnshang yìbān shí yīdiǎn zuǒyòu shuìjiào, zǎoshang liù diǎn bàn qǐchuáng.","vi":"Mỗi tối tôi thường đi ngủ vào khoảng 11 giờ và thức dậy lúc 6 giờ rưỡi sáng."},{"type":"compound","zh":"虽然这家饭店的环境很一般，但是因为价格便宜、分量又足，所以学生很多。","pinyin":"Suīrán zhè jiā fàndiàn de huánjìng hěn yìbān, dànshì yīnwèi jiàgé piányi, fènliàng yòu zú, suǒyǐ xuésheng hěn duō.","vi":"Tuy không gian nhà hàng này rất bình thường nhưng vì giá rẻ, suất ăn lại đầy đặn nên rất đông sinh viên."}],"related":[{"hanzi":"普通","pinyin":"pǔtōng","vi":"Phổ thông"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"特别","pinyin":"tèbié","vi":"Đặc biệt"},{"hanzi":"搬","pinyin":"bān","vi":"Chuyển"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"}]},{"id":"一样","hanzi":"一样","pinyin":"yíyàng","meaning_vi":"giống nhau, như nhau","explanation":"一 (một) + 样 (kiểu dáng). Dùng trong cấu trúc A 跟 B 一样.","hsk_level":2,"tags":["tinh-tu"],"image":"👯","examples":[{"type":"basic","zh":"我们两个一样高。","pinyin":"Wǒmen liǎng ge yíyàng gāo.","vi":"Hai chúng tôi cao bằng nhau."},{"type":"simple","zh":"我买的这件白色衬衫跟我姐姐那件的颜色一模一样。","pinyin":"Wǒ mǎi de zhè jiàn báisè chènshān gēn wǒ jiějie nà jiàn de yánsè yìmúyíyàng.","vi":"Chiếc áo sơ mi trắng tôi mua có màu sắc giống hệt chiếc của chị gái tôi."},{"type":"compound","zh":"虽然我们来自不同的国家，但是大家喜欢中国文化的心情是一样的。","pinyin":"Suīrán wǒmen láizì bùtóng de guójiā, dànshì dàjiā xǐhuan Zhōngguó wénhuà de xīnqíng shì yíyàng de.","vi":"Tuy chúng tôi đến từ các quốc gia khác nhau nhưng tình cảm yêu thích văn hóa Trung Quốc của mọi người là như nhau."}],"related":[{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Tương đồng"},{"hanzi":"不同","pinyin":"bùtóng","vi":"Khác nhau"},{"hanzi":"一般","pinyin":"yìbān","vi":"Bình thường"},{"hanzi":"怎么样","pinyin":"zěnmeyàng","vi":"Thế nào"},{"hanzi":"比","pinyin":"bǐ","vi":"So với"}],"traditional":"一樣"},{"id":"不同","hanzi":"不同","pinyin":"bùtóng","meaning_vi":"không giống, khác nhau","explanation":"不 (không) + 同 (giống nhau).","hsk_level":2,"tags":["tinh-tu"],"image":"🔀","examples":[{"type":"basic","zh":"我们的意见不同。","pinyin":"Wǒmen de yìjiàn bùtóng.","vi":"Ý kiến của chúng tôi khác nhau."},{"type":"simple","zh":"不同国家的人在饮食习惯和文化传统上都有很大的区别。","pinyin":"Bùtóng guójiā de rén zài yǐnshí xíguàn hé wénhuà chuántǒng Shangdōu yǒu hěn dà de qūbié.","vi":"Người ở các quốc gia khác nhau đều có sự khác biệt lớn về thói quen ăn uống và truyền thống văn hóa."},{"type":"compound","zh":"虽然双胞胎兄弟长得非常像，但是他们的性格和爱好却完全不同。","pinyin":"Suīrán shuāngbāotāi xiōngdì zhǎngde fēicháng xiàng, dànshì tāmen de xìnggé hé àihào què wánquán bùtóng.","vi":"Tuy hai anh em sinh đôi trông rất giống nhau nhưng tính cách và sở thích của họ lại hoàn toàn khác nhau."}],"related":[{"hanzi":"相同","pinyin":"xiāngtóng","vi":"Giống nhau"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Như nhau"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"同学","pinyin":"tóngxué","vi":"Bạn học"},{"hanzi":"同事","pinyin":"tóngshì","vi":"Đồng nghiệp"}]},{"id":"相同","hanzi":"相同","pinyin":"xiāngtóng","meaning_vi":"giống nhau, tương đồng","explanation":"相 (lẫn nhau) + 同 (cùng).","hsk_level":2,"tags":["tinh-tu"],"image":"🟰","examples":[{"type":"basic","zh":"我们的爱好相同。","pinyin":"Wǒmen de àihào xiāngtóng.","vi":"Sở thích của chúng tôi giống nhau."},{"type":"simple","zh":"这两个汉字的读音完全相同，但是意思却不一样。","pinyin":"Zhè liǎng ge hànzì de dúyīn wánquán xiāngtóng, dànshì yìsi què bù yíyàng.","vi":"Cách đọc của hai chữ Hán này hoàn toàn giống nhau nhưng ý nghĩa lại không giống nhau."},{"type":"compound","zh":"因为我们两个人有很多相同的兴趣爱好，所以很快就成了好朋友。","pinyin":"Yīnwèi wǒmen liǎng ge rén yǒu hěn duō xiāngtóng de xìngqù àihào, suǒyǐ hěn kuài jiù chéngle hǎopéngyou.","vi":"Vì hai chúng tôi có rất nhiều sở thích giống nhau nên chẳng mấy chốc đã trở thành bạn thân."}],"related":[{"hanzi":"不同","pinyin":"bùtóng","vi":"Khác nhau"},{"hanzi":"一样","pinyin":"yíyàng","vi":"Giống nhau"},{"hanzi":"相信","pinyin":"xiāngxìn","vi":"Tin tưởng"},{"hanzi":"互相","pinyin":"hùxiāng","vi":"Lẫn nhau"},{"hanzi":"同学","pinyin":"tóngxué","vi":"Bạn học"}]},{"id":"方便","hanzi":"方便","pinyin":"fāngbiàn","meaning_vi":"thuận tiện, tiện lợi","explanation":"方 (phương hướng) + 便 (tiện).","hsk_level":2,"tags":["tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"这里交通很方便。","pinyin":"Zhèlǐ jiāotōng hěn fāngbiàn.","vi":"Giao thông ở đây rất thuận tiện."},{"type":"simple","zh":"我家附近有地铁站、超市和医院，生活非常方便。","pinyin":"Wǒ jiā fùjìn yǒu dìtiězhàn, chāoshì hé yīyuàn, shēnghuó fēicháng fāngbiàn.","vi":"Gần nhà tôi có ga tàu điện ngầm, siêu thị và bệnh viện, sinh hoạt vô cùng thuận tiện."},{"type":"compound","zh":"现在用手机支付买东西非常方便，出门甚至不用带现金了。","pinyin":"Xiànzài yòng shǒujī zhīfù mǎidōngxi fēicháng fāngbiàn, chūmén shènzhì bú yòng dài xiànjīn le.","vi":"Hiện nay dùng điện thoại thanh toán khi mua đồ vô cùng tiện lợi, ra ngoài thậm chí không cần mang tiền mặt."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"Rẻ"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"方法","pinyin":"fāngfǎ","vi":"Phương pháp"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"Tùy ý"}]},{"id":"安全","hanzi":"安全","pinyin":"ānquán","meaning_vi":"an toàn","explanation":"安 (bình an) + 全 (toàn vẹn). Đối nghĩa với 危险 (nguy hiểm).","hsk_level":2,"tags":["tinh-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"这里非常安全。","pinyin":"Zhèlǐ fēicháng ānquán.","vi":"Ở đây vô cùng an toàn."},{"type":"simple","zh":"坐汽车或者出租车的时候，大家一定要记得系好安全带。","pinyin":"Zuò qìchē huòzhě chūzūchē de shíhou, dàjiā yídìngyào jìde jì hǎo ānquándài.","vi":"Khi ngồi ô tô hoặc taxi, mọi người nhất định phải nhớ thắt dây an toàn."},{"type":"compound","zh":"虽然骑自行车速度没有汽车快，但是在堵车的时候既安全又环保。","pinyin":"Suīrán qí zìxíngchē sùdù méiyǒu qìchē kuài, dànshì zài dǔchē de shíhou jì ānquán yòu huánbǎo.","vi":"Tuy đi xe đạp tốc độ không nhanh bằng ô tô nhưng lúc tắc đường lại vừa an toàn vừa bảo vệ môi trường."}],"related":[{"hanzi":"危险","pinyin":"wēixiǎn","vi":"Nguy hiểm"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"安心","pinyin":"ānxīn","vi":"An tâm"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"平安","pinyin":"píng'ān","vi":"Bình an"}]},{"id":"危险","hanzi":"危险","pinyin":"wēixiǎn","meaning_vi":"nguy hiểm","explanation":"危 (nguy) + 险 (hiểm trở). Đối nghĩa với 安全 (an toàn).","hsk_level":2,"tags":["tinh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"马路上车多，很危险。","pinyin":"Mǎlù shangchē duō, hěn wēixiǎn.","vi":"Trên đường nhiều xe cộ, rất nguy hiểm."},{"type":"simple","zh":"夏天不要一个人去没有安全保护的河里游泳，那样太危险了。","pinyin":"Xiàtiān bú yào yígerén qù méiyǒu ānquán bǎohù de hé lǐ yóuyǒng, nàyàng tài wēixiǎn le.","vi":"Mùa hè đừng đi bơi một mình ở sông không có bảo hộ an toàn, như vậy nguy hiểm quá."},{"type":"compound","zh":"虽然爬这座高山非常危险，但是仍然有很多运动员想要挑战自己。","pinyin":"Suīrán pá zhè zuò gāoshān fēicháng wēixiǎn, dànshì réngrán yǒu hěn duō yùndòngyuán xiǎngyào tiǎozhàn zìjǐ.","vi":"Tuy leo ngọn núi cao này vô cùng nguy hiểm nhưng vẫn có rất nhiều vận động viên muốn thử thách bản thân."}],"related":[{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"保险","pinyin":"bǎoxiǎn","vi":"Bảo hiểm"},{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"Mạo hiểm"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"Cẩn thận"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"}],"traditional":"危險"},{"id":"安静","hanzi":"安静","pinyin":"ānjìng","meaning_vi":"yên tĩnh","explanation":"安 (yên ổn) + 静 (tĩnh lặng).","hsk_level":2,"tags":["tinh-tu"],"image":"🤫","examples":[{"type":"basic","zh":"图书馆里很安静。","pinyin":"Túshūguǎn lǐ hěn ānjìng.","vi":"Trong thư viện rất yên tĩnh."},{"type":"simple","zh":"老师走进教室以后，同学们立刻安静下来准备听课。","pinyin":"Lǎoshī zǒujìn jiàoshì yǐhòu, tóngxuémen lìkè ānjìng xiàlái zhǔnbèi tīngkè.","vi":"Sau khi thầy giáo bước vào phòng học, các bạn học sinh lập tức giữ yên lặng chuẩn bị nghe giảng."},{"type":"compound","zh":"因为我喜欢安静的环境，所以我每天晚上都在自己的房间里看书学习。","pinyin":"Yīnwèi wǒ xǐhuan ānjìng de huánjìng, suǒyǐ wǒ měitiān wǎnshang dōu zài zìjǐ de fángjiān lǐ kànshū xuéxí.","vi":"Vì tôi thích môi trường yên tĩnh nên mỗi tối tôi đều đọc sách và học tập trong phòng riêng của mình."}],"related":[{"hanzi":"热闹","pinyin":"rènao","vi":"Náo nhiệt"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"Bình tĩnh"},{"hanzi":"环境","pinyin":"huánjìng","vi":"Môi trường"}],"traditional":"安靜"},{"id":"热闹","hanzi":"热闹","pinyin":"rènao","meaning_vi":"náo nhiệt, nhộn nhịp","explanation":"热 (nóng) + 闹 (ồn ào vui vẻ).","hsk_level":2,"tags":["tinh-tu"],"image":"🎉","examples":[{"type":"basic","zh":"春节的时候街上很热闹。","pinyin":"Chūnjié de shíhou jiēshang hěn rènao.","vi":"Dịp Tết trên phố rất náo nhiệt."},{"type":"simple","zh":"周末市中心的超市和电影院里人来人往，非常热闹。","pinyin":"Zhōumò shìzhōngxīn de chāoshì hé diànyǐngyuàn lǐrén lái rén wǎng, fēicháng rènao.","vi":"Cuối tuần siêu thị và rạp chiếu phim ở trung tâm thành phố người qua kẻ lại vô cùng náo nhiệt."},{"type":"compound","zh":"今天是爷爷七十大寿，全家人欢聚一堂，家里显得特别热闹。","pinyin":"Jīntiān shì yéye qīshí dàshòu, quán jiārén huānjùyìtáng, jiālǐ xiǎnde tèbié rènao.","vi":"Hôm nay là lễ mừng thọ 70 tuổi của ông nội, cả nhà sum họp đông đủ, trong nhà trông đặc biệt náo nhiệt."}],"related":[{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"Nhiệt tình"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"开心","pinyin":"kāixīn","vi":"Vui vẻ"}],"traditional":"熱鬧"},{"id":"甜","hanzi":"甜","pinyin":"tián","meaning_vi":"ngọt","explanation":"舌 (cái lưỡi) + 甘 (ngọt) → lưỡi nếm thấy vị ngọt.","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"🍬","examples":[{"type":"basic","zh":"这个西瓜真甜！","pinyin":"Zhè ge xīguā zhēn tián!","vi":"Quả dưa hấu này ngọt thật đấy!"},{"type":"simple","zh":"妈妈买的红苹果和葡萄又新鲜又甜，大家都爱吃。","pinyin":"Māma mǎi de hóng píngguǒ hé pútao yòu xīnxiān yòu tián, dàjiā dōu ài chī.","vi":"Táo đỏ và nho mẹ mua vừa tươi vừa ngọt, ai cũng thích ăn."},{"type":"compound","zh":"虽然蛋糕和巧克力吃起来很甜，但是吃太多对牙齿和身体不好。","pinyin":"Suīrán dàngāo hé qiǎokèlì chī qǐlái hěn tián, dànshì chī tài duō duì yáchǐ hé shēntǐ bù hǎo.","vi":"Tuy bánh ngọt và sô cô la ăn vào rất ngọt nhưng ăn nhiều quá thì không tốt cho răng và sức khỏe."}],"related":[{"hanzi":"酸","pinyin":"suān","vi":"Chua"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"辣","pinyin":"là","vi":"Cay"},{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"西瓜","pinyin":"xīguā","vi":"Dưa hấu"}]},{"id":"辣","hanzi":"辣","pinyin":"là","meaning_vi":"cay","explanation":"辛 (cay/vất vả) + 束.","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"🌶️","examples":[{"type":"basic","zh":"我不喜欢吃辣的菜。","pinyin":"Wǒ bù xǐhuan chī là de cài.","vi":"Tôi không thích ăn món cay."},{"type":"simple","zh":"四川菜和湖南菜非常有特色，味道通常又麻又辣。","pinyin":"Sìchuāncài hé Húnán cài fēicháng yǒu tèsè, wèidào tōngcháng yòu má yòu là.","vi":"Món Tứ Xuyên và món Hồ Nam vô cùng đặc sắc, hương vị thường vừa tê vừa cay."},{"type":"compound","zh":"虽然我以前一点儿辣也不能吃，但是在中国生活了一年以后已经习惯了。","pinyin":"Suīrán wǒ yǐqián yìdiǎnr là yě bù néng chī, dànshì zài Zhōngguó shēnghuóle yì nián yǐhòu yǐjīng xíguàn le.","vi":"Tuy trước đây tôi một chút cay cũng không ăn được nhưng sau khi sống ở Trung Quốc một năm thì đã quen rồi."}],"related":[{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"酸","pinyin":"suān","vi":"Chua"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"}]},{"id":"咸","hanzi":"咸","pinyin":"xián","meaning_vi":"mặn","explanation":"Chỉ vị mặn của muối trong món ăn.","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"🧂","examples":[{"type":"basic","zh":"这个菜有点儿咸。","pinyin":"Zhè ge cài yǒudiǎnr xián.","vi":"Món ăn này hơi mặn một chút."},{"type":"simple","zh":"因为今天做菜的时候盐放多了，所以汤喝起来有点儿咸。","pinyin":"Yīnwèi jīntiān zuòcài de shíhou yán fàng duō le, suǒyǐ tāng hē qǐlái yǒudiǎnr xián.","vi":"Vì hôm nay lúc nấu ăn cho nhiều muối quá nên canh uống vào hơi mặn."},{"type":"compound","zh":"医生建议老人平时吃饭不要吃太咸，清淡一点儿对身体更健康。","pinyin":"Yīshēng jiànyì lǎorén píngshí chīfàn bú yào chī tài xián, qīngdàn yìdiǎnr duì shēntǐ gèng jiànkāng.","vi":"Bác sĩ khuyên người lớn tuổi bình thường ăn uống đừng ăn quá mặn, thanh đạm một chút sẽ tốt cho sức khỏe hơn."}],"related":[{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"辣","pinyin":"là","vi":"Cay"},{"hanzi":"酸","pinyin":"suān","vi":"Chua"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"渴","pinyin":"kě","vi":"Khát nước"}],"traditional":"鹹"},{"id":"酸","hanzi":"酸","pinyin":"suān","meaning_vi":"chua; mỏi, nhức (cơ thể)","explanation":"Bộ dậu 酉 + 夋. Dùng cho vị chua (酸奶 - sữa chua) hoặc mỏi cơ.","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"🍋","examples":[{"type":"basic","zh":"这个苹果有点儿酸。","pinyin":"Zhè ge píngguǒ yǒudiǎnr suān.","vi":"Quả táo này hơi chua một chút."},{"type":"simple","zh":"我每天早上早饭后都会喝一杯酸奶，帮助消化。","pinyin":"Wǒ měitiān zǎoshang zǎofàn hòu dōuhuì hē yì bēi suānnǎi, bāngzhù xiāohuà.","vi":"Mỗi sáng sau bữa ăn sáng tôi đều uống một cốc sữa chua để hỗ trợ tiêu hóa."},{"type":"compound","zh":"昨天去爬山走了太多路，今天早上起床觉得两条腿又酸又疼。","pinyin":"Zuótiān qù páshān zǒule tài duō lù, jīntiān zǎoshang qǐchuáng juéde liǎng tiáo tuǐ yòu suān yòu téng.","vi":"Hôm qua đi leo núi đi bộ nhiều quá, sáng nay thức dậy cảm thấy hai chân vừa mỏi vừa đau."}],"related":[{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"辣","pinyin":"là","vi":"Cay"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"酸奶","pinyin":"suānnǎi","vi":"Sữa chua"}]},{"id":"苦","hanzi":"苦","pinyin":"kǔ","meaning_vi":"đắng; khổ, vất vả","explanation":"Bộ thảo 艹+ 古 (cổ/xưa).","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"☕","examples":[{"type":"basic","zh":"这杯黑咖啡很苦。","pinyin":"Zhè bēi hēikāfēi hěn kǔ.","vi":"Cốc cà phê đen này rất đắng."},{"type":"simple","zh":"虽然中药喝起来非常苦，但是对治病很有效果。","pinyin":"Suīrán zhōngyào hē qǐlái fēicháng kǔ, dànshì duì zhìbìng hěn yǒu xiàoguǒ.","vi":"Tuy thuốc Bắc uống vào vô cùng đắng nhưng lại rất có hiệu quả chữa bệnh."},{"type":"compound","zh":"爸爸经常教育我们，只有不怕吃苦、努力学习，将来才能过上好生活。","pinyin":"Bàba jīngcháng jiàoyù wǒmen, zhǐyǒu bú pà chīkǔ, nǔlì xuéxí, jiānglái cáinéngguò shànghǎo shēnghuó.","vi":"Bố thường dạy bảo chúng tôi, chỉ có không sợ gian khổ, chăm chỉ học tập thì tương lai mới có cuộc sống tốt."}],"related":[{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"酸","pinyin":"suān","vi":"Chua"},{"hanzi":"辣","pinyin":"là","vi":"Cay"},{"hanzi":"咸","pinyin":"xián","vi":"Mặn"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"Vất vả"}]},{"id":"新鲜","hanzi":"新鲜","pinyin":"xīnxiān","meaning_vi":"tươi, tươi mới","explanation":"新 (mới) + 鲜 (tươi ngon, 鱼 + 羊).","hsk_level":2,"tags":["tinh-tu","an-uong"],"image":"🥬","examples":[{"type":"basic","zh":"这些水果很新鲜。","pinyin":"Zhèxiē shuǐguǒ hěn xīnxiān.","vi":"Những trái cây này rất tươi."},{"type":"simple","zh":"奶奶每天早上都去早市买最新鲜的蔬菜和鱼。","pinyin":"Nǎinai měitiān zǎo Shangdōu qù zǎoshì mǎi zuì xīnxiān de shūcài hé yú.","vi":"Bà nội mỗi sáng đều đi chợ sớm mua rau củ và cá tươi ngon nhất."},{"type":"compound","zh":"下过雨以后，公园里的空气特别新鲜，所以很多老人都去那里散步。","pinyin":"Xiàguo yǔ yǐhòu, gōngyuán lǐ de kōngqì tèbié xīnxiān, suǒyǐ hěn duō lǎorén dōu qù nàlǐ sànbù.","vi":"Sau khi mưa, không khí trong công viên đặc biệt trong lành nên nhiều người già đều ra đó đi dạo."}],"related":[{"hanzi":"新","pinyin":"xīn","vi":"Mới"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"Hải sản"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"Trái cây"},{"hanzi":"菜","pinyin":"cài","vi":"Rau/Món ăn"},{"hanzi":"旧","pinyin":"jiù","vi":"Cũ"}],"traditional":"新鮮"},{"id":"晴","hanzi":"晴","pinyin":"qíng","meaning_vi":"nắng, trời quang","explanation":"Bộ nhật 日 (mặt trời) + 青 (xanh trong).","hsk_level":2,"tags":["tinh-tu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"今天是晴天。","pinyin":"Jīntiān shì qíngtiān.","vi":"Hôm nay là ngày nắng."},{"type":"simple","zh":"昨天还下着大雨，今天早上天气就转晴了。","pinyin":"Zuótiān hái xiàzhe dàyǔ, jīntiān zǎoshang tiānqì jiù zhuǎn qíng le.","vi":"Hôm qua trời vẫn còn mưa to, sáng nay thời tiết đã chuyển nắng rồi."},{"type":"compound","zh":"因为周末天气预报说是晴天，所以我们全家决定去海边旅游。","pinyin":"Yīnwèi zhōumò tiānqì yùbào shuō shì qíngtiān, suǒyǐ wǒmen quánjiā juédìng qù hǎibiān lǚyóu.","vi":"Vì dự báo thời tiết cuối tuần nói trời nắng nên cả nhà tôi quyết định đi biển du lịch."}],"related":[{"hanzi":"阴","pinyin":"yīn","vi":"Âm u"},{"hanzi":"晴天","pinyin":"qíngtiān","vi":"Ngày nắng"},{"hanzi":"太阳","pinyin":"tàiyáng","vi":"Mặt trời"},{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"Mắt"}]},{"id":"阴","hanzi":"阴","pinyin":"yīn","meaning_vi":"âm u, nhiều mây, râm","explanation":"Bộ phụ 阝+ 月 (mặt trăng).","hsk_level":2,"tags":["tinh-tu","thoi-tiet"],"image":"☁️","examples":[{"type":"basic","zh":"今天天阴了，可能要下雨。","pinyin":"Jīntiān tiān yīn le, kěnéng yào xiàyǔ.","vi":"Hôm nay trời âm u rồi, có lẽ sắp mưa."},{"type":"simple","zh":"上午还是大晴天，到了下午突然变成阴天了。","pinyin":"Shàngwǔ háishi dà qíngtiān, dàole xiàwǔ tūrán biànchéng yīntiān le.","vi":"Buổi sáng vẫn còn nắng to, đến buổi chiều đột nhiên chuyển sang trời nhiều mây âm u."},{"type":"compound","zh":"虽然今天是阴天，没有太阳，但是温度不冷不热，非常适合爬山。","pinyin":"Suīrán jīntiān shì yīntiān, méiyǒu tàiyáng, dànshì wēndù bù lěng bú rè, fēicháng shìhé páshān.","vi":"Tuy hôm nay trời âm u không có nắng nhưng nhiệt độ không lạnh cũng không nóng, rất thích hợp leo núi."}],"related":[{"hanzi":"晴","pinyin":"qíng","vi":"Nắng"},{"hanzi":"阴天","pinyin":"yīntiān","vi":"Trời râm"},{"hanzi":"云","pinyin":"yún","vi":"Mây"},{"hanzi":"下雨","pinyin":"xiàyǔ","vi":"Trời mưa"},{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"}],"traditional":"陰"},{"id":"凉快","hanzi":"凉快","pinyin":"liángkuai","meaning_vi":"mát mẻ","explanation":"凉 (mát, bộ băng 冫) + 快 (sảng khoái).","hsk_level":2,"tags":["tinh-tu","thoi-tiet"],"image":"🍃","examples":[{"type":"basic","zh":"秋天的天气很凉快。","pinyin":"Qiūtiān de tiānqì hěn liángkuai.","vi":"Thời tiết mùa thu rất mát mẻ."},{"type":"simple","zh":"晚上吃完饭以后，去公园的树下乘凉非常凉快。","pinyin":"Wǎnshang chīwán fàn yǐhòu, qù gōngyuán de shù xià chéngliáng fēicháng liángkuai.","vi":"Buổi tối sau khi ăn cơm xong, ra dưới tán cây công viên hóng mát vô cùng mát mẻ."},{"type":"compound","zh":"因为房间里开着空调，所以外面虽然很热，里面却非常凉快。","pinyin":"Yīnwèi fángjiān lǐ kāizhe kōngtiáo, suǒyǐ wàimiàn suīrán hěn rè, lǐmiàn què fēicháng liángkuai.","vi":"Vì trong phòng đang bật điều hòa nên tuy bên ngoài rất nóng nhưng bên trong lại vô cùng mát mẻ."}],"related":[{"hanzi":"暖和","pinyin":"nuǎnhuo","vi":"Ấm áp"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"风","pinyin":"fēng","vi":"Gió"}],"traditional":"涼快"},{"id":"暖和","hanzi":"暖和","pinyin":"nuǎnhuo","meaning_vi":"ấm áp","explanation":"暖 (ấm, bộ nhật 日) + 和 (hài hòa).","hsk_level":2,"tags":["tinh-tu","thoi-tiet"],"image":"🧣","examples":[{"type":"basic","zh":"春天来了，天气暖和了。","pinyin":"Chūntiān lái le, tiānqì nuǎnhuo le.","vi":"Mùa xuân đến rồi, thời tiết ấm áp rồi."},{"type":"simple","zh":"我妈妈给我买了一件新羽绒服，穿起来非常暖和。","pinyin":"Wǒ māma gěi wǒ mǎile yí jiàn xīn yǔróngfú, chuān qǐlái fēicháng nuǎnhuo.","vi":"Mẹ tôi mua cho tôi một chiếc áo phao mới, mặc vào vô cùng ấm áp."},{"type":"compound","zh":"虽然外面正在下雪，但是因为家里有暖气，所以房间里很暖和。","pinyin":"Suīrán wàimiàn zhèngzài xiàxuě, dànshì yīnwèi jiālǐ yǒu nuǎnqì, suǒyǐ fángjiān lǐ hěn nuǎnhuo.","vi":"Tuy bên ngoài đang có tuyết rơi nhưng vì trong nhà có hệ thống sưởi nên trong phòng rất ấm."}],"related":[{"hanzi":"凉快","pinyin":"liángkuai","vi":"Mát mẻ"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"和平","pinyin":"hépíng","vi":"Hòa bình"}]},{"id":"蓝","hanzi":"蓝","pinyin":"lán","meaning_vi":"màu xanh dương, xanh lam","explanation":"Bộ thảo 艹+ 监 (cây chàm dùng để nhuộm màu xanh).","hsk_level":2,"tags":["tinh-tu","mau-sac"],"image":"🟦","examples":[{"type":"basic","zh":"今天的天空真蓝！","pinyin":"Jīntiān de tiānkōng zhēn lán!","vi":"Bầu trời hôm nay xanh thật đấy!"},{"type":"simple","zh":"我弟弟最喜欢蓝色的书包和蓝色的运动鞋。","pinyin":"Wǒ dìdi zuì xǐhuan lánsè de shūbāo hé lánsè de yùndòngxié.","vi":"Em trai tôi thích nhất chiếc cặp sách màu xanh dương và đôi giày thể thao màu xanh dương."},{"type":"compound","zh":"晴天的时候，大海的水看起来像蓝宝石一样漂亮。","pinyin":"Qíngtiān de shíhou, dàhǎi de shuǐ kànqǐlái xiàng lánbǎoshí yíyàng piàoliang.","vi":"Vào ngày nắng, nước biển trông đẹp tựa như viên ngọc sapphire xanh lam."}],"related":[{"hanzi":"绿","pinyin":"lǜ","vi":"Xanh lá"},{"hanzi":"黄","pinyin":"huáng","vi":"Vàng"},{"hanzi":"白","pinyin":"bái","vi":"Trắng"},{"hanzi":"黑","pinyin":"hēi","vi":"Đen"},{"hanzi":"红","pinyin":"hóng","vi":"Đỏ"}],"traditional":"藍"},{"id":"绿","hanzi":"绿","pinyin":"lǜ","meaning_vi":"màu xanh lá cây","explanation":"Bộ mịch 纟+ 录.","hsk_level":2,"tags":["tinh-tu","mau-sac"],"image":"🟩","examples":[{"type":"basic","zh":"春天树叶变绿了。","pinyin":"Chūntiān shùyè biàn lǜ le.","vi":"Mùa xuân lá cây chuyển sang màu xanh."},{"type":"simple","zh":"过马路的时候，一定要等绿灯亮了再走。","pinyin":"Guòmǎlù de shíhou, yídìngyào děng lǜdēng liàngle zài zǒu.","vi":"Khi sang đường, nhất định phải đợi đèn xanh bật sáng rồi mới đi."},{"type":"compound","zh":"我爷爷非常喜欢喝绿茶，每天早上都要泡一杯清香的龙井绿茶。","pinyin":"Wǒ yéye fēicháng xǐhuan hē lǜchá, měitiān zǎo Shangdōu yào pào yì bēi qīngxiāng de Lóngjǐng lǜchá.","vi":"Ông nội tôi vô cùng thích uống trà xanh, mỗi sáng đều pha một cốc trà xanh Long Tỉnh thơm ngát."}],"related":[{"hanzi":"蓝","pinyin":"lán","vi":"Xanh dương"},{"hanzi":"黄","pinyin":"huáng","vi":"Vàng"},{"hanzi":"红","pinyin":"hóng","vi":"Đỏ"},{"hanzi":"绿茶","pinyin":"lǜchá","vi":"Trà xanh"},{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"}],"traditional":"綠"},{"id":"黄","hanzi":"黄","pinyin":"huáng","meaning_vi":"màu vàng","explanation":"Chỉ màu vàng (黄河 - Hoàng Hà, 黄色 - màu vàng).","hsk_level":2,"tags":["tinh-tu","mau-sac"],"image":"🟨","examples":[{"type":"basic","zh":"秋天树叶变黄了。","pinyin":"Qiūtiān shùyè biàn huángle.","vi":"Mùa thu lá cây chuyển sang màu vàng."},{"type":"simple","zh":"妹妹穿着一条黄色的裙子。","pinyin":"Mèimei chuānzhe yì tiáo huángsè de qúnzi.","vi":"Em gái đang mặc một chiếc váy màu vàng."},{"type":"compound","zh":"桌子上的那个黄色笔记本是我昨天在学校门口的商店买的。","pinyin":"Zhuōzi shang de nà ge huángsè bǐjìběn shì wǒ zuótiān zài xuéxiào ménkǒu de shāngdiàn mǎi de.","vi":"Quyển sổ tay màu vàng trên bàn kia là tôi mua ở cửa hàng cổng trường hôm qua."}],"related":[{"hanzi":"红","pinyin":"hóng","vi":"Đỏ"},{"hanzi":"蓝","pinyin":"lán","vi":"Xanh dương"},{"hanzi":"绿","pinyin":"lǜ","vi":"Xanh lá"},{"hanzi":"白","pinyin":"bái","vi":"Trắng"},{"hanzi":"黑","pinyin":"hēi","vi":"Đen"}],"traditional":"黃"},{"id":"满意","hanzi":"满意","pinyin":"mǎnyì","meaning_vi":"hài lòng, vừa ý","explanation":"满 (đầy đủ) + 意 (ý muốn).","hsk_level":2,"tags":["tinh-tu","cam-xuc"],"image":"😊","examples":[{"type":"basic","zh":"我对结果很满意。","pinyin":"Wǒ duì jiéguǒ hěn mǎnyì.","vi":"Tôi rất hài lòng với kết quả."},{"type":"simple","zh":"妈妈对姐姐新找的这份工作感到非常满意。","pinyin":"Māma duì jiějie xīn zhǎo de zhè fèn gōngzuò gǎndào fēicháng mǎnyì.","vi":"Mẹ cảm thấy vô cùng hài lòng với công việc mới tìm được này của chị gái."},{"type":"compound","zh":"虽然这次考试成绩还不错，但是我自己并不是很满意，下次还要更努力。","pinyin":"Suīrán zhè cì kǎoshì chéngjì hái búcuò, dànshì wǒ zìjǐ bìngbú shì hěn mǎnyì, xiàcì hái yào gèng nǔlì.","vi":"Tuy điểm thi lần này khá ổn nhưng bản thân tôi vẫn chưa thực sự hài lòng, lần sau phải cố gắng hơn nữa."}],"related":[{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"意思","pinyin":"yìsi","vi":"Ý nghĩa"},{"hanzi":"愿意","pinyin":"yuànyì","vi":"Bằng lòng"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"Vui mừng"},{"hanzi":"服务","pinyin":"fúwù","vi":"Phục vụ"}],"traditional":"滿意"},{"id":"有名","hanzi":"有名","pinyin":"yǒumíng","meaning_vi":"nổi tiếng","explanation":"有 (có) + 名 (tên tuổi).","hsk_level":2,"tags":["tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"北京烤鸭很有名。","pinyin":"Běijīngkǎoyā hěn yǒumíng.","vi":"Vịt quay Bắc Kinh rất nổi tiếng."},{"type":"simple","zh":"长城和故宫都是中国非常有名的地方，每年都有很多游客。","pinyin":"Chángchéng hé gùgōng dōu shì Zhōngguó fēicháng yǒumíng de dìfang, měinián dōu yǒu hěn duō yóukè.","vi":"Vạn Lý Trường Thành và Cố Cung đều là những địa danh vô cùng nổi tiếng của Trung Quốc, hằng năm đều có rất đông du khách."},{"type":"compound","zh":"虽然这家饭店开在一条小胡同里，但是做的菜特别正宗，在当地非常有名。","pinyin":"Suīrán zhè jiā fàndiàn kāi zài yì tiáo xiǎo hútòng lǐ, dànshì zuò de cài tèbié zhèngzōng, zài dāngdì fēicháng yǒumíng.","vi":"Tuy nhà hàng này mở trong một con ngõ nhỏ nhưng món ăn nấu đặc biệt chuẩn vị, ở địa phương vô cùng nổi tiếng."}],"related":[{"hanzi":"名字","pinyin":"míngzi","vi":"Tên"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"Nổi tiếng"},{"hanzi":"有","pinyin":"yǒu","vi":"Có"},{"hanzi":"有意思","pinyin":"yǒuyìsi","vi":"Thú vị"},{"hanzi":"名词","pinyin":"míngcí","vi":"Danh từ"}]},{"id":"公司","hanzi":"公司","pinyin":"gōngsī","meaning_vi":"công ty","explanation":"公 (công cộng) + 司 (quản lý).","hsk_level":2,"tags":["danh-tu","cong-viec","dia-diem"],"image":"🏢","examples":[{"type":"basic","zh":"我爸爸在一家大公司工作。","pinyin":"Wǒ bàba zài yìjiā dàgōngsī gōngzuò.","vi":"Bố tôi làm việc ở một công ty lớn."},{"type":"simple","zh":"我们公司每天早上九点上班，下午六点下班。","pinyin":"Wǒmen gōngsī měitiān zǎoshang jiǔ diǎn shàngbān, xiàwǔ liù diǎn xiàbān.","vi":"Công ty chúng tôi mỗi sáng 9 giờ vào làm, 6 giờ chiều tan làm."},{"type":"compound","zh":"因为这家公司的福利很好、同事也很友好，所以大家都喜欢在这里工作。","pinyin":"Yīnwèi zhè jiā gōngsī de fúlì hěn hǎo, tóngshì yě hěn yǒuhǎo, suǒyǐ dàjiā dōu xǐhuan zài zhèlǐ gōngzuò.","vi":"Vì phúc lợi của công ty này rất tốt, đồng nghiệp cũng thân thiện nên ai cũng thích làm việc ở đây."}],"related":[{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"Văn phòng"},{"hanzi":"司机","pinyin":"sījī","vi":"Tài xế"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"上班","pinyin":"shàngbān","vi":"Đi làm"},{"hanzi":"同事","pinyin":"tóngshì","vi":"Đồng nghiệp"}]},{"id":"办公室","hanzi":"办公室","pinyin":"bàngōngshì","meaning_vi":"văn phòng","explanation":"办公 (làm việc công) + 室 (phòng).","hsk_level":2,"tags":["danh-tu","cong-viec","dia-diem"],"image":"💼","examples":[{"type":"basic","zh":"王老师在办公室里。","pinyin":"Wáng lǎoshī zài bàngōngshì lǐ.","vi":"Thầy Vương đang ở trong văn phòng."},{"type":"simple","zh":"如果你有问题想问老师，下课以后可以去二楼的办公室找他。","pinyin":"Rúguǒ nǐ yǒu wèntí xiǎng wèn lǎoshī, xiàkè yǐhòu kěyǐ qù èr lóu de bàngōngshì zhǎo tā.","vi":"Nếu bạn có câu hỏi muốn hỏi thầy giáo, sau khi tan học có thể lên văn phòng tầng 2 tìm thầy."},{"type":"compound","zh":"虽然已经下班了，但是李经理还在办公室里认真准备明天的会议资料。","pinyin":"Suīrán yǐjīng xiàbān le, dànshì Lǐ jīnglǐ hái zài bàngōngshì lǐ rènzhēn zhǔnbèi míngtiān de huìyì zīliào.","vi":"Tuy đã tan làm rồi nhưng giám đốc Lý vẫn đang ở trong văn phòng chăm chỉ chuẩn bị tài liệu họp cho ngày mai."}],"related":[{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"教室","pinyin":"jiàoshì","vi":"Phòng học"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"办公","pinyin":"bàngōng","vi":"Làm việc văn phòng"},{"hanzi":"老师","pinyin":"lǎoshī","vi":"Giáo viên"}],"traditional":"辦公室"},{"id":"教室","hanzi":"教室","pinyin":"jiàoshì","meaning_vi":"phòng học, lớp học","explanation":"教 (dạy học) + 室 (phòng).","hsk_level":2,"tags":["danh-tu","hoc-tap","dia-diem"],"image":"🏫","examples":[{"type":"basic","zh":"同学们都在教室里学习。","pinyin":"Tóngxuémen dōu zài jiàoshì lǐ xuéxí.","vi":"Các bạn học đều đang học tập trong phòng học."},{"type":"simple","zh":"我们的教室非常宽敞明亮，里面有空调和多媒体设备。","pinyin":"Wǒmen de jiàoshì fēicháng kuānchǎng míngliàng, lǐmiàn yǒukōng tiáohé duōméitǐ shèbèi.","vi":"Phòng học của chúng tôi vô cùng rộng rãi sáng sủa, bên trong có điều hòa và thiết bị đa phương tiện."},{"type":"compound","zh":"每天早上八点以前，值日生都会提前到教室把黑板擦干净。","pinyin":"Měitiān zǎoshang bā diǎn yǐqián, zhírìshēng dōuhuì tíqián dào jiàoshì bǎ hēi bǎncā gānjìng.","vi":"Mỗi sáng trước 8 giờ, bạn trực nhật đều đến lớp sớm để lau sạch bảng đen."}],"related":[{"hanzi":"教","pinyin":"jiāo","vi":"Dạy học"},{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"Văn phòng"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"Trường học"},{"hanzi":"上课","pinyin":"shàngkè","vi":"Lên lớp"},{"hanzi":"学生","pinyin":"xuésheng","vi":"Học sinh"}]},{"id":"图书馆","hanzi":"图书馆","pinyin":"túshūguǎn","meaning_vi":"thư viện","explanation":"图书 (sách báo) + 馆 (nhà lớn/cơ sở).","hsk_level":2,"tags":["danh-tu","hoc-tap","dia-diem"],"image":"📚","examples":[{"type":"basic","zh":"我去图书馆借书。","pinyin":"Wǒqù túshūguǎn jièshū.","vi":"Tôi đi thư viện mượn sách."},{"type":"simple","zh":"周末的时候，很多大学生都喜欢去图书馆看书和写论文。","pinyin":"Zhōumò de shíhou, hěn duōdà xuésheng dōu xǐhuan qù túshūguǎn kànshū hé xiě lùnwén.","vi":"Vào cuối tuần, nhiều sinh viên đại học đều thích đến thư viện đọc sách và viết luận văn."},{"type":"compound","zh":"因为图书馆里非常安静，学习气氛也很好，所以我每天晚自习都去那里。","pinyin":"Yīnwèi túshūguǎn lǐ fēicháng ānjìng, xuéxí qìfēn yě hěn hǎo, suǒyǐ wǒ měitiān wǎnzìxí dōu qù nàlǐ.","vi":"Vì trong thư viện vô cùng yên tĩnh, không khí học tập cũng rất tốt nên tối nào tự học tôi cũng đến đó."}],"related":[{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"宾馆","pinyin":"bīnguǎn","vi":"Khách sạn"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"借","pinyin":"jiè","vi":"Mượn"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"Trường học"}],"traditional":"圖書館"},{"id":"超市","hanzi":"超市","pinyin":"chāoshì","meaning_vi":"siêu thị","explanation":"Viết tắt của 超级市场 (siêu cấp thị trường).","hsk_level":2,"tags":["danh-tu","mua-sam","dia-diem"],"image":"🛒","examples":[{"type":"basic","zh":"妈妈去超市买水果了。","pinyin":"Māma qù chāoshì mǎi shuǐguǒ le.","vi":"Mẹ đi siêu thị mua trái cây rồi."},{"type":"simple","zh":"我家楼下就有一家大型超市，里面的东西种类非常齐全。","pinyin":"Wǒ jiā lóuxià jiù yǒu yìjiā dàxíng chāoshì, lǐmiàn de dōngxi zhǒnglèi fēicháng qíquán.","vi":"Ngay dưới lầu nhà tôi có một siêu thị lớn, hàng hóa bên trong chủng loại vô cùng đầy đủ."},{"type":"compound","zh":"因为周末超市经常有打折活动，所以很多人都会去那里买生活用品。","pinyin":"Yīnwèi zhōumò chāoshì jīngcháng yǒu dǎzhé huódòng, suǒyǐ hěn duō rén dōuhuì qù nàlǐ mǎi shēnghuó yòngpǐn.","vi":"Vì cuối tuần siêu thị thường có chương trình giảm giá nên nhiều người đều đến đó mua đồ dùng sinh hoạt."}],"related":[{"hanzi":"商店","pinyin":"shāngdiàn","vi":"Cửa hàng"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"},{"hanzi":"东西","pinyin":"dōngxi","vi":"Đồ đạc"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"Chợ"}]},{"id":"公园","hanzi":"公园","pinyin":"gōngyuán","meaning_vi":"công viên","explanation":"公 (công cộng) + 园 (khu vườn).","hsk_level":2,"tags":["danh-tu","dia-diem","giai-tri"],"image":"🌳","examples":[{"type":"basic","zh":"公园里有很多花和树。","pinyin":"Gōngyuán lǐ yǒu hěn duō huā hé shù.","vi":"Trong công viên có rất nhiều hoa và cây."},{"type":"simple","zh":"每天早上都有很多老人在公园里打太极拳和散步。","pinyin":"Měitiān zǎo Shangdōu yǒu hěn duō lǎorén zài gōngyuán lǐ dǎ tàijíquán hé sànbù.","vi":"Mỗi sáng đều có nhiều người già tập Thái Cực Quyền và đi dạo trong công viên."},{"type":"compound","zh":"如果明天天气晴朗、不刮风的话，我们就一起去公园划船吧。","pinyin":"Rúguǒ míngtiān tiānqì qínglǎng, bù guāfēng dehuà, wǒmen jiù yìqǐ qù gōngyuán huáchuán ba.","vi":"Nếu ngày mai trời quang đãng, không có gió thì chúng ta cùng đi công viên chèo thuyền nhé."}],"related":[{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"公共汽车","pinyin":"gōnggòngqìchē","vi":"Xe buýt"},{"hanzi":"花园","pinyin":"huāyuán","vi":"Vườn hoa"},{"hanzi":"散步","pinyin":"sànbù","vi":"Đi dạo"},{"hanzi":"玩","pinyin":"wán","vi":"Chơi"}],"traditional":"公園"},{"id":"宾馆","hanzi":"宾馆","pinyin":"bīnguǎn","meaning_vi":"khách sạn, nhà khách","explanation":"宾 (khách quý) + 馆 (nhà lưu trú).","hsk_level":2,"tags":["danh-tu","du-lich","dia-diem"],"image":"🏨","examples":[{"type":"basic","zh":"我们住在那家宾馆。","pinyin":"Wǒmen zhùzài nà jiā bīnguǎn.","vi":"Chúng tôi ở tại khách sạn đó."},{"type":"simple","zh":"这家宾馆离火车站很近，房间也非常干净舒适。","pinyin":"Zhè jiā bīnguǎn lí huǒchēzhàn hěn jìn, fángjiān yě fēicháng gānjìng shūshì.","vi":"Khách sạn này cách ga tàu hỏa rất gần, phòng ốc cũng vô cùng sạch sẽ thoải mái."},{"type":"compound","zh":"因为旅游旺季房间很紧张，所以我们最好提前在网上预订宾馆。","pinyin":"Yīnwèi lǚyóu wàngjì fángjiān hěn jǐnzhāng, suǒyǐ wǒmen zuìhǎo tíqián zài wǎngshang yùdìng bīnguǎn.","vi":"Vì mùa cao điểm du lịch phòng ốc rất khan hiếm nên tốt nhất chúng ta đặt trước khách sạn trên mạng."}],"related":[{"hanzi":"饭店","pinyin":"fàndiàn","vi":"Nhà hàng/Khách sạn"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"住","pinyin":"zhù","vi":"Ở"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"}],"traditional":"賓館"},{"id":"地铁","hanzi":"地铁","pinyin":"dìtiě","meaning_vi":"tàu điện ngầm","explanation":"地 (mặt đất) + 铁 (đường sắt) → đường sắt ngầm dưới đất.","hsk_level":2,"tags":["danh-tu","giao-thong"],"image":"🚇","examples":[{"type":"basic","zh":"我每天坐地铁去上班。","pinyin":"Wǒ měitiān zuò dìtiě qù shàngbān.","vi":"Mỗi ngày tôi đi tàu điện ngầm đi làm."},{"type":"simple","zh":"北京和上海的地铁非常发达，去哪里都很方便。","pinyin":"Běijīng hé Shànghǎi de dìtiě fēicháng fādá, qù nǎlǐ dōu hěn fāngbiàn.","vi":"Tàu điện ngầm ở Bắc Kinh và Thượng Hải vô cùng phát triển, đi đâu cũng rất tiện."},{"type":"compound","zh":"上下班高峰期路上经常堵车，所以坐地铁比坐公共汽车快得多。","pinyin":"Shàngxiàbān gāofēngqī lùshang jīngcháng dǔchē, suǒyǐ zuò dìtiě bǐ zuò gōnggòngqìchē kuài de duō.","vi":"Giờ cao điểm đi làm và tan làm trên đường thường tắc xe nên đi tàu điện ngầm nhanh hơn xe buýt nhiều."}],"related":[{"hanzi":"火车","pinyin":"huǒchē","vi":"Tàu hỏa"},{"hanzi":"公共汽车","pinyin":"gōnggòngqìchē","vi":"Xe buýt"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"铁","pinyin":"tiě","vi":"Sắt"},{"hanzi":"坐","pinyin":"zuò","vi":"Đi/Ngồi"}],"traditional":"地鐵"},{"id":"公共汽车","hanzi":"公共汽车","pinyin":"gōnggòngqìchē","meaning_vi":"xe buýt","explanation":"公共 (công cộng) + 汽车 (xe ô tô).","hsk_level":2,"tags":["danh-tu","giao-thong"],"image":"🚌","examples":[{"type":"basic","zh":"公共汽车站就在前面。","pinyin":"Gōnggòng qìchēzhàn jiù zài qiánmiàn.","vi":"Trạm xe buýt nằm ngay phía trước."},{"type":"simple","zh":"从我家坐公共汽车到学校大概需要三十分钟。","pinyin":"Cóng wǒ jiā zuò gōnggòngqìchē dào xuéxiào dàgài xūyào sānshí fēnzhōng.","vi":"Đi xe buýt từ nhà tôi đến trường mất khoảng 30 phút."},{"type":"compound","zh":"虽然坐公共汽车票价很便宜，但是遇到堵车的时候就会比较慢。","pinyin":"Suīrán zuò gōnggòngqìchē piàojià hěn piányi, dànshì yùdào dǔchē de shíhou jiù huì bǐjiào màn.","vi":"Tuy giá vé xe buýt rất rẻ nhưng khi gặp tắc đường thì sẽ tương đối chậm."}],"related":[{"hanzi":"汽车","pinyin":"qìchē","vi":"Xe ô tô"},{"hanzi":"出租车","pinyin":"chūzūchē","vi":"Xe taxi"},{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"Công viên"},{"hanzi":"车","pinyin":"chē","vi":"Xe"}],"traditional":"公共汽車"},{"id":"自行车","hanzi":"自行车","pinyin":"zìxíngchē","meaning_vi":"xe đạp","explanation":"自行 (tự đi) + 车 (xe).","hsk_level":2,"tags":["danh-tu","giao-thong"],"image":"🚲","examples":[{"type":"basic","zh":"他每天骑自行车上学。","pinyin":"Tā měitiān qí zìxíngchē shàngxué.","vi":"Mỗi ngày cậu ấy đạp xe đạp đi học."},{"type":"simple","zh":"爸爸给我买了一辆蓝色的自行车作为生日礼物。","pinyin":"Bàba gěi wǒ mǎile yí liàng lánsè de zìxíngchē zuòwéi shēngrì lǐwù.","vi":"Bố đã mua tặng tôi một chiếc xe đạp màu xanh dương làm quà sinh nhật."},{"type":"compound","zh":"骑自行车不仅能锻炼身体，而且对保护环境也很有好处。","pinyin":"Qí zìxíngchē bùjǐn néng duànliàn shēntǐ, érqiě duì bǎohù huánjìng yě hěn yǒu hǎochu.","vi":"Đi xe đạp không chỉ rèn luyện sức khỏe mà còn rất có lợi cho việc bảo vệ môi trường."}],"related":[{"hanzi":"骑","pinyin":"qí","vi":"Cưỡi/Đạp xe"},{"hanzi":"车","pinyin":"chē","vi":"Xe"},{"hanzi":"汽车","pinyin":"qìchē","vi":"Ô tô"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"Tự mình"},{"hanzi":"行","pinyin":"xíng","vi":"Đi/Được"}],"traditional":"自行車"},{"id":"船","hanzi":"船","pinyin":"chuán","meaning_vi":"thuyền, tàu thủy","explanation":"Bộ chu 舟 (con thuyền) + 㕣.","hsk_level":2,"tags":["danh-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"我们坐船去那个岛。","pinyin":"Wǒmen zuò chuán qù nà ge dǎo.","vi":"Chúng tôi đi thuyền tới hòn đảo đó."},{"type":"simple","zh":"周末的时候，很多游客喜欢在公园的湖上划船。","pinyin":"Zhōumò de shíhou, hěn duō yóukè xǐhuan zài gōngyuán de hú shang huáchuán.","vi":"Vào cuối tuần, nhiều du khách thích chèo thuyền trên hồ trong công viên."},{"type":"compound","zh":"虽然坐船的速度比坐飞机慢得多，但是在船上可以欣赏美丽的海景。","pinyin":"Suīrán zuò chuán de sùdù bǐ zuòfēijī màn de duō, dànshì zài chuán shang kěyǐ xīnshǎng měilì de hǎijǐng.","vi":"Tuy tốc độ đi tàu thủy chậm hơn đi máy bay nhiều nhưng trên tàu có thể ngắm cảnh biển tuyệt đẹp."}],"related":[{"hanzi":"飞机","pinyin":"fēijī","vi":"Máy bay"},{"hanzi":"火车","pinyin":"huǒchē","vi":"Tàu hỏa"},{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"河","pinyin":"hé","vi":"Sông"},{"hanzi":"坐","pinyin":"zuò","vi":"Ngồi/Đi"}]},{"id":"票","hanzi":"票","pinyin":"piào","meaning_vi":"vé","explanation":"Dùng cho 火车票 (vé tàu), 飞机票 (vé máy bay), 电影票 (vé xem phim).","hsk_level":2,"tags":["danh-tu","giao-thong","du-lich"],"image":"🎫","examples":[{"type":"basic","zh":"我买了两张电影票。","pinyin":"Wǒ mǎile liǎng zhāng diànyǐngpiào.","vi":"Tôi đã mua hai vé xem phim."},{"type":"simple","zh":"现在用手机在网上买火车票和飞机票都非常方便。","pinyin":"Xiànzài yòng shǒujī zài wǎngshang mǎi huǒchēpiào hé fēijīpiào dōu fēicháng fāngbiàn.","vi":"Hiện nay dùng điện thoại mua vé tàu hỏa và vé máy bay trên mạng đều vô cùng tiện lợi."},{"type":"compound","zh":"因为春节期间回家的人特别多，所以火车票一定要提前预订。","pinyin":"Yīnwèi Chūnjié qījiān huíjiā de rén tèbié duō, suǒyǐ huǒchēpiào yídìngyào tíqián yùdìng.","vi":"Vì dịp Tết người về quê đặc biệt đông nên vé tàu hỏa nhất định phải đặt trước."}],"related":[{"hanzi":"火车票","pinyin":"huǒchēpiào","vi":"Vé tàu hỏa"},{"hanzi":"电影票","pinyin":"diànyǐngpiào","vi":"Vé xem phim"},{"hanzi":"买","pinyin":"mǎi","vi":"Mua"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","vi":"Ga tàu hỏa"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"}]},{"id":"护照","hanzi":"护照","pinyin":"hùzhào","meaning_vi":"hộ chiếu","explanation":"护 (bảo vệ) + 照 (giấy chứng nhận).","hsk_level":2,"tags":["danh-tu","du-lich"],"image":"🛂","examples":[{"type":"basic","zh":"出国旅游要带护照。","pinyin":"Chūguó lǚyóu yào dài hùzhào.","vi":"Đi du lịch nước ngoài phải mang theo hộ chiếu."},{"type":"simple","zh":"办理机场登机手续的时候，工作人员需要检查你的护照和机票。","pinyin":"Bànlǐ jīchǎng dēngjī shǒuxù de shíhou, gōngzuò rényuán xūyào jiǎnchá nǐ de hùzhào hé jīpiào.","vi":"Khi làm thủ tục lên máy bay ở sân bay, nhân viên cần kiểm tra hộ chiếu và vé máy bay của bạn."},{"type":"compound","zh":"护照是我们在国外最重要的身份证件，一定要放好，千万别弄丢了。","pinyin":"Hùzhào shì wǒmen zài guówài zuì zhòngyào de shēnfèn zhèngjiàn, yídìngyào fàng hǎo, qiānwàn bié nòngdiū le.","vi":"Hộ chiếu là giấy tờ tùy thân quan trọng nhất của chúng ta ở nước ngoài, nhất định phải cất kỹ, đừng để mất."}],"related":[{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"照顾","pinyin":"zhàogu","vi":"Chăm sóc"},{"hanzi":"照片","pinyin":"zhàopiàn","vi":"Bức ảnh"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"}],"traditional":"護照"},{"id":"地图","hanzi":"地图","pinyin":"dìtú","meaning_vi":"bản đồ","explanation":"地 (đất/địa lý) + 图 (hình vẽ).","hsk_level":2,"tags":["danh-tu","du-lich"],"image":"🗺️","examples":[{"type":"basic","zh":"我在看北京地图。","pinyin":"Wǒ zài kàn Běijīng dìtú.","vi":"Tôi đang xem bản đồ Bắc Kinh."},{"type":"simple","zh":"去一个陌生的城市旅游时，手机里的电子地图非常有帮助。","pinyin":"Qù yí ge mòshēng de chéngshì lǚyóu shí, shǒujī lǐ de diànzǐ dìtú fēicháng yǒubāngzhù.","vi":"Khi đi du lịch ở một thành phố xa lạ, bản đồ điện tử trong điện thoại giúp ích rất nhiều."},{"type":"compound","zh":"虽然我第一次来北京，但是看着地图，我很快就找到了去故宫的路。","pinyin":"Suīrán wǒ dìyīcì lái Běijīng, dànshì kànzhe dìtú, wǒ hěn kuài jiù zhǎodàole qù gùgōng de lù.","vi":"Tuy đây là lần đầu tôi đến Bắc Kinh nhưng nhìn theo bản đồ tôi đã nhanh chóng tìm được đường đi Cố Cung."}],"related":[{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"},{"hanzi":"找","pinyin":"zhǎo","vi":"Tìm"}],"traditional":"地圖"},{"id":"行李箱","hanzi":"行李箱","pinyin":"xínglixiāng","meaning_vi":"vali hành lý","explanation":"行李 (hành lý) + 箱 (cái hòm/thùng).","hsk_level":2,"tags":["danh-tu","du-lich","do-vat"],"image":"🧳","examples":[{"type":"basic","zh":"这个行李箱很重。","pinyin":"Zhè ge xínglixiāng hěn zhòng.","vi":"Chiếc vali hành lý này rất nặng."},{"type":"simple","zh":"姐姐已经把去中国留学要带的衣服和书都放进行李箱了。","pinyin":"Jiějie yǐjīng bǎ qù Zhōngguó liúxué yào dài de yīfu hé shū dōu fàngjìn xínglixiāng le.","vi":"Chị gái đã xếp hết quần áo và sách vở cần mang đi du học Trung Quốc vào vali rồi."},{"type":"compound","zh":"因为这个行李箱太大了，不能带上飞机，所以必须办理托运。","pinyin":"Yīnwèi zhè ge xínglixiāng tài dà le, bù néng dàishàng fēijī, suǒyǐ bìxū bànlǐ tuōyùn.","vi":"Vì chiếc vali này to quá không thể xách tay lên máy bay nên bắt buộc phải làm thủ tục ký gửi."}],"related":[{"hanzi":"行李","pinyin":"xíngli","vi":"Hành lý"},{"hanzi":"冰箱","pinyin":"bīngxiāng","vi":"Tủ lạnh"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"Sân bay"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"Chuẩn bị"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"Du lịch"}]},{"id":"春天","hanzi":"春天","pinyin":"chūntiān","meaning_vi":"mùa xuân","explanation":"春 (mùa xuân) + 天 (mùa/trời).","hsk_level":2,"tags":["danh-tu","thoi-gian","thoi-tiet"],"image":"🌸","examples":[{"type":"basic","zh":"春天花都开了。","pinyin":"Chūntiān Huādōu kāi le.","vi":"Mùa xuân hoa đều nở rồi."},{"type":"simple","zh":"春天的时候，天气不冷不热，树叶变绿了，非常漂亮。","pinyin":"Chūntiān de shíhou, tiānqì bù lěng bú rè, shùyè biàn lǜ le, fēicháng piàoliang.","vi":"Vào mùa xuân, thời tiết không lạnh không nóng, lá cây chuyển xanh, vô cùng đẹp."},{"type":"compound","zh":"春天来了，天气越来越暖和，所以很多人都去公园看花。","pinyin":"Chūntiān lái le, tiānqì yuèláiyuè nuǎnhuo, suǒyǐ hěn duō rén dōu qù gōngyuán kàn huā.","vi":"Mùa xuân đến rồi, thời tiết ngày càng ấm áp nên nhiều người đều đi công viên ngắm hoa."}],"related":[{"hanzi":"夏天","pinyin":"xiàtiān","vi":"Mùa hè"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"Mùa đông"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"季节","pinyin":"jìjié","vi":"Mùa"}]},{"id":"夏天","hanzi":"夏天","pinyin":"xiàtiān","meaning_vi":"mùa hè","explanation":"夏 (mùa hè) + 天 (mùa/trời).","hsk_level":2,"tags":["danh-tu","thoi-gian","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"夏天我喜欢去游泳。","pinyin":"Xiàtiān wǒ xǐhuan qù yóuyǒng.","vi":"Mùa hè tôi thích đi bơi."},{"type":"simple","zh":"北京的夏天白天很热，晚上去公园散步会比较凉快。","pinyin":"Běijīng de xiàtiān báitiān hěn rè, wǎnshang qù gōngyuán sànbù huì bǐjiào liángkuai.","vi":"Mùa hè ở Bắc Kinh ban ngày rất nóng, buổi tối ra công viên đi dạo sẽ tương đối mát mẻ."},{"type":"compound","zh":"虽然夏天的太阳很毒，但是因为有暑假，还可以吃冰西瓜，所以孩子们都很喜欢夏天。","pinyin":"Suīrán xiàtiān de tàiyáng hěn dú, dànshì yīnwèi yǒu shǔjià, hái kěyǐ chī bīng xīguā, suǒyǐ háizimen dōu hěn xǐhuan xiàtiān.","vi":"Tuy nắng mùa hè rất gắt nhưng vì có kỳ nghỉ hè và được ăn dưa hấu lạnh nên trẻ con đều rất thích mùa hè."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"Mùa đông"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"游泳","pinyin":"yóuyǒng","vi":"Bơi lội"}]},{"id":"秋天","hanzi":"秋天","pinyin":"qiūtiān","meaning_vi":"mùa thu","explanation":"秋 (mùa thu, bộ hòa 禾 + 火) + 天.","hsk_level":2,"tags":["danh-tu","thoi-gian","thoi-tiet"],"image":"🍁","examples":[{"type":"basic","zh":"北京的秋天最美。","pinyin":"Běijīng de qiūtiān zuì měi.","vi":"Mùa thu ở Bắc Kinh đẹp nhất."},{"type":"simple","zh":"秋天到了，天气变得很凉快，香山上的红叶吸引了无数游客。","pinyin":"Qiūtiān dào le, tiānqì biànde hěn liángkuai, xiāng shān shang de hóngyè xīyǐnle wúshù yóukè.","vi":"Mùa thu đến rồi, thời tiết trở nên mát mẻ, lá đỏ trên Hương Sơn thu hút vô số du khách."},{"type":"compound","zh":"我最喜欢秋天，因为秋天不冷也不热。","pinyin":"Wǒ zuì xǐhuan qiūtiān, yīnwèi qiūtiān bù lěng yě bú rè.","vi":"Tôi thích mùa thu nhất vì mùa thu không lạnh cũng không nóng."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"夏天","pinyin":"xiàtiān","vi":"Mùa hè"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"Mùa đông"},{"hanzi":"凉快","pinyin":"liángkuai","vi":"Mát mẻ"},{"hanzi":"季节","pinyin":"jìjié","vi":"Mùa"}]},{"id":"冬天","hanzi":"冬天","pinyin":"dōngtiān","meaning_vi":"mùa đông","explanation":"冬 (mùa đông) + 天 (mùa/trời).","hsk_level":2,"tags":["danh-tu","thoi-gian","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"北京的冬天很冷。","pinyin":"Běijīng de dōngtiān hěn lěng.","vi":"Mùa đông ở Bắc Kinh rất lạnh."},{"type":"simple","zh":"冬天一下雪，孩子们就会高兴地跑到外面去堆雪人。","pinyin":"Dōngtiān yí xiàxuě, háizimen jiù huì gāoxìng de pǎo dào wàimiàn qù duī xuěrén.","vi":"Mùa đông hễ có tuyết rơi là lũ trẻ lại vui mừng chạy ra ngoài đắp người tuyết."},{"type":"compound","zh":"虽然北方的冬天外面非常寒冷，但是房间里都有暖气，一点儿也不冷。","pinyin":"Suīrán běifāng de dōngtiān wàimiàn fēicháng hánlěng, dànshì fángjiān lǐ dōu yǒu nuǎnqì, yìdiǎnr yě bù lěng.","vi":"Tuy mùa đông miền Bắc bên ngoài vô cùng lạnh giá nhưng trong phòng đều có lò sưởi nên chẳng lạnh chút nào."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"夏天","pinyin":"xiàtiān","vi":"Mùa hè"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"冷","pinyin":"lěng","vi":"Lạnh"},{"hanzi":"雪","pinyin":"xuě","vi":"Tuyết"}]},{"id":"季节","hanzi":"季节","pinyin":"jìjié","meaning_vi":"mùa (trong năm)","explanation":"季 (mùa) + 节 (tiết khí).","hsk_level":2,"tags":["danh-tu","thoi-gian","thien-nhien"],"image":"🍂","examples":[{"type":"basic","zh":"一年有四个季节。","pinyin":"Yì nián yǒu sì ge jìjié.","vi":"Một năm có bốn mùa."},{"type":"simple","zh":"每个季节都有自己独特的风景，我最喜欢春天和秋天。","pinyin":"Měi ge jìjié dōu yǒu zìjǐ dútè de fēngjǐng, wǒ zuì xǐhuan chūntiān hé qiūtiān.","vi":"Mỗi mùa đều có phong cảnh độc đáo riêng, tôi thích nhất là mùa xuân và mùa thu."},{"type":"compound","zh":"因为每个季节的天气都不一样，所以我们要穿不同的衣服。","pinyin":"Yīnwèi měi ge jìjié de tiānqì dōu bù yíyàng, suǒyǐ wǒmen yào chuān bùtóng de yīfu.","vi":"Vì thời tiết mỗi mùa đều khác nhau nên chúng ta phải mặc quần áo khác nhau."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"夏天","pinyin":"xiàtiān","vi":"Mùa hè"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"Mùa thu"},{"hanzi":"冬天","pinyin":"dōngtiān","vi":"Mùa đông"},{"hanzi":"节日","pinyin":"jiérì","vi":"Ngày lễ"}],"traditional":"季節"},{"id":"云","hanzi":"云","pinyin":"yún","meaning_vi":"mây","explanation":"Chữ tượng hình làn mây bay trên trời.","hsk_level":2,"tags":["danh-tu","thien-nhien","thoi-tiet"],"image":"☁️","examples":[{"type":"basic","zh":"天上有很多白云。","pinyin":"Tiānshang yǒu hěn duō báiyún.","vi":"Trên trời có rất nhiều mây trắng."},{"type":"simple","zh":"晴天的时候，蓝蓝的天空上飘着几朵洁白的云，非常好看。","pinyin":"Qíngtiān de shíhou, lán lán de tiānkōng shang piāozhe jǐ duǒ jiébái de yún, fēicháng hǎokàn.","vi":"Vào ngày nắng, trên bầu trời xanh ngắt lững lờ trôi vài đám mây trắng muốt, vô cùng đẹp mắt."},{"type":"compound","zh":"刚才还是晴天，现在天上突然飘来了很多黑云，看来马上要下雨了。","pinyin":"Gāngcái háishi qíngtiān, xiànzài tiānshang tūrán piāo láile hěn duō hēi yún, kànlái mǎshàng yào xiàyǔ le.","vi":"Vừa nãy trời vẫn nắng, giờ trên trời đột nhiên kéo đến rất nhiều mây đen, xem ra sắp mưa rồi."}],"related":[{"hanzi":"天","pinyin":"tiān","vi":"Bầu trời"},{"hanzi":"雨","pinyin":"yǔ","vi":"Mưa"},{"hanzi":"雪","pinyin":"xuě","vi":"Tuyết"},{"hanzi":"晴","pinyin":"qíng","vi":"Nắng"},{"hanzi":"阴","pinyin":"yīn","vi":"Âm u"}],"traditional":"雲"},{"id":"晴天","hanzi":"晴天","pinyin":"qíngtiān","meaning_vi":"ngày nắng, trời nắng","explanation":"晴 (nắng, bộ nhật 日) + 天 (trời).","hsk_level":2,"tags":["danh-tu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"今天是个大晴天。","pinyin":"Jīntiān shì ge dà qíngtiān.","vi":"Hôm nay là một ngày nắng đẹp."},{"type":"simple","zh":"一到晴天，奶奶就会把被子拿到阳台上去晒太阳。","pinyin":"Yí dào qíngtiān, nǎinai jiù huì bǎ bèizi nádào yángtái shangqù shàitàiyáng.","vi":"Hễ đến ngày nắng là bà nội lại mang chăn ra ban công phơi nắng."},{"type":"compound","zh":"连续下了三天雨以后，今天终于迎来了晴天，大家的心情都变好了。","pinyin":"Liánxù xiàle sān tiān yǔ yǐhòu, jīntiān zhōngyú yíngláile qíngtiān, dàjiā de xīnqíng dōu biàn hǎo le.","vi":"Sau ba ngày mưa liên tiếp, hôm nay cuối cùng cũng đón ngày nắng đẹp, tâm trạng mọi người đều vui vẻ hơn."}],"related":[{"hanzi":"晴","pinyin":"qíng","vi":"Nắng"},{"hanzi":"阴天","pinyin":"yīntiān","vi":"Ngày râm"},{"hanzi":"天气","pinyin":"tiānqì","vi":"Thời tiết"},{"hanzi":"太阳","pinyin":"tàiyáng","vi":"Mặt trời"},{"hanzi":"下雨","pinyin":"xiàyǔ","vi":"Trời mưa"}]},{"id":"河","hanzi":"河","pinyin":"hé","meaning_vi":"sông, dòng sông","explanation":"Bộ thủy 氵+ 可.","hsk_level":2,"tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"我家前面有一条小河。","pinyin":"Wǒ jiā qiánmiàn yǒu yì tiáo xiǎohé.","vi":"Phía trước nhà tôi có một con sông nhỏ."},{"type":"simple","zh":"河水非常清澈，能看见很多小鱼在水里游来游去。","pinyin":"Héshuǐ fēicháng qīngchè, néng kànjiàn hěn duō xiǎo yú zài shuǐ lǐ yóu lái yóu qù.","vi":"Nước sông vô cùng trong vắt, có thể nhìn thấy rất nhiều cá nhỏ bơi lội tung tăng dưới nước."},{"type":"compound","zh":"夏天傍晚的时候，河边吹着凉爽的微风，很多人都在那里散步聊天。","pinyin":"Xiàtiān bàngwǎn de shíhou, hébiān chuīzhe liángshuǎng de wēifēng, hěn duō rén dōu zài nàlǐ sànbù liáotiān.","vi":"Vào chiều tối mùa hè, bên bờ sông thổi làn gió nhẹ mát rượi, nhiều người đều đi dạo trò chuyện ở đó."}],"related":[{"hanzi":"海","pinyin":"hǎi","vi":"Biển"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"黄河","pinyin":"Huánghé","vi":"Hoàng Hà"},{"hanzi":"长江","pinyin":"Chángjiāng","vi":"Trường Giang"},{"hanzi":"船","pinyin":"chuán","vi":"Thuyền"}]},{"id":"海","hanzi":"海","pinyin":"hǎi","meaning_vi":"biển, đại dương","explanation":"Bộ thủy 氵+ 每.","hsk_level":2,"tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌊","examples":[{"type":"basic","zh":"我喜欢去海边旅游。","pinyin":"Wǒ xǐhuan qù hǎibiān lǚyóu.","vi":"Tôi thích đi du lịch bờ biển."},{"type":"simple","zh":"今年暑假我们全家去了海边，每天都在沙滩上玩。","pinyin":"Jīnnián shǔjià wǒmen quán jiāqùle hǎibiān, měitiān dōu zài shātān shang wán.","vi":"Kỳ nghỉ hè năm nay cả nhà tôi đã đi bờ biển, ngày nào cũng vui chơi trên bãi cát."},{"type":"compound","zh":"站在海边看着一望无际的大海，所有的烦恼好像一下子都消失了。","pinyin":"Zhàn zài hǎibiān kànzhe yí wàng wújì de dàhǎi, suǒyǒu de fánnǎo hǎoxiàng yíxiàzi dōu xiāoshī le.","vi":"Đứng bên bờ biển ngắm nhìn đại dương mênh mông không thấy bờ, mọi phiền muộn dường như tan biến hết."}],"related":[{"hanzi":"河","pinyin":"hé","vi":"Sông"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"上海","pinyin":"Shànghǎi","vi":"Thượng Hải"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"Hải sản"},{"hanzi":"船","pinyin":"chuán","vi":"Thuyền"}]},{"id":"环境","hanzi":"环境","pinyin":"huánjìng","meaning_vi":"môi trường","explanation":"环 (xung quanh) + 境 (cảnh giới/khu vực).","hsk_level":2,"tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"这里的环境很好。","pinyin":"Zhèlǐ de huánjìng hěn hǎo.","vi":"Môi trường ở đây rất tốt."},{"type":"simple","zh":"我们学校周围的环境非常安静，非常适合学生读书学习。","pinyin":"Wǒmen xuéxiào zhōuwéi de huánjìng fēicháng ānjìng, fēicháng shìhé xuésheng dúshū xuéxí.","vi":"Môi trường xung quanh trường học của chúng tôi vô cùng yên tĩnh, rất thích hợp cho học sinh đọc sách học tập."},{"type":"compound","zh":"为了保护我们的地球环境，大家平时应该少用塑料袋，多坐公共交通工具。","pinyin":"Wèile bǎohù wǒmen de dìqiú huánjìng, dàjiā píngshí yīnggāi shǎo yòng sùliàodài, duō zuò gōnggòng jiāotōng gōngjù.","vi":"Để bảo vệ môi trường Trái Đất của chúng ta, mọi người bình thường nên dùng ít túi ni lông và đi phương tiện công cộng nhiều hơn."}],"related":[{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"安静","pinyin":"ānjìng","vi":"Yên tĩnh"},{"hanzi":"干净","pinyin":"gānjìng","vi":"Sạch sẽ"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"},{"hanzi":"公园","pinyin":"gōngyuán","vi":"Công viên"}],"traditional":"環境"},{"id":"城市","hanzi":"城市","pinyin":"chéngshì","meaning_vi":"thành phố","explanation":"城 (thành quách) + 市 (thị trấn/chợ).","hsk_level":2,"tags":["danh-tu","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"北京是一座大城市。","pinyin":"Běijīng shì yí zuò dàchéngshì.","vi":"Bắc Kinh là một thành phố lớn."},{"type":"simple","zh":"上海是中国最现代化的国际大城市之一。","pinyin":"Shànghǎi shì Zhōngguó zuì xiàndàihuà de Guójì dàchéngshì zhīyī.","vi":"Thượng Hải là một trong những đại đô thị quốc tế hiện đại nhất của Trung Quốc."},{"type":"compound","zh":"虽然大城市的工作机会很多，但是生活节奏太快，压力也比较大。","pinyin":"Suīrán dàchéngshì de gōngzuò jīhuì hěn duō, dànshì shēnghuó jiézòu tài kuài, yālì yě bǐjiào dà.","vi":"Tuy cơ hội việc làm ở thành phố lớn rất nhiều nhưng nhịp sống quá nhanh, áp lực cũng tương đối lớn."}],"related":[{"hanzi":"超市","pinyin":"chāoshì","vi":"Siêu thị"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"Chợ"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"},{"hanzi":"中国","pinyin":"Zhōngguó","vi":"Trung Quốc"},{"hanzi":"北京","pinyin":"Běijīng","vi":"Bắc Kinh"}]},{"id":"地方","hanzi":"地方","pinyin":"dìfang","meaning_vi":"nơi, chỗ, địa phương","explanation":"地 (đất) + 方 (phương hướng).","hsk_level":2,"tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"这是什么地方？","pinyin":"Zhè shì shénme dìfang?","vi":"Đây là nơi nào vậy?"},{"type":"simple","zh":"中国有很多风景优美、历史悠久的地方值得去参观。","pinyin":"Zhōng guóyǒu hěn duō fēngjǐng yōuměi, lìshǐ yōujiǔ de dìfang zhíde qù cānguān.","vi":"Trung Quốc có rất nhiều nơi phong cảnh tươi đẹp, lịch sử lâu đời đáng để đi tham quan."},{"type":"compound","zh":"如果你们在学习中遇到不明白的地方，可以随时在课堂上提出来。","pinyin":"Rúguǒ nǐmen zài xuéxí zhōng yùdào bù míngbai de dìfang, kěyǐ suíshí zài kètáng shang tí chūlái.","vi":"Nếu trong quá trình học các bạn gặp chỗ nào chưa hiểu rõ thì có thể nêu ra ngay trên lớp bất cứ lúc nào."}],"related":[{"hanzi":"地铁","pinyin":"dìtiě","vi":"Tàu điện ngầm"},{"hanzi":"地图","pinyin":"dìtú","vi":"Bản đồ"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"Thuận tiện"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"Phương hướng"},{"hanzi":"城市","pinyin":"chéngshì","vi":"Thành phố"}]},{"id":"旁边","hanzi":"旁边","pinyin":"pángbiān","meaning_vi":"bên cạnh","explanation":"旁 (bên) + 边 (cạnh).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"↔️","examples":[{"type":"basic","zh":"他在我旁边坐着。","pinyin":"Tā zài wǒ pángbiān zuò zhe.","vi":"Anh ấy đang ngồi bên cạnh tôi."},{"type":"simple","zh":"我们学校旁边有一家书店和一家很好吃的面馆。","pinyin":"Wǒmen xuéxiào pángbiān yǒu yìjiā shūdiàn hé yìjiā hěn hǎochī de miànguǎn.","vi":"Bên cạnh trường học của chúng tôi có một hiệu sách và một quán mì rất ngon."},{"type":"compound","zh":"那个站在王老师旁边说话的年轻人就是我们班的新班主任。","pinyin":"Nà ge zhàn zài Wáng lǎoshī pángbiān shuōhuà de niánqīngrén jiùshì wǒmen bān de xīn bānzhǔrèn.","vi":"Người trẻ tuổi đang đứng nói chuyện bên cạnh thầy Vương kia chính là giáo viên chủ nhiệm mới của lớp chúng tôi."}],"related":[{"hanzi":"边","pinyin":"biān","vi":"Bên/Cạnh"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"Đối diện"},{"hanzi":"附近","pinyin":"fùjìn","vi":"Lân cận"},{"hanzi":"左边","pinyin":"zuǒbiān","vi":"Bên trái"},{"hanzi":"右边","pinyin":"yòubiān","vi":"Bên phải"}],"traditional":"旁邊"},{"id":"对面","hanzi":"对面","pinyin":"duìmiàn","meaning_vi":"đối diện","explanation":"对 (đối) + 面 (mặt).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🔄","examples":[{"type":"basic","zh":"银行在学校对面。","pinyin":"Yínháng zài xuéxiào duìmiàn.","vi":"Ngân hàng ở đối diện trường học."},{"type":"simple","zh":"我家对面新开了一家大型超市，买东西非常方便。","pinyin":"Wǒ jiā duìmiàn xīn kāile yìjiā dàxíng chāoshì, mǎidōngxi fēicháng fāngbiàn.","vi":"Đối diện nhà tôi mới mở một siêu thị lớn, mua sắm đồ đạc vô cùng tiện lợi."},{"type":"compound","zh":"因为我家就在学校对面，所以我每天走路上学只要五分钟。","pinyin":"Yīnwèi wǒ jiā jiù zài xuéxiào duìmiàn, suǒyǐ wǒ měitiān zǒulù shàngxué zhǐyào wǔ fēnzhōng.","vi":"Vì nhà tôi ở ngay đối diện trường nên mỗi ngày tôi đi bộ đến trường chỉ mất 5 phút."}],"related":[{"hanzi":"对","pinyin":"duì","vi":"Đúng/Đối"},{"hanzi":"旁边","pinyin":"pángbiān","vi":"Bên cạnh"},{"hanzi":"前面","pinyin":"qiánmiàn","vi":"Phía trước"},{"hanzi":"后面","pinyin":"hòumiàn","vi":"Phía sau"},{"hanzi":"面条","pinyin":"miàntiáo","vi":"Mì sợi"}],"traditional":"對面"},{"id":"附近","hanzi":"附近","pinyin":"fùjìn","meaning_vi":"gần đây, vùng lân cận","explanation":"附 (gắn liền) + 近 (gần).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🏘️","examples":[{"type":"basic","zh":"这附近有医院吗？","pinyin":"Zhè fùjìn yǒu yīyuàn ma?","vi":"Gần đây có bệnh viện không?"},{"type":"simple","zh":"我租的房子就在大学附近，每天走路十分钟就能到教室。","pinyin":"Wǒ zū de fángzi jiù zài dàxué fùjìn, měitiān zǒulù shí fēnzhōng jiù néng dào jiàoshì.","vi":"Căn nhà tôi thuê nằm ngay gần trường đại học, mỗi ngày đi bộ 10 phút là tới phòng học."},{"type":"compound","zh":"因为公司附近有很多不同口味的饭店，所以我们每天中午都可以换着吃。","pinyin":"Yīnwèi gōngsī fùjìn yǒu hěn duō bùtóng kǒuwèi de fàndiàn, suǒyǐ wǒmen měitiān zhōngwǔ dōu kěyǐ huànzhe chī.","vi":"Vì gần công ty có rất nhiều nhà hàng đủ hương vị khác nhau nên trưa nào chúng tôi cũng có thể đổi món."}],"related":[{"hanzi":"近","pinyin":"jìn","vi":"Gần"},{"hanzi":"远","pinyin":"yuǎn","vi":"Xa"},{"hanzi":"旁边","pinyin":"pángbiān","vi":"Bên cạnh"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"Đối diện"},{"hanzi":"地方","pinyin":"dìfang","vi":"Nơi chốn"}]},{"id":"中间","hanzi":"中间","pinyin":"zhōngjiān","meaning_vi":"ở giữa, khoảng giữa","explanation":"中 (giữa) + 间 (khoảng).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🎯","examples":[{"type":"basic","zh":"我坐在他们两个中间。","pinyin":"Wǒ zuò zài tāmen liǎng ge zhōngjiān.","vi":"Tôi ngồi ở giữa hai người họ."},{"type":"simple","zh":"图书馆在教学楼和体育馆的中间，位置非常好找。","pinyin":"Túshūguǎn zài jiàoxuélóu hé tǐyùguǎn de zhōngjiān, wèizhì fēicháng hǎo zhǎo.","vi":"Thư viện nằm ở giữa tòa nhà giảng đường và nhà thi đấu, vị trí rất dễ tìm."},{"type":"compound","zh":"从早上八点到中午十二点要上四节课，中间有二十分钟的休息时间。","pinyin":"Cóng zǎoshang bā diǎn dào zhōngwǔ shí'èr diǎn yào shàng sì jié kè, zhōngjiān yǒu èrshí fēnzhōng de xiūxi shíjiān.","vi":"Từ 8 giờ sáng đến 12 giờ trưa phải học 4 tiết, ở giữa có 20 phút thời gian nghỉ giải lao."}],"related":[{"hanzi":"中","pinyin":"zhōng","vi":"Giữa"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"旁边","pinyin":"pángbiān","vi":"Bên cạnh"},{"hanzi":"中国","pinyin":"Zhōngguó","vi":"Trung Quốc"}],"traditional":"中間"},{"id":"外面","hanzi":"外面","pinyin":"wàimiàn","meaning_vi":"bên ngoài","explanation":"外 (ngoài) + 面 (bề mặt/phía).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"🚪","examples":[{"type":"basic","zh":"外面正在下雨。","pinyin":"Wàimiàn zhèngzài xiàyǔ.","vi":"Bên ngoài đang mưa."},{"type":"simple","zh":"今天外面风很大，你出门的时候别忘了多穿一件外套。","pinyin":"Jīntiān wàimiàn fēng hěn dà, nǐ chūmén de shíhou bié wàngle duō chuān yí jiàn wàitào.","vi":"Hôm nay bên ngoài gió rất lớn, lúc ra khỏi nhà bạn đừng quên mặc thêm một chiếc áo khoác."},{"type":"compound","zh":"虽然在外面饭店吃饭很方便，但是我觉得还是妈妈在家做的菜更健康。","pinyin":"Suīrán zài wàimiàn fàndiàn chīfàn hěn fāngbiàn, dànshì wǒ juéde háishi māma zài jiā zuò de cài gèng jiànkāng.","vi":"Tuy ăn cơm ở nhà hàng bên ngoài rất tiện nhưng tôi thấy món ăn mẹ nấu ở nhà vẫn lành mạnh hơn."}],"related":[{"hanzi":"里面","pinyin":"lǐmiàn","vi":"Bên trong"},{"hanzi":"外","pinyin":"wài","vi":"Ngoài"},{"hanzi":"外国","pinyin":"wàiguó","vi":"Nước ngoài"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"Đối diện"},{"hanzi":"出","pinyin":"chū","vi":"Ra"}]},{"id":"里面","hanzi":"里面","pinyin":"lǐmiàn","meaning_vi":"bên trong","explanation":"里 (trong) + 面 (phía).","hsk_level":2,"tags":["danh-tu","dia-diem","phuong-huong"],"image":"📦","examples":[{"type":"basic","zh":"房间里面很干净。","pinyin":"Fángjiān lǐmiàn hěn gānjìng.","vi":"Bên trong phòng rất sạch sẽ."},{"type":"simple","zh":"我的书包里面放着两本汉语书、一个本子和几支笔。","pinyin":"Wǒ de shūbāo lǐmiàn fàngzhe liǎng běn Hànyǔ shū, yí ge běnzi hé jǐ zhī bǐ.","vi":"Bên trong cặp sách của tôi đựng hai quyển sách tiếng Trung, một quyển vở và mấy cây bút."},{"type":"compound","zh":"这个大箱子里面装的都是爷爷以前收藏的旧报纸和老照片。","pinyin":"Zhè ge dà xiāngzi lǐmiàn zhuāng de dōu shì yéye yǐqián shōucáng de jiù bàozhǐ hé lǎo zhàopiàn.","vi":"Bên trong chiếc thùng lớn này đựng toàn báo cũ và ảnh xưa mà ông nội sưu tầm trước đây."}],"related":[{"hanzi":"外面","pinyin":"wàimiàn","vi":"Bên ngoài"},{"hanzi":"里","pinyin":"lǐ","vi":"Trong"},{"hanzi":"这里","pinyin":"zhèlǐ","vi":"Ở đây"},{"hanzi":"哪里","pinyin":"nǎlǐ","vi":"Ở đâu"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"}],"traditional":"裡面"},{"id":"楼","hanzi":"楼","pinyin":"lóu","meaning_vi":"tầng, tòa nhà, lầu","explanation":"Bộ mộc 木 + 娄. Dùng chỉ số tầng (一楼 - tầng 1) hoặc tòa nhà.","hsk_level":2,"tags":["danh-tu","nha-cua","dia-diem"],"image":"🏢","examples":[{"type":"basic","zh":"老师办公室在三楼。","pinyin":"Lǎoshī bàngōngshì zài sān lóu.","vi":"Văn phòng giáo viên ở tầng 3."},{"type":"simple","zh":"我们学校新建的那座图书馆一共有十层楼高。","pinyin":"Wǒmen xuéxiào xīnjiàn de nà zuò túshūguǎn yí gòngyǒu shí cénglóu gāo.","vi":"Tòa thư viện mới xây của trường chúng tôi cao tổng cộng 10 tầng."},{"type":"compound","zh":"因为电梯正在维修，所以我今天只好走楼梯爬上了八楼。","pinyin":"Yīnwèi diàntī zhèngzài wéixiū, suǒyǐ wǒ jīntiān zhǐhǎo zǒu lóutī páshàngle bā lóu.","vi":"Vì thang máy đang bảo trì nên hôm nay tôi đành đi thang bộ leo lên tận tầng 8."}],"related":[{"hanzi":"楼上","pinyin":"lóushàng","vi":"Trên lầu"},{"hanzi":"楼下","pinyin":"lóuxià","vi":"Dưới lầu"},{"hanzi":"大楼","pinyin":"dàlóu","vi":"Tòa nhà lớn"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"家","pinyin":"jiā","vi":"Nhà"}],"traditional":"樓"},{"id":"窗户","hanzi":"窗户","pinyin":"chuānghu","meaning_vi":"cửa sổ","explanation":"窗 (cửa sổ, bộ huyệt 穴) + 户 (cửa).","hsk_level":2,"tags":["danh-tu","nha-cua","do-vat"],"image":"🪟","examples":[{"type":"basic","zh":"请打开窗户。","pinyin":"Qǐng dǎkāi chuānghu.","vi":"Xin hãy mở cửa sổ."},{"type":"simple","zh":"每天早上起床以后，我都会先打开窗户让新鲜空气进来。","pinyin":"Měitiān zǎoshang qǐchuáng yǐhòu, wǒ dōuhuì xiān dǎkāi chuānghu ràng xīnxiān kōngqì jìnlái.","vi":"Mỗi sáng sau khi thức dậy, tôi đều mở cửa sổ trước để không khí trong lành tràn vào."},{"type":"compound","zh":"因为晚上刮起了大风，所以我赶紧起身把卧室的窗户关紧了。","pinyin":"Yīnwèi wǎnshang guā qǐle dàfēng, suǒyǐ wǒ gǎnjǐn qǐshēn bǎ wòshì de chuānghu guānjǐn le.","vi":"Vì buổi tối nổi gió lớn nên tôi vội vàng đứng dậy đóng chặt cửa sổ phòng ngủ lại."}],"related":[{"hanzi":"门","pinyin":"mén","vi":"Cửa"},{"hanzi":"房间","pinyin":"fángjiān","vi":"Căn phòng"},{"hanzi":"打开","pinyin":"dǎkāi","vi":"Mở ra"},{"hanzi":"关","pinyin":"guān","vi":"Đóng"},{"hanzi":"空气","pinyin":"kōngqì","vi":"Không khí"}],"traditional":"窗戶"},{"id":"丈夫","hanzi":"丈夫","pinyin":"zhàngfu","meaning_vi":"chồng","explanation":"Danh từ chỉ người chồng trong gia đình.","hsk_level":2,"tags":["danh-tu","gia-dinh","con-nguoi"],"image":"🤵","examples":[{"type":"basic","zh":"她丈夫是医生。","pinyin":"Tā zhàngfu shì yīshēng.","vi":"Chồng cô ấy là bác sĩ."},{"type":"simple","zh":"王小姐和她的丈夫都在同一所大学里当老师。","pinyin":"Wáng xiǎojie hé tā de zhàngfu dōu zài tóngyī suǒ dàxué lǐ dāng lǎoshī.","vi":"Cô Vương và chồng của cô ấy đều làm giảng viên ở cùng một trường đại học."},{"type":"compound","zh":"虽然她丈夫平时工作非常忙，但是周末一定会陪她一起去逛超市。","pinyin":"Suīrán tā zhàngfu píngshí gōngzuò fēicháng máng, dànshì zhōumò yídìng huì péi tā yìqǐ qù guàng chāoshì.","vi":"Tuy bình thường chồng cô ấy làm việc rất bận nhưng cuối tuần nhất định sẽ đi dạo siêu thị cùng cô ấy."}],"related":[{"hanzi":"妻子","pinyin":"qīzi","vi":"Vợ"},{"hanzi":"先生","pinyin":"xiānsheng","vi":"Chồng/Ông"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"Kết hôn"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"},{"hanzi":"男人","pinyin":"nánrén","vi":"Đàn ông"}]},{"id":"妻子","hanzi":"妻子","pinyin":"qīzi","meaning_vi":"vợ","explanation":"妻 (vợ) + hậu tố 子.","hsk_level":2,"tags":["danh-tu","gia-dinh","con-nguoi"],"image":"👰","examples":[{"type":"basic","zh":"他非常爱他的妻子。","pinyin":"Tā fēicháng ài tā de qīzi.","vi":"Anh ấy vô cùng yêu vợ của mình."},{"type":"simple","zh":"张先生每天下班以后都会回家帮妻子一起做晚饭。","pinyin":"Zhāng xiānsheng měitiān xiàbān yǐhòu dōuhuì huíjiā bāng qīzi yìqǐ zuò wǎnfàn.","vi":"Ông Trương mỗi ngày sau khi tan làm đều về nhà giúp vợ nấu bữa tối."},{"type":"compound","zh":"因为妻子最近身体不太舒服，所以他特意请了几天假在家照顾她。","pinyin":"Yīnwèi qīzi zuìjìn shēntǐ bú tài shūfu, suǒyǐ tā tèyì qǐngle jǐtiān jià zài jiā zhàogu tā.","vi":"Vì dạo này sức khỏe của vợ không được tốt nên anh ấy đặc biệt xin nghỉ phép mấy ngày ở nhà chăm sóc cô ấy."}],"related":[{"hanzi":"丈夫","pinyin":"zhàngfu","vi":"Chồng"},{"hanzi":"太太","pinyin":"tàitai","vi":"Vợ/Bà"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"Kết hôn"},{"hanzi":"女人","pinyin":"nǚrén","vi":"Phụ nữ"},{"hanzi":"孩子","pinyin":"háizi","vi":"Con cái"}]},{"id":"父母","hanzi":"父母","pinyin":"fùmǔ","meaning_vi":"bố mẹ, cha mẹ","explanation":"父 (cha) + 母 (mẹ).","hsk_level":2,"tags":["danh-tu","gia-dinh","con-nguoi"],"image":"👨‍👩‍👧","examples":[{"type":"basic","zh":"我们要关心父母。","pinyin":"Wǒmen yào guānxīn fùmǔ.","vi":"Chúng ta phải quan tâm đến bố mẹ."},{"type":"simple","zh":"每个周末我都会给远在家乡的父母打一个长途电话。","pinyin":"Měi ge zhōumò wǒ dōuhuì gěi yuǎn zài jiāxiāng de fùmǔ dǎ yí ge chángtú diànhuà.","vi":"Mỗi cuối tuần tôi đều gọi một cuộc điện thoại đường dài cho bố mẹ ở quê nhà."},{"type":"compound","zh":"虽然我在外面工作很辛苦，但是想到父母的期望，我就充满了动力。","pinyin":"Suīrán wǒ zài wàimiàn gōngzuò hěn xīnkǔ, dànshì xiǎngdào fùmǔ de qīwàng, wǒ jiù chōngmǎnle dònglì.","vi":"Tuy làm việc bên ngoài rất vất vả nhưng nghĩ đến sự kỳ vọng của bố mẹ là tôi lại tràn đầy động lực."}],"related":[{"hanzi":"爸爸","pinyin":"bàba","vi":"Bố"},{"hanzi":"妈妈","pinyin":"māma","vi":"Mẹ"},{"hanzi":"父亲","pinyin":"fùqīn","vi":"Cha"},{"hanzi":"母亲","pinyin":"mǔqīn","vi":"Mẹ"},{"hanzi":"家人","pinyin":"jiārén","vi":"Người nhà"}]},{"id":"家人","hanzi":"家人","pinyin":"jiārén","meaning_vi":"người nhà, gia đình","explanation":"家 (nhà) + 人 (người).","hsk_level":2,"tags":["danh-tu","gia-dinh","con-nguoi"],"image":"👨‍👩‍👦","examples":[{"type":"basic","zh":"我爱我的家人。","pinyin":"Wǒ ài wǒ de jiārén.","vi":"Tôi yêu gia đình của tôi."},{"type":"simple","zh":"每年春节的时候，无论工作多忙，大家都会赶回家和家人团聚。","pinyin":"Měinián Chūnjié de shíhou, wúlùn gōngzuò duō máng, dàjiā dōuhuì gǎn huíjiā hé jiārén tuánjù.","vi":"Vào dịp Tết Nguyên đán hằng năm, dù công việc bận đến đâu mọi người cũng tranh thủ về nhà đoàn tụ với gia đình."},{"type":"compound","zh":"能和家人平平安安、快快乐乐地生活在一起，就是世界上最幸福的事情。","pinyin":"Néng hé jiārén píngpíng ān'ān, kuài kuàilè lè de shēnghuó zài yìqǐ, jiùshì shìjiè shang zuì xìngfú de shìqing.","vi":"Có thể sống bình an, vui vẻ bên cạnh người thân chính là điều hạnh phúc nhất trên đời."}],"related":[{"hanzi":"家","pinyin":"jiā","vi":"Nhà"},{"hanzi":"大家","pinyin":"dàjiā","vi":"Mọi người"},{"hanzi":"父母","pinyin":"fùmǔ","vi":"Bố mẹ"},{"hanzi":"家庭","pinyin":"jiātíng","vi":"Gia đình"},{"hanzi":"回家","pinyin":"huíjiā","vi":"Về nhà"}]},{"id":"客人","hanzi":"客人","pinyin":"kèrén","meaning_vi":"khách, khách khứa","explanation":"客 (khách) + 人 (người).","hsk_level":2,"tags":["danh-tu","giao-tiep","con-nguoi"],"image":"🧑","examples":[{"type":"basic","zh":"家里来客人了。","pinyin":"Jiālǐ lái kèrén le.","vi":"Nhà có khách đến rồi."},{"type":"simple","zh":"每次家里来客人的时候，妈妈都会做一大桌丰盛的饭菜。","pinyin":"Měi cì jiālǐ lái kèrén de shíhou, māma dōuhuì zuò yí dà zhuō fēngshèng de fàncài.","vi":"Mỗi lần nhà có khách đến chơi, mẹ đều nấu một bàn đầy ắp các món ăn thịnh soạn."},{"type":"compound","zh":"虽然今天饭店里的客人特别多，但是服务员们依然保持着热情的微笑。","pinyin":"Suīrán jīntiān fàndiàn lǐ de kèrén tèbié duō, dànshì fúwùyuánmen yīrán bǎochízhe rèqíng de wēixiào.","vi":"Tuy hôm nay khách trong nhà hàng đặc biệt đông nhưng các nhân viên phục vụ vẫn luôn giữ nụ cười niềm nở."}],"related":[{"hanzi":"不客气","pinyin":"búkèqi","vi":"Không có gì"},{"hanzi":"客气","pinyin":"kèqi","vi":"Khách sáo"},{"hanzi":"请客","pinyin":"qǐngkè","vi":"Mời khách"},{"hanzi":"顾客","pinyin":"gùkè","vi":"Khách hàng"},{"hanzi":"宾馆","pinyin":"bīnguǎn","vi":"Khách sạn"}]},{"id":"邻居","hanzi":"邻居","pinyin":"línjū","meaning_vi":"hàng xóm","explanation":"邻 (lân cận) + 居 (cư trú).","hsk_level":2,"tags":["danh-tu","con-nguoi","nha-cua"],"image":"🏘️","examples":[{"type":"basic","zh":"他是我的好邻居。","pinyin":"Tā shì wǒ de hǎo línjū.","vi":"Anh ấy là người hàng xóm tốt của tôi."},{"type":"simple","zh":"我的邻居是一位退休的老教师，平时非常喜欢养花和看书。","pinyin":"Wǒ de línjū shì yí wèi tuìxiū de lǎo jiàoshī, píngshí fēicháng xǐhuan yǎnghuā hé kànshū.","vi":"Hàng xóm của tôi là một giáo viên lớn tuổi đã nghỉ hưu, bình thường vô cùng thích trồng hoa và đọc sách."},{"type":"compound","zh":"因为我们是邻居，所以经常互相帮助。","pinyin":"Yīnwèi wǒmen shì línjū, suǒyǐ jīngcháng hùxiāng bāngzhù.","vi":"Vì chúng tôi là hàng xóm nên thường xuyên giúp đỡ lẫn nhau."}],"related":[{"hanzi":"居住","pinyin":"jūzhù","vi":"Cư trú"},{"hanzi":"附近","pinyin":"fùjìn","vi":"Lân cận"},{"hanzi":"朋友","pinyin":"péngyou","vi":"Bạn bè"},{"hanzi":"友好","pinyin":"yǒuhǎo","vi":"Thân thiện"},{"hanzi":"家","pinyin":"jiā","vi":"Nhà"}],"traditional":"鄰居"},{"id":"同事","hanzi":"同事","pinyin":"tóngshì","meaning_vi":"đồng nghiệp","explanation":"同 (cùng) + 事 (công việc) → người làm cùng cơ quan.","hsk_level":2,"tags":["danh-tu","cong-viec","con-nguoi"],"image":"👩‍💼","examples":[{"type":"basic","zh":"我和同事关系很好。","pinyin":"Wǒ hé tóngshì guānxi hěn hǎo.","vi":"Tôi và đồng nghiệp quan hệ rất tốt."},{"type":"simple","zh":"今天中午我和几个同事一起去公司对面的中国饭店吃午饭。","pinyin":"Jīntiān zhōngwǔ wǒ hé jǐ ge tóngshì yìqǐ qù gōngsī duìmiàn de Zhōngguó fàndiàn chī wǔfàn.","vi":"Trưa nay tôi cùng mấy đồng nghiệp đi ăn trưa ở nhà hàng Trung Quốc đối diện công ty."},{"type":"compound","zh":"因为刚进公司有很多业务不熟悉，所以同事们经常耐心地指导我。","pinyin":"Yīnwèi gāng jìn gōngsī yǒu hěn duō yèwù bù shúxī, suǒyǐ tóngshìmen jīngcháng nàixīn de zhǐdǎo wǒ.","vi":"Vì mới vào công ty còn nhiều nghiệp vụ chưa quen nên các đồng nghiệp thường xuyên kiên nhẫn hướng dẫn tôi."}],"related":[{"hanzi":"同学","pinyin":"tóngxué","vi":"Bạn học"},{"hanzi":"同意","pinyin":"tóngyì","vi":"Đồng ý"},{"hanzi":"公司","pinyin":"gōngsī","vi":"Công ty"},{"hanzi":"事情","pinyin":"shìqing","vi":"Sự việc"},{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"}]},{"id":"服务员","hanzi":"服务员","pinyin":"fúwùyuán","meaning_vi":"nhân viên phục vụ","explanation":"服务 (phục vụ) + 员 (nhân viên).","hsk_level":2,"tags":["danh-tu","nghe-nghiep","con-nguoi"],"image":"💁","examples":[{"type":"basic","zh":"服务员，请给我菜单。","pinyin":"Fúwùyuán, qǐng gěi wǒ càidān.","vi":"Phục vụ ơi, xin cho tôi xem thực đơn."},{"type":"simple","zh":"这家宾馆的服务员态度非常好，总是主动帮助客人拿行李。","pinyin":"Zhè jiā bīnguǎn de fúwùyuán tàidù fēicháng hǎo, zǒngshì zhǔdòng bāngzhù kèrén ná xíngli.","vi":"Nhân viên phục vụ của khách sạn này thái độ rất tốt, luôn chủ động giúp khách xách hành lý."},{"type":"compound","zh":"因为这家饭店的菜做得好吃，而且服务员也很热情，所以回头客特别多。","pinyin":"Yīnwèi zhè jiā fàndiàn de cài zuò de hǎochī, érqiě fúwùyuán yě hěn rèqíng, suǒyǐ huítóukè tèbié duō.","vi":"Vì món ăn nhà hàng này nấu ngon mà nhân viên phục vụ lại nhiệt tình nên khách quay lại đặc biệt đông."}],"related":[{"hanzi":"服务","pinyin":"fúwù","vi":"Phục vụ"},{"hanzi":"衣服","pinyin":"yīfu","vi":"Quần áo"},{"hanzi":"舒服","pinyin":"shūfu","vi":"Thoải mái"},{"hanzi":"客人","pinyin":"kèrén","vi":"Khách"},{"hanzi":"饭店","pinyin":"fàndiàn","vi":"Nhà hàng"}],"traditional":"服務員"},{"id":"警察","hanzi":"警察","pinyin":"jǐngchá","meaning_vi":"cảnh sát","explanation":"警 (cảnh báo) + 察 (xem xét).","hsk_level":2,"tags":["danh-tu","nghe-nghiep","con-nguoi"],"image":"👮","examples":[{"type":"basic","zh":"他是一名交通警察。","pinyin":"Tā shì yì míng jiāotōng jǐngchá.","vi":"Anh ấy là một cảnh sát giao thông."},{"type":"simple","zh":"在陌生的城市迷路的时候，我们可以向路边的警察叔叔求助。","pinyin":"Zài mòshēng de chéngshì mílù de shíhou, wǒmen kěyǐ xiàng lùbiān de jǐngchá shūshu qiúzhù.","vi":"Lúc bị lạc đường ở thành phố xa lạ, chúng ta có thể nhờ các chú cảnh sát bên đường giúp đỡ."},{"type":"compound","zh":"不管刮风还是下雨，警察都在路上工作，保护大家的安全。","pinyin":"Bùguǎn guāfēng háishi xiàyǔ, jǐngchá dōu zài lùshang gōngzuò, bǎohù dàjiā de ānquán.","vi":"Bất kể trời gió hay mưa, cảnh sát đều làm việc trên đường để bảo vệ an toàn cho mọi người."}],"related":[{"hanzi":"检查","pinyin":"jiǎnchá","vi":"Kiểm tra"},{"hanzi":"安全","pinyin":"ānquán","vi":"An toàn"},{"hanzi":"保护","pinyin":"bǎohù","vi":"Bảo vệ"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"Nguy hiểm"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"Giúp đỡ"}]},{"id":"头发","hanzi":"头发","pinyin":"tóufa","meaning_vi":"tóc","explanation":"头 (đầu) + 发 (tóc, thanh nhẹ).","hsk_level":2,"tags":["danh-tu","co-the"],"image":"💇","examples":[{"type":"basic","zh":"她的头发又黑又长。","pinyin":"Tā de tóufa yòu hēi yòu cháng.","vi":"Tóc của cô ấy vừa đen vừa dài."},{"type":"simple","zh":"我每天晚上洗完澡以后，都会用吹风机把头发吹干再睡觉。","pinyin":"Wǒ měitiān wǎnshang xǐ wán zǎo yǐhòu, dōuhuì yòng chuīfēngjī bǎ tóufa chuīgān zài shuìjiào.","vi":"Mỗi tối sau khi tắm xong, tôi đều dùng máy sấy sấy khô tóc rồi mới đi ngủ."},{"type":"compound","zh":"因为哥哥的头发太长了，所以他决定今天下午去理发店理发。","pinyin":"Yīnwèi gēge de tóufa tài cháng le, suǒyǐ tā juédìng jīntiān xiàwǔ qù lǐfàdiàn lǐfà.","vi":"Vì tóc của anh trai dài quá rồi nên anh ấy quyết định chiều nay đi tiệm cắt tóc."}],"related":[{"hanzi":"头","pinyin":"tóu","vi":"Đầu"},{"hanzi":"长","pinyin":"cháng","vi":"Dài"},{"hanzi":"短","pinyin":"duǎn","vi":"Ngắn"},{"hanzi":"洗","pinyin":"xǐ","vi":"Gội/Rửa"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"Mắt"}],"traditional":"頭髮"},{"id":"脸","hanzi":"脸","pinyin":"liǎn","meaning_vi":"khuôn mặt, mặt","explanation":"Bộ nguyệt ⺼(cơ thể) + 佥.","hsk_level":2,"tags":["danh-tu","co-the"],"image":"😊","examples":[{"type":"basic","zh":"妹妹的脸红红的。","pinyin":"Mèimei de liǎnhóng hóng de.","vi":"Khuôn mặt của em gái đỏ hồng."},{"type":"simple","zh":"每天早上起床以后，我都会用温水洗脸刷牙。","pinyin":"Měitiān zǎoshang qǐchuáng yǐhòu, wǒ dōuhuì yòng wēn shuǐ xǐliǎn shuāyá.","vi":"Mỗi sáng sau khi thức dậy, tôi đều rửa mặt đánh răng bằng nước ấm."},{"type":"compound","zh":"听到老师表扬自己的时候，她害羞得一下子红了脸。","pinyin":"Tīngdào lǎoshī biǎoyáng zìjǐ de shíhou, tā hàixiū de yíxiàzi hóngle liǎn.","vi":"Khi nghe thầy giáo khen ngợi mình, cô ấy ngại ngùng đến mức đỏ bừng cả mặt."}],"related":[{"hanzi":"洗脸","pinyin":"xǐliǎn","vi":"Rửa mặt"},{"hanzi":"头","pinyin":"tóu","vi":"Đầu"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"Mắt"},{"hanzi":"鼻子","pinyin":"bízi","vi":"Mũi"},{"hanzi":"笑","pinyin":"xiào","vi":"Cười"}],"traditional":"臉"},{"id":"腿","hanzi":"腿","pinyin":"tuǐ","meaning_vi":"chân, đùi","explanation":"Bộ nguyệt ⺼+ 退.","hsk_level":2,"tags":["danh-tu","co-the"],"image":"🦵","examples":[{"type":"basic","zh":"我的腿有点儿疼。","pinyin":"Wǒ de tuǐ yǒudiǎnr téng.","vi":"Chân của tôi hơi đau một chút."},{"type":"simple","zh":"他个子很高，两条腿特别长，跑起路来像风一样快。","pinyin":"Tā gèzi hěn gāo, liǎng tiáo tuǐ tèbié cháng, pǎo qǐ lù lái xiàng fēng yíyàng kuài.","vi":"Dáng người cậu ấy rất cao, đôi chân đặc biệt dài, chạy nhanh như gió."},{"type":"compound","zh":"因为昨天去爬山走了五个小时，所以我今天两条腿酸得都走不动了。","pinyin":"Yīnwèi zuótiān qù páshān zǒule wǔ ge xiǎoshí, suǒyǐ wǒ jīntiān liǎng tiáo tuǐ suān de dōu zǒu búdòng le.","vi":"Vì hôm qua đi leo núi đi bộ 5 tiếng đồng hồ nên hôm nay hai chân tôi mỏi nhừ không bước nổi nữa."}],"related":[{"hanzi":"脚","pinyin":"jiǎo","vi":"Bàn chân"},{"hanzi":"手","pinyin":"shǒu","vi":"Tay"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"Cơ thể"},{"hanzi":"跑","pinyin":"pǎo","vi":"Chạy"},{"hanzi":"高","pinyin":"gāo","vi":"Cao"}]},{"id":"药","hanzi":"药","pinyin":"yào","meaning_vi":"thuốc","explanation":"Bộ thảo 艹+ 约 (thời xưa thuốc bào chế từ thảo mộc). Cụm: 吃药 (uống thuốc).","hsk_level":2,"tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"生病了要按时吃药。","pinyin":"Shēngbìngle yào ànshí chīyào.","vi":"Bị ốm rồi thì phải uống thuốc đúng giờ."},{"type":"simple","zh":"医生给我开了一些感冒药，让我每天早晚各吃一次。","pinyin":"Yīshēng gěi wǒ kāile yìxiē gǎnmàoyào, ràng wǒ měitiān zǎowǎn gè chī yí cì.","vi":"Bác sĩ kê cho tôi một ít thuốc cảm cúm, dặn tôi mỗi ngày sáng tối uống một lần."},{"type":"compound","zh":"虽然这服中药喝起来非常苦，但是喝了三天以后我的病就好了。","pinyin":"Suīrán zhè fù zhōngyào hē qǐlái fēicháng kǔ, dànshì hēle sān tiān yǐhòu wǒ de bìng jiù hǎo le.","vi":"Tuy thang thuốc Bắc này uống vào vô cùng đắng nhưng sau khi uống 3 ngày thì bệnh của tôi đã khỏi."}],"related":[{"hanzi":"医院","pinyin":"yīyuàn","vi":"Bệnh viện"},{"hanzi":"医生","pinyin":"yīshēng","vi":"Bác sĩ"},{"hanzi":"生病","pinyin":"shēngbìng","vi":"Bị ốm"},{"hanzi":"苦","pinyin":"kǔ","vi":"Đắng"},{"hanzi":"吃药","pinyin":"chīyào","vi":"Uống thuốc"}],"traditional":"藥"},{"id":"眼镜","hanzi":"眼镜","pinyin":"yǎnjìng","meaning_vi":"kính mắt","explanation":"眼 (mắt) + 镜 (gương/thấu kính). Cụm: 戴眼镜 (đeo kính).","hsk_level":2,"tags":["danh-tu","do-vat","trang-phuc"],"image":"👓","examples":[{"type":"basic","zh":"他戴着一副黑眼镜。","pinyin":"Tā dàizhe yí fù hēi yǎnjìng.","vi":"Anh ấy đang đeo một cặp kính màu đen."},{"type":"simple","zh":"因为每天看电脑的时间太长，所以我现在看书必须戴眼镜。","pinyin":"Yīnwèi měitiān kàn diànnǎo de shíjiān tài cháng, suǒyǐ wǒ xiànzài kànshū bìxū dài yǎnjìng.","vi":"Vì mỗi ngày nhìn máy tính quá lâu nên bây giờ đọc sách tôi bắt buộc phải đeo kính."},{"type":"compound","zh":"刚才我找了半天眼镜，后来才发现原来它就戴在我自己的头上。","pinyin":"Gāngcái wǒ zhǎole bàn tiān yǎnjìng, hòulái cái fāxiàn yuánlái tā jiù dài zài wǒ zìjǐ de tóushang.","vi":"Vừa nãy tôi tìm kính mãi nửa ngày, sau mới phát hiện hóa ra nó đang đeo ngay trên đầu mình."}],"related":[{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"Đôi mắt"},{"hanzi":"看","pinyin":"kàn","vi":"Nhìn"},{"hanzi":"清楚","pinyin":"qīngchu","vi":"Rõ ràng"},{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"Đồng hồ"},{"hanzi":"戴","pinyin":"dài","vi":"Đeo"}],"traditional":"眼鏡"},{"id":"手表","hanzi":"手表","pinyin":"shǒubiǎo","meaning_vi":"đồng hồ đeo tay","explanation":"手 (tay) + 表 (đồng hồ).","hsk_level":2,"tags":["danh-tu","do-vat","trang-phuc"],"image":"⌚","examples":[{"type":"basic","zh":"这块手表很漂亮。","pinyin":"Zhè kuài shǒubiǎo hěn piàoliang.","vi":"Chiếc đồng hồ đeo tay này rất đẹp."},{"type":"simple","zh":"这块手表是去年我生日的时候爸爸送给我的礼物。","pinyin":"Zhè kuài shǒubiǎo shì qùnián wǒ shēngrì de shíhou bàba sònggěi wǒ de lǐwù.","vi":"Chiếc đồng hồ đeo tay này là món quà bố tặng cho tôi vào dịp sinh nhật năm ngoái."},{"type":"compound","zh":"虽然现在大家都习惯用手机看时间，但是戴一块手表依然显得很有礼貌。","pinyin":"Suīrán xiànzài dàjiā dōu xí guànyòng shǒujī kàn shíjiān, dànshì dài yíkuài shǒubiǎo yīrán xiǎnde hěn yǒulǐmào.","vi":"Tuy hiện nay mọi người đều quen xem giờ bằng điện thoại nhưng đeo một chiếc đồng hồ vẫn tỏ ra rất lịch sự."}],"related":[{"hanzi":"手机","pinyin":"shǒujī","vi":"Điện thoại"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"Kính mắt"},{"hanzi":"点","pinyin":"diǎn","vi":"Giờ"},{"hanzi":"分","pinyin":"fēn","vi":"Phút"}],"traditional":"手錶"},{"id":"报纸","hanzi":"报纸","pinyin":"bàozhǐ","meaning_vi":"báo, báo giấy","explanation":"报 (báo cáo/tin tức) + 纸 (giấy).","hsk_level":2,"tags":["danh-tu","do-vat","hoc-tap"],"image":"📰","examples":[{"type":"basic","zh":"爷爷每天早上都看报纸。","pinyin":"Yéye měitiān zǎo Shangdōu kàn bàozhǐ.","vi":"Ông nội mỗi sáng đều đọc báo."},{"type":"simple","zh":"通过阅读每天的中文报纸，我们可以了解国内外发生的新闻。","pinyin":"Tōngguò yuèdú měitiān de Zhōngwén bàozhǐ, wǒmen kěyǐ liǎojiě guónèiwài fāshēng de xīnwén.","vi":"Thông qua việc đọc báo tiếng Trung hằng ngày, chúng ta có thể nắm bắt tin tức trong và ngoài nước."},{"type":"compound","zh":"虽然现在很多人都在网上看新闻，但是我爷爷还是喜欢每天买报纸看。","pinyin":"Suīrán xiànzài hěn duō rén dōu zài wǎngshang kàn xīnwén, dànshì wǒ yéye háishi xǐhuan měitiān mǎi bàozhǐ kàn.","vi":"Tuy hiện nay nhiều người đều xem tin tức trên mạng nhưng ông nội tôi vẫn thích mua báo đọc mỗi ngày."}],"related":[{"hanzi":"新闻","pinyin":"xīnwén","vi":"Tin tức"},{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"看","pinyin":"kàn","vi":"Đọc/Xem"},{"hanzi":"读","pinyin":"dú","vi":"Đọc"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"}],"traditional":"報紙"},{"id":"词典","hanzi":"词典","pinyin":"cídiǎn","meaning_vi":"từ điển","explanation":"词 (từ ngữ) + 典 (sách kinh điển).","hsk_level":2,"tags":["danh-tu","hoc-tap","do-vat"],"image":"📕","examples":[{"type":"basic","zh":"我买了一本汉越词典。","pinyin":"Wǒ mǎile yì běn hàn yuè cídiǎn.","vi":"Tôi đã mua một quyển từ điển Hán - Việt."},{"type":"simple","zh":"遇到不认识的生词时，我们可以查一下汉语词典。","pinyin":"Yùdào bú rènshi de shēngcí shí, wǒmen kěyǐ chá yíxià Hànyǔ cídiǎn.","vi":"Khi gặp từ mới không biết, chúng ta có thể tra từ điển tiếng Trung."},{"type":"compound","zh":"虽然现在手机上的电子词典很方便，但是我学习的时候还是喜欢用纸质词典。","pinyin":"Suīrán xiànzài shǒujī shang de diànzǐ cídiǎn hěn fāngbiàn, dànshì wǒ xuéxí de shíhou háishi xǐhuan yòng zhǐzhì cídiǎn.","vi":"Tuy từ điển điện tử trên điện thoại rất tiện nhưng khi học tôi vẫn thích dùng từ điển giấy."}],"related":[{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"字","pinyin":"zì","vi":"Chữ"},{"hanzi":"汉字","pinyin":"hànzì","vi":"Chữ Hán"},{"hanzi":"学习","pinyin":"xuéxí","vi":"Học tập"},{"hanzi":"图书馆","pinyin":"túshūguǎn","vi":"Thư viện"}],"traditional":"詞典"},{"id":"作业","hanzi":"作业","pinyin":"zuòyè","meaning_vi":"bài tập về nhà","explanation":"作 (làm) + 业 (nghiệp/việc học).","hsk_level":2,"tags":["danh-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"我每天晚上都做作业。","pinyin":"Wǒ měitiān wǎn Shangdōu zuò zuòyè.","vi":"Mỗi tối tôi đều làm bài tập về nhà."},{"type":"simple","zh":"每天下课回家以后，弟弟总是先把作业写完再去玩。","pinyin":"Měitiān xiàkè huíjiā yǐhòu, dìdi zǒngshì xiān bǎ zuòyè xiěwán zài qù wán.","vi":"Mỗi ngày sau khi tan học về nhà, em trai luôn làm xong bài tập trước rồi mới đi chơi."},{"type":"compound","zh":"因为今天的汉语作业比较多，所以我一直写到晚上十点才完成。","pinyin":"Yīnwèi jīntiān de Hànyǔ zuòyè bǐjiào duō, suǒyǐ wǒ yìzhí xiě dào wǎnshang shí diǎn cái wánchéng.","vi":"Vì bài tập tiếng Trung hôm nay tương đối nhiều nên tôi viết mãi đến 10 giờ tối mới hoàn thành."}],"related":[{"hanzi":"工作","pinyin":"gōngzuò","vi":"Công việc"},{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"练习","pinyin":"liànxí","vi":"Luyện tập"},{"hanzi":"上课","pinyin":"shàngkè","vi":"Lên lớp"},{"hanzi":"下课","pinyin":"xiàkè","vi":"Tan học"}],"traditional":"作業"},{"id":"成绩","hanzi":"成绩","pinyin":"chéngjì","meaning_vi":"thành tích, điểm số","explanation":"成 (thành tựu) + 绩 (công lao).","hsk_level":2,"tags":["danh-tu","hoc-tap"],"image":"💯","examples":[{"type":"basic","zh":"他的学习成绩很好。","pinyin":"Tā de xuéxí chéngjì hěn hǎo.","vi":"Thành tích học tập của cậu ấy rất tốt."},{"type":"simple","zh":"因为平时学习非常认真，所以她在这次期末考试中取得了优异的成绩。","pinyin":"Yīnwèi píngshí xuéxí fēicháng rènzhēn, suǒyǐ tā zài zhè cì qīmò kǎoshì zhōng qǔ déle yōuyì de chéngjì.","vi":"Vì bình thường học tập vô cùng chăm chỉ nên cô ấy đã đạt thành tích xuất sắc trong kỳ thi cuối kỳ lần này."},{"type":"compound","zh":"只要你找到适合自己的学习方法并坚持努力，成绩一定会慢慢提高的。","pinyin":"Zhǐyào nǐ zhǎodào shìhé zìjǐ de xuéxí fāngfǎ bìng jiānchí nǔlì, chéngjì yídìng huì mànmàn tígāo de.","vi":"Chỉ cần bạn tìm được phương pháp học phù hợp với bản thân và kiên trì nỗ lực thì thành tích nhất định sẽ dần nâng cao."}],"related":[{"hanzi":"完成","pinyin":"wánchéng","vi":"Hoàn thành"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"},{"hanzi":"努力","pinyin":"nǔlì","vi":"Nỗ lực"}],"traditional":"成績"},{"id":"水平","hanzi":"水平","pinyin":"shuǐpíng","meaning_vi":"trình độ, mức độ","explanation":"水 (nước) + 平 (bằng phẳng) → mặt nước phẳng làm chuẩn đo lường.","hsk_level":2,"tags":["danh-tu","hoc-tap"],"image":"📊","examples":[{"type":"basic","zh":"他的汉语水平很高。","pinyin":"Tā de Hànyǔ shuǐpíng hěn gāo.","vi":"Trình độ tiếng Trung của anh ấy rất cao."},{"type":"simple","zh":"来中国留学一年以后，我的汉语听说水平有了很大的提高。","pinyin":"Lái Zhōngguó liúxué yì nián yǐhòu, wǒ de Hànyǔ tīngshuō shuǐpíng yǒule hěn dà de tígāo.","vi":"Sau khi đến Trung Quốc du học một năm, trình độ nghe nói tiếng Trung của tôi đã tiến bộ rất nhiều."},{"type":"compound","zh":"为了检验自己目前的汉语水平，我报名参加了下个月的HSK考试。","pinyin":"Wèi le jiǎn yàn zì jǐ mù qián de hàn yǔ shuǐ píng, wǒ bào míng cān jiā le xià ge yuè de HSK kǎo shì.","vi":"Để kiểm tra trình độ tiếng Trung hiện tại của bản thân, tôi đã đăng ký tham gia kỳ thi HSK tháng sau."}],"related":[{"hanzi":"提高","pinyin":"tígāo","vi":"Nâng cao"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"汉语水平考试","pinyin":"Hànyǔ Shuǐpíng Kǎoshì","vi":"Kỳ thi HSK"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"平时","pinyin":"píngshí","vi":"Bình thường"}]},{"id":"汉语水平考试","hanzi":"汉语水平考试","pinyin":"Hànyǔ Shuǐpíng Kǎoshì","meaning_vi":"kỳ thi năng lực Hán ngữ (HSK)","explanation":"Tên đầy đủ của kỳ thi HSK.","hsk_level":2,"tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"我准备参加汉语水平考试。","pinyin":"Wǒ zhǔnbèi cānjiā Hànyǔshuǐpíngkǎoshì.","vi":"Tôi chuẩn bị tham gia kỳ thi năng lực Hán ngữ."},{"type":"simple","zh":"很多外国人都参加汉语水平考试。","pinyin":"Hěn duō wàiguórén dōu cānjiā Hànyǔshuǐpíngkǎoshì.","vi":"Rất nhiều người nước ngoài tham gia kỳ thi năng lực Hán ngữ."},{"type":"compound","zh":"因为申请中国大学的奖学金需要HSK证书，所以我正在认真准备汉语水平考试。","pinyin":"Yīn wèi shēn qǐng zhōng guó dà xué de jiǎng xué jīn xū yào HSK zhèng shū, suǒ yǐ wǒ zhèng zài rèn zhēn zhǔn bèi hàn yǔ shuǐ píng kǎo shì.","vi":"Vì xin học bổng đại học Trung Quốc cần chứng chỉ HSK nên tôi đang nghiêm túc ôn thi năng lực Hán ngữ."}],"related":[{"hanzi":"汉语","pinyin":"Hànyǔ","vi":"Tiếng Trung"},{"hanzi":"水平","pinyin":"shuǐpíng","vi":"Trình độ"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"Thi cử"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"Thành tích"},{"hanzi":"通过","pinyin":"tōngguò","vi":"Thi đỗ/Thông qua"}],"traditional":"漢語水平考試"},{"id":"音乐","hanzi":"音乐","pinyin":"yīnyuè","meaning_vi":"âm nhạc","explanation":"音 (âm thanh) + 乐 (nhạc, đọc yuè).","hsk_level":2,"tags":["danh-tu","giai-tri"],"image":"🎵","examples":[{"type":"basic","zh":"我喜欢听中国音乐。","pinyin":"Wǒ xǐhuan tīng Zhōngguó yīnyuè.","vi":"Tôi thích nghe nhạc Trung Quốc."},{"type":"simple","zh":"每天晚上做完作业以后，我喜欢躺在床上听一会儿轻音乐。","pinyin":"Měitiān wǎnshang zuòwán zuòyè yǐhòu, wǒ xǐhuan tǎng zài chuáng shang tīng yíhuìr qīngyīnyuè.","vi":"Mỗi tối sau khi làm xong bài tập, tôi thích nằm trên giường nghe một chút nhạc nhẹ."},{"type":"compound","zh":"音乐是一种没有国界的语言，它能让人放松心情、忘记烦恼。","pinyin":"Yīnyuè shì yì zhǒng méiyǒu guójiè de yǔyán, tā néng ràng rén fàngsōng xīnqíng, wàngjì fánnǎo.","vi":"Âm nhạc là một loại ngôn ngữ không biên giới, nó có thể giúp con người thư giãn tinh thần và quên đi phiền muộn."}],"related":[{"hanzi":"歌","pinyin":"gē","vi":"Bài hát"},{"hanzi":"唱歌","pinyin":"chànggē","vi":"Ca hát"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"},{"hanzi":"听","pinyin":"tīng","vi":"Nghe"},{"hanzi":"跳舞","pinyin":"tiàowǔ","vi":"Nhảy múa"}],"traditional":"音樂"},{"id":"歌","hanzi":"歌","pinyin":"gē","meaning_vi":"bài hát","explanation":"哥 + 欠 (há miệng hát).","hsk_level":2,"tags":["danh-tu","giai-tri"],"image":"🎶","examples":[{"type":"basic","zh":"这首中文歌很好听。","pinyin":"Zhè shǒu Zhōngwén gē hěn hǎotīng.","vi":"Bài hát tiếng Trung này rất hay."},{"type":"simple","zh":"我姐姐会唱很多首好听的中文歌和英文歌。","pinyin":"Wǒ jiějie huì chàng hěn duō shǒu hǎotīng de Zhōngwén gē hé Yīngwén gē.","vi":"Chị gái tôi biết hát rất nhiều bài hát tiếng Trung và tiếng Anh hay."},{"type":"compound","zh":"学唱中文歌不仅很有趣，而且还能帮助我们记住很多生词和语法。","pinyin":"Xué chàng Zhōngwén gē bùjǐn hěn yǒuqù, érqiě hái néng bāngzhù wǒmen jìzhù hěn duō shēngcí hé yǔfǎ.","vi":"Học hát tiếng Trung không những rất thú vị mà còn giúp chúng ta ghi nhớ được nhiều từ mới và ngữ pháp."}],"related":[{"hanzi":"唱歌","pinyin":"chànggē","vi":"Ca hát"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"Âm nhạc"},{"hanzi":"哥哥","pinyin":"gēge","vi":"Anh trai"},{"hanzi":"好听","pinyin":"hǎotīng","vi":"Hay"},{"hanzi":"听","pinyin":"tīng","vi":"Nghe"}]},{"id":"故事","hanzi":"故事","pinyin":"gùshi","meaning_vi":"câu chuyện","explanation":"故 (cũ/xưa) + 事 (sự việc).","hsk_level":2,"tags":["danh-tu","giai-tri"],"image":"📖","examples":[{"type":"basic","zh":"这个故事很有意思。","pinyin":"Zhè ge gùshi hěn yǒuyìsi.","vi":"Câu chuyện này rất thú vị."},{"type":"simple","zh":"每天晚上睡觉前，妈妈都会给弟弟讲一个有趣的小故事。","pinyin":"Měitiān wǎnshang shuìjiào qián, māma dōuhuì gěi dìdi jiǎng yí ge yǒuqù de xiǎo gùshi.","vi":"Mỗi tối trước khi đi ngủ, mẹ đều kể cho em trai nghe một câu chuyện nhỏ thú vị."},{"type":"compound","zh":"虽然这本书里的故事都很短，但是每一个故事都告诉我们一个做人的道理。","pinyin":"Suīrán zhè běn shū lǐ de gùshi dōu hěn duǎn, dànshì měi yí ge gùshi dōu gàosu wǒmen yí ge zuòrén de dàolǐ.","vi":"Tuy các câu chuyện trong quyển sách này đều rất ngắn nhưng mỗi câu chuyện đều dạy cho chúng ta một đạo lý làm người."}],"related":[{"hanzi":"事情","pinyin":"shìqing","vi":"Sự việc"},{"hanzi":"同事","pinyin":"tóngshì","vi":"Đồng nghiệp"},{"hanzi":"书","pinyin":"shū","vi":"Sách"},{"hanzi":"电影","pinyin":"diànyǐng","vi":"Phim"},{"hanzi":"听","pinyin":"tīng","vi":"Nghe"}]},{"id":"新闻","hanzi":"新闻","pinyin":"xīnwén","meaning_vi":"tin tức, thời sự","explanation":"新 (mới) + 闻 (nghe thấy).","hsk_level":2,"tags":["danh-tu","cong-nghe"],"image":"📺","examples":[{"type":"basic","zh":"爸爸每天晚上都看新闻。","pinyin":"Bàba měitiān wǎnshang dōu kàn xīnwén.","vi":"Bố mỗi tối đều xem thời sự."},{"type":"simple","zh":"我每天早上吃早饭的时候，都会一边吃一边听广播新闻。","pinyin":"Wǒ měitiān zǎoshang chī zǎofàn de shíhou, dōuhuì yìbiān chī yìbiān tīng guǎngbō xīnwén.","vi":"Mỗi sáng lúc ăn bữa sáng, tôi đều vừa ăn vừa nghe tin tức trên đài."},{"type":"compound","zh":"最近新闻里经常报道关于环境保护和新能源发展的新消息。","pinyin":"Zuìjìn xīnwén lǐ jīngcháng bàodào guānyú huánjìngbǎohù hé xīnnéngyuán fāzhǎn de xīn xiāoxi.","vi":"Dạo gần đây trên tin tức thường xuyên đưa tin về bảo vệ môi trường và phát triển năng lượng mới."}],"related":[{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"Báo giấy"},{"hanzi":"新","pinyin":"xīn","vi":"Mới"},{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"Tươi mới"},{"hanzi":"电视","pinyin":"diànshì","vi":"Tivi"},{"hanzi":"听","pinyin":"tīng","vi":"Nghe"}],"traditional":"新聞"},{"id":"礼物","hanzi":"礼物","pinyin":"lǐwù","meaning_vi":"quà tặng","explanation":"礼 (lễ nghĩa) + 物 (đồ vật).","hsk_level":2,"tags":["danh-tu","giao-tiep","do-vat"],"image":"🎁","examples":[{"type":"basic","zh":"这是我送你的生日礼物。","pinyin":"Zhè shì wǒ sòng nǐ de shēngrì lǐwù.","vi":"Đây là món quà sinh nhật tôi tặng bạn."},{"type":"simple","zh":"昨天妈妈过生日，我和妹妹一起买了一束漂亮的花作为礼物送给她。","pinyin":"Zuótiān māma guòshēngrì, wǒ hé mèimei yìqǐ mǎile yí shù piàoliang de huā zuòwéi lǐwù sònggěi tā.","vi":"Hôm qua là sinh nhật mẹ, tôi và em gái đã cùng mua một bó hoa đẹp làm quà tặng mẹ."},{"type":"compound","zh":"虽然这件礼物价格并不贵，但是它代表了我对你最真诚的祝福。","pinyin":"Suīrán zhè jiàn lǐwù jiàgé bìngbú guì, dànshì tā dàibiǎole wǒ duì nǐ zuì zhēnchéng de zhùfú.","vi":"Tuy món quà này giá cả không hề đắt nhưng nó đại diện cho lời chúc chân thành nhất của tôi dành cho bạn."}],"related":[{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"},{"hanzi":"送","pinyin":"sòng","vi":"Tặng/Tiễn"},{"hanzi":"动物","pinyin":"dòngwù","vi":"Động vật"},{"hanzi":"购物","pinyin":"gòuwù","vi":"Mua sắm"},{"hanzi":"礼貌","pinyin":"lǐmào","vi":"Lễ phép"}],"traditional":"禮物"},{"id":"生日","hanzi":"生日","pinyin":"shēngrì","meaning_vi":"sinh nhật","explanation":"生 (sinh ra) + 日 (ngày).","hsk_level":2,"tags":["danh-tu","thoi-gian","gia-dinh"],"image":"🎂","examples":[{"type":"basic","zh":"今天是我的生日。","pinyin":"Jīntiān shì wǒ de shēngrì.","vi":"Hôm nay là sinh nhật của tôi."},{"type":"simple","zh":"这个月十五号是我妈妈的生日，我们全家都会一起庆祝。","pinyin":"Zhè geyuè shí wǔhào shì wǒ māma de shēngrì, wǒmen quánjiā dōuhuì yìqǐ qìngzhù.","vi":"Ngày 15 tháng này là sinh nhật mẹ tôi, cả nhà tôi sẽ cùng nhau tổ chức mừng."},{"type":"compound","zh":"虽然我今年在国外留学不能回家过生日，但是父母和朋友都发来了祝福。","pinyin":"Suīrán wǒ jīnnián zài guówài liúxué bù néng huíjiā guòshēngrì, dànshì fùmǔ hé péngyou dōu fā láile zhùfú.","vi":"Tuy năm nay tôi đi du học ở nước ngoài không thể về nhà đón sinh nhật nhưng bố mẹ và bạn bè đều gửi lời chúc tới."}],"related":[{"hanzi":"礼物","pinyin":"lǐwù","vi":"Quà tặng"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"},{"hanzi":"蛋糕","pinyin":"dàngāo","vi":"Bánh kem"},{"hanzi":"节日","pinyin":"jiérì","vi":"Ngày lễ"},{"hanzi":"日","pinyin":"rì","vi":"Ngày"}]},{"id":"节日","hanzi":"节日","pinyin":"jiérì","meaning_vi":"ngày lễ, dịp lễ","explanation":"节 (tiết lễ) + 日 (ngày).","hsk_level":2,"tags":["danh-tu","thoi-gian","van-hoa"],"image":"🎊","examples":[{"type":"basic","zh":"春节是中国最重要的节日。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì.","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất của Trung Quốc."},{"type":"simple","zh":"一到传统节日，各大超市和商店里就会挂满红色的灯笼。","pinyin":"Yí dào chuántǒng jiérì, gè dà chāoshì hé shāngdiàn lǐ jiù huì guà mǎn hóngsè de dēnglong.","vi":"Hễ đến ngày lễ truyền thống là các siêu thị và cửa hàng lớn đều treo đầy đèn lồng đỏ."},{"type":"compound","zh":"在节日放假期间，很多人喜欢选择出门旅游或者回家陪伴父母。","pinyin":"Zài jiérì fàngjià qījiān, hěn duō rén xǐhuan xuǎnzé chūmén lǚyóu huòzhě huíjiā péibàn fùmǔ.","vi":"Trong kỳ nghỉ lễ, nhiều người thích lựa chọn đi du lịch hoặc về nhà quây quần bên bố mẹ."}],"related":[{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"季节","pinyin":"jìjié","vi":"Mùa"},{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"},{"hanzi":"日","pinyin":"rì","vi":"Ngày"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"}],"traditional":"節日"},{"id":"春节","hanzi":"春节","pinyin":"Chūnjié","meaning_vi":"Tết Nguyên đán, Tết Âm lịch","explanation":"春 (mùa xuân) + 节 (lễ hội).","hsk_level":2,"tags":["danh-tu","thoi-gian","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"春节快乐！","pinyin":"Chūnjié kuàilè!","vi":"Chúc mừng năm mới (Tết Nguyên đán)!"},{"type":"simple","zh":"春节是中国人一年中最隆重、最热闹的传统节日。","pinyin":"Chūnjié shì Zhōngguórén yì niánzhōng zuì lóngzhòng, zuì rènao de chuántǒng jiérì.","vi":"Tết Nguyên đán là ngày lễ truyền thống long trọng và náo nhiệt nhất trong năm của người Trung Quốc."},{"type":"compound","zh":"不管平时工作有多忙，到了春节的时候，大家都会想办法回家吃年夜饭。","pinyin":"Bùguǎn píngshí gōngzuò yǒu duō máng, dàole Chūnjié de shíhou, dàjiā dōuhuì xiǎngbànfǎ huíjiā chī niányèfàn.","vi":"Bất kể bình thường công việc bận rộn đến đâu, đến dịp Tết mọi người đều tìm cách về nhà ăn bữa cơm tất niên."}],"related":[{"hanzi":"春天","pinyin":"chūntiān","vi":"Mùa xuân"},{"hanzi":"节日","pinyin":"jiérì","vi":"Ngày lễ"},{"hanzi":"饺子","pinyin":"jiǎozi","vi":"Sủi cảo"},{"hanzi":"热闹","pinyin":"rènao","vi":"Náo nhiệt"},{"hanzi":"快乐","pinyin":"kuàilè","vi":"Vui vẻ"}],"traditional":"春節"},{"id":"香蕉","hanzi":"香蕉","pinyin":"xiāngjiāo","meaning_vi":"quả chuối","explanation":"香 (thơm) + 蕉 (cây chuối).","hsk_level":2,"tags":["danh-tu","an-uong"],"image":"🍌","examples":[{"type":"basic","zh":"猴子喜欢吃香蕉。","pinyin":"Hóuzi xǐhuan chī xiāngjiāo.","vi":"Khỉ thích ăn chuối."},{"type":"simple","zh":"我每天早上运动以后都会吃一根香蕉，补充能量。","pinyin":"Wǒ měitiān zǎoshang yùndòng yǐhòu dōuhuì chī yìgēn xiāngjiāo, bǔchōng néngliàng.","vi":"Mỗi sáng sau khi vận động tôi đều ăn một quả chuối để bổ sung năng lượng."},{"type":"compound","zh":"这些黄色的香蕉又香又甜，而且价格也很便宜，我们多买一些吧。","pinyin":"Zhèxiē huángsè de xiāngjiāo yòu xiāng yòu tián, érqiě jiàgé yě hěn piányi, wǒmen duō mǎi yìxiē ba.","vi":"Những quả chuối màu vàng này vừa thơm vừa ngọt, giá cả lại rất rẻ, chúng ta mua thêm một ít nhé."}],"related":[{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"Trái cây"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"Quả táo"},{"hanzi":"西瓜","pinyin":"xīguā","vi":"Dưa hấu"},{"hanzi":"葡萄","pinyin":"pútao","vi":"Quả nho"},{"hanzi":"黄","pinyin":"huáng","vi":"Màu vàng"}]},{"id":"葡萄","hanzi":"葡萄","pinyin":"pútao","meaning_vi":"quả nho","explanation":"Cả hai chữ đều có bộ thảo 艹(thực vật).","hsk_level":2,"tags":["danh-tu","an-uong"],"image":"🍇","examples":[{"type":"basic","zh":"这些葡萄很甜。","pinyin":"Zhèxiē pútao hěn tián.","vi":"Những quả nho này rất ngọt."},{"type":"simple","zh":"妈妈买了一串紫色的葡萄，洗干净以后放在桌子上让大家吃。","pinyin":"Māma mǎile yíchuàn zǐsè de pútao, xǐ gānjìng yǐhòu fàng zài zhuōzi shang ràng dàjiā chī.","vi":"Mẹ đã mua một chùm nho màu tím, rửa sạch rồi đặt lên bàn cho mọi người ăn."},{"type":"compound","zh":"虽然这串葡萄看起来很漂亮，但是吃起来有点儿酸，没有苹果甜。","pinyin":"Suīrán zhè chuàn pútao kànqǐlái hěn piàoliang, dànshì chī qǐlái yǒudiǎnr suān, méiyǒu píngguǒ tián.","vi":"Tuy chùm nho này trông rất đẹp mắt nhưng ăn vào hơi chua một chút, không ngọt bằng táo."}],"related":[{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"Trái cây"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"Quả táo"},{"hanzi":"香蕉","pinyin":"xiāngjiāo","vi":"Quả chuối"},{"hanzi":"西瓜","pinyin":"xīguā","vi":"Dưa hấu"},{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"}]},{"id":"蛋糕","hanzi":"蛋糕","pinyin":"dàngāo","meaning_vi":"bánh ngọt, bánh kem","explanation":"蛋 (trứng) + 糕 (bánh).","hsk_level":2,"tags":["danh-tu","an-uong"],"image":"🍰","examples":[{"type":"basic","zh":"我买了一个生日蛋糕。","pinyin":"Wǒ mǎile yí ge shēngrì dàngāo.","vi":"Tôi đã mua một chiếc bánh kem sinh nhật."},{"type":"simple","zh":"这块巧克力蛋糕非常松软香甜，妹妹一下子吃了两块。","pinyin":"Zhè kuài qiǎokèlì dàngāo fēicháng sōngruǎn xiāngtián, mèimei yíxiàzi chīle liǎng kuài.","vi":"Miếng bánh kem sô cô la này vô cùng mềm xốp thơm ngọt, em gái ăn một lúc hết hai miếng."},{"type":"compound","zh":"虽然生日蛋糕非常好吃，但是因为糖分太高，所以晚上睡觉前不要吃太多。","pinyin":"Suīrán shēngrì dàngāo fēicháng hǎochī, dànshì yīnwèi tángfèn tài gāo, suǒyǐ wǎnshang shuìjiào qián bú yào chī tài duō.","vi":"Tuy bánh sinh nhật rất ngon nhưng vì lượng đường quá cao nên buổi tối trước khi đi ngủ đừng ăn quá nhiều."}],"related":[{"hanzi":"鸡蛋","pinyin":"jīdàn","vi":"Trứng gà"},{"hanzi":"面包","pinyin":"miànbāo","vi":"Bánh mì"},{"hanzi":"生日","pinyin":"shēngrì","vi":"Sinh nhật"},{"hanzi":"甜","pinyin":"tián","vi":"Ngọt"},{"hanzi":"块","pinyin":"kuài","vi":"Miếng"}]},{"id":"啤酒","hanzi":"啤酒","pinyin":"píjiǔ","meaning_vi":"bia","explanation":"啤 + 酒 (rượu, bộ thủy 氵).","hsk_level":2,"tags":["danh-tu","do-uong"],"image":"🍺","examples":[{"type":"basic","zh":"爸爸喜欢喝啤酒。","pinyin":"Bàba xǐhuan hē píjiǔ.","vi":"Bố thích uống bia."},{"type":"simple","zh":"夏天晚上和朋友一起吃烧烤、喝冰啤酒是一件很开心的事。","pinyin":"Xiàtiān wǎnshang hé péngyou yìqǐ chī shāokǎo, hē bīng píjiǔ shì yí jiàn hěn kāixīn de shì.","vi":"Buổi tối mùa hè cùng bạn bè ăn đồ nướng, uống bia lạnh là một việc rất vui vẻ."},{"type":"compound","zh":"虽然啤酒喝起来很凉快，但是开车之前绝对不能喝酒，要注意安全。","pinyin":"Suīrán píjiǔ hē qǐlái hěn liángkuai, dànshì kāichē zhīqián juéduì bù néng hējiǔ, yào zhùyì ānquán.","vi":"Tuy uống bia vào rất mát mẻ nhưng trước khi lái xe tuyệt đối không được uống rượu bia, phải chú ý an toàn."}],"related":[{"hanzi":"饮料","pinyin":"yǐnliào","vi":"Đồ uống"},{"hanzi":"喝","pinyin":"hē","vi":"Uống"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"茶","pinyin":"chá","vi":"Trà"},{"hanzi":"咖啡","pinyin":"kāfēi","vi":"Cà phê"}]},{"id":"饮料","hanzi":"饮料","pinyin":"yǐnliào","meaning_vi":"đồ uống, nước giải khát","explanation":"饮 (uống) + 料 (nguyên liệu).","hsk_level":2,"tags":["danh-tu","do-uong"],"image":"🧃","examples":[{"type":"basic","zh":"你想喝什么饮料？","pinyin":"Nǐ xiǎng hē shénme yǐnliào?","vi":"Bạn muốn uống đồ uống gì?"},{"type":"simple","zh":"这家超市的冰箱里有各种各样的果汁、茶和碳酸饮料。","pinyin":"Zhè jiā chāoshì de bīngxiāng lǐ yǒu gèzhǒng gèyàng de guǒzhī, chá hé tànsuānyǐnliào.","vi":"Trong tủ lạnh của siêu thị này có đủ các loại nước ép trái cây, trà và nước ngọt có ga."},{"type":"compound","zh":"医生建议青少年平时应该多喝白开水，少喝含糖量高的饮料。","pinyin":"Yīshēng jiànyì qīngshàonián píngshí yīnggāi duō hē báikāishuǐ, shǎo hē hán táng liàng gāo de yǐnliào.","vi":"Bác sĩ khuyên thanh thiếu niên bình thường nên uống nhiều nước đun sôi để nguội và uống ít nước giải khát nhiều đường."}],"related":[{"hanzi":"啤酒","pinyin":"píjiǔ","vi":"Bia"},{"hanzi":"水","pinyin":"shuǐ","vi":"Nước"},{"hanzi":"茶","pinyin":"chá","vi":"Trà"},{"hanzi":"咖啡","pinyin":"kāfēi","vi":"Cà phê"},{"hanzi":"牛奶","pinyin":"niúnǎi","vi":"Sữa bò"}],"traditional":"飲料"},{"id":"菜单","hanzi":"菜单","pinyin":"càidān","meaning_vi":"thực đơn","explanation":"菜 (món ăn) + 单 (danh sách).","hsk_level":2,"tags":["danh-tu","an-uong"],"image":"📋","examples":[{"type":"basic","zh":"请给我看一下菜单。","pinyin":"Qǐng gěi wǒ kàn yíxià càidān.","vi":"Xin cho tôi xem thực đơn một chút."},{"type":"simple","zh":"我们刚在饭店坐下来，热情的服务员就把菜单递了过来。","pinyin":"Wǒmen gāng zài fàndiàn zuò xiàlái, rèqíng de fúwùyuán jiù bǎ càidān dìle guòlái.","vi":"Chúng tôi vừa ngồi xuống trong nhà hàng thì nhân viên phục vụ niềm nở đã đưa thực đơn tới ngay."},{"type":"compound","zh":"虽然这本菜单上有很多中国菜的名字，但是旁边都有照片，点菜很方便。","pinyin":"Suīrán zhè běn càidān shang yǒu hěn duō Zhōngguócài de míngzi, dànshì pángbiān dōu yǒu zhàopiàn, diǎncài hěn fāngbiàn.","vi":"Tuy trên quyển thực đơn này có nhiều tên món ăn Trung Quốc nhưng bên cạnh đều có ảnh minh họa nên gọi món rất tiện."}],"related":[{"hanzi":"菜","pinyin":"cài","vi":"Món ăn"},{"hanzi":"饭店","pinyin":"fàndiàn","vi":"Nhà hàng"},{"hanzi":"服务员","pinyin":"fúwùyuán","vi":"Nhân viên phục vụ"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"Đơn giản"},{"hanzi":"吃","pinyin":"chī","vi":"Ăn"}],"traditional":"菜單"},{"id":"碗","hanzi":"碗","pinyin":"wǎn","meaning_vi":"cái bát, chén","explanation":"Bộ thạch 石 + 宛. Vừa là danh từ vừa là lượng từ (一碗米饭).","hsk_level":2,"tags":["danh-tu","do-vat"],"image":"🥣","examples":[{"type":"basic","zh":"我吃了两碗米饭。","pinyin":"Wǒ chīle liǎng wǎn mǐfàn.","vi":"Tôi đã ăn hai bát cơm."},{"type":"simple","zh":"每天吃完晚饭以后，我和弟弟都会主动帮妈妈洗碗。","pinyin":"Měitiān chīwán wǎnfàn yǐhòu, wǒ hé dìdi dōuhuì zhǔdòng bāng māma xǐwǎn.","vi":"Mỗi ngày sau khi ăn xong bữa tối, tôi và em trai đều chủ động giúp mẹ rửa bát."},{"type":"compound","zh":"今天中午我特别饿，一口气吃了两大碗牛肉面条和一碗鸡蛋汤。","pinyin":"Jīntiān zhōngwǔ wǒ tèbié è, yìkǒuqì chīle liǎng dà wǎn niúròu miàntiáo hé yì wǎn jīdàn tāng.","vi":"Trưa nay tôi đặc biệt đói, ăn một mạch hết hai bát to mì thịt bò và một bát canh trứng."}],"related":[{"hanzi":"筷子","pinyin":"kuàizi","vi":"Đôi đũa"},{"hanzi":"杯子","pinyin":"bēizi","vi":"Cái cốc"},{"hanzi":"米饭","pinyin":"mǐfàn","vi":"Cơm"},{"hanzi":"面条","pinyin":"miàntiáo","vi":"Mì sợi"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"}]},{"id":"筷子","hanzi":"筷子","pinyin":"kuàizi","meaning_vi":"đôi đũa","explanation":"Bộ trúc ⺮(làm bằng tre) + 快 + 子.","hsk_level":2,"tags":["danh-tu","do-vat","an-uong"],"image":"🥢","examples":[{"type":"basic","zh":"我会用筷子吃饭。","pinyin":"Wǒ huì yòng kuàizi chīfàn.","vi":"Tôi biết dùng đũa ăn cơm."},{"type":"simple","zh":"中国人吃饭一般都用筷子和碗，而西方人习惯用刀叉。","pinyin":"Zhōngguórén chīfàn yìbān dōu yòng kuàizi hé wǎn, ér Xīfāngrén xí guànyòng dāochā.","vi":"Người Trung Quốc ăn cơm thường dùng đũa và bát, còn người phương Tây quen dùng dao nĩa."},{"type":"compound","zh":"虽然他刚来中国的时候不会用筷子，但是练习了几天以后就用得很熟练了。","pinyin":"Suīrán tā gāng lái Zhōngguó de shíhou bú huì yòng kuàizi, dànshì liànxíle jǐtiān yǐhòu jiù yòng de hěn shúliàn le.","vi":"Tuy lúc mới đến Trung Quốc anh ấy không biết dùng đũa nhưng sau khi tập vài ngày thì đã dùng rất thành thạo."}],"related":[{"hanzi":"碗","pinyin":"wǎn","vi":"Cái bát"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"Ăn cơm"},{"hanzi":"桌子","pinyin":"zhuōzi","vi":"Cái bàn"},{"hanzi":"椅子","pinyin":"yǐzi","vi":"Cái ghế"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh"}]},{"id":"伞","hanzi":"伞","pinyin":"sǎn","meaning_vi":"cái ô, cây dù","explanation":"Chữ tượng hình chiếc ô xòe ra che mưa nắng.","hsk_level":2,"tags":["danh-tu","do-vat","thoi-tiet"],"image":"☂️","examples":[{"type":"basic","zh":"下雨了，别忘了带伞。","pinyin":"Xiàyǔ le, bié wàngle dài sǎn.","vi":"Trời mưa rồi, đừng quên mang theo ô."},{"type":"simple","zh":"门旁边放着一把蓝色的雨伞，那是昨天王老师忘在这里的。","pinyin":"Mén pángbiān fàngzhe yì bǎ lánsè de yǔsǎn, nàshì zuótiān Wáng lǎoshī wàng zài zhèlǐ de.","vi":"Bên cạnh cửa đang để một chiếc ô màu xanh dương, đó là chiếc ô hôm qua thầy Vương để quên ở đây."},{"type":"compound","zh":"夏天的天气变化很快，出门时最好在包里放一把伞，既能遮阳又能挡雨。","pinyin":"Xiàtiān de tiānqì biànhuà hěn kuài, chūmén shí zuì hǎozài bāo lǐ fàng yì bǎ sǎn, jì néng zhēyáng yòu néng dǎngyǔ.","vi":"Thời tiết mùa hè thay đổi rất nhanh, khi ra ngoài tốt nhất nên để một chiếc ô trong túi, vừa che nắng vừa chắn mưa."}],"related":[{"hanzi":"下雨","pinyin":"xiàyǔ","vi":"Trời mưa"},{"hanzi":"雨","pinyin":"yǔ","vi":"Mưa"},{"hanzi":"带","pinyin":"dài","vi":"Mang theo"},{"hanzi":"包","pinyin":"bāo","vi":"Túi xách"},{"hanzi":"晴天","pinyin":"qíngtiān","vi":"Ngày nắng"}],"traditional":"傘"},{"id":"包","hanzi":"包","pinyin":"bāo","meaning_vi":"cái túi, cặp sách, gói","explanation":"Vừa là danh từ (书包, 钱包) vừa là lượng từ (一包饼干).","hsk_level":2,"tags":["danh-tu","do-vat","trang-phuc"],"image":"👜","examples":[{"type":"basic","zh":"我的包在桌子上。","pinyin":"Wǒ de bāo zài zhuōzi shang.","vi":"Túi của tôi ở trên bàn."},{"type":"simple","zh":"妹妹每天背着她那个粉红色的新书包高高兴兴地去上学。","pinyin":"Mèimei měitiān bēizhe tā nà ge fěnhóngsè de xīn shūbāo gāo gāoxìng xìng de qù shàngxué.","vi":"Em gái mỗi ngày đeo chiếc cặp sách mới màu hồng của mình vui vẻ đi học."},{"type":"compound","zh":"下车的时候一定要检查好随身携带的包，别把手机和钱包忘在车上了。","pinyin":"Xiàchē de shíhou yídìngyào jiǎnchá hǎo suíshēn xiédài de bāo, bié bǎshǒu jī hé qiánbāo wàng zài chē shang le.","vi":"Lúc xuống xe nhất định phải kiểm tra kỹ túi xách mang theo bên mình, đừng để quên điện thoại và ví tiền trên xe."}],"related":[{"hanzi":"书包","pinyin":"shūbāo","vi":"Cặp sách"},{"hanzi":"钱包","pinyin":"qiánbāo","vi":"Ví tiền"},{"hanzi":"包子","pinyin":"bāozi","vi":"Bánh bao"},{"hanzi":"面包","pinyin":"miànbāo","vi":"Bánh mì"},{"hanzi":"行李箱","pinyin":"xínglixiāng","vi":"Vali"}]},{"id":"空调","hanzi":"空调","pinyin":"kōngtiáo","meaning_vi":"máy điều hòa nhiệt độ","explanation":"空 (không khí) + 调 (điều chỉnh).","hsk_level":2,"tags":["danh-tu","do-vat","cong-nghe"],"image":"❄️","examples":[{"type":"basic","zh":"房间里开着空调。","pinyin":"Fángjiān lǐ kāizhe kōngtiáo.","vi":"Trong phòng đang bật điều hòa."},{"type":"simple","zh":"夏天外面的天气特别热，一回到家我就把空调打开了。","pinyin":"Xiàtiān wàimiàn de tiānqì tèbié rè, yì huí dàojiā wǒ jiù bǎ kōngtiáo dǎkāi le.","vi":"Mùa hè thời tiết bên ngoài đặc biệt nóng, vừa về đến nhà là tôi bật điều hòa ngay."},{"type":"compound","zh":"虽然吹空调很凉快，但是温度不要调得太低，否则很容易感冒。","pinyin":"Suīrán chuī kōngtiáo hěn liángkuai, dànshì wēndù bú yào tiáo de tài dī, fǒuzé hěn róngyì gǎnmào.","vi":"Tuy bật điều hòa rất mát nhưng nhiệt độ đừng chỉnh thấp quá, nếu không sẽ rất dễ bị cảm cúm."}],"related":[{"hanzi":"空气","pinyin":"kōngqì","vi":"Không khí"},{"hanzi":"凉快","pinyin":"liángkuai","vi":"Mát mẻ"},{"hanzi":"热","pinyin":"rè","vi":"Nóng"},{"hanzi":"开","pinyin":"kāi","vi":"Bật/Mở"},{"hanzi":"关","pinyin":"guān","vi":"Tắt/Đóng"}],"traditional":"空調"},{"id":"已经","hanzi":"已经","pinyin":"yǐjīng","meaning_vi":"đã, rồi","explanation":"Biểu thị hành động đã hoàn thành hoặc trạng thái đã đạt tới (我已经吃饭了).","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"✔️","examples":[{"type":"basic","zh":"我已经吃过晚饭了。","pinyin":"Wǒ yǐjīng chīguo wǎnfàn le.","vi":"Tôi đã ăn bữa tối rồi."},{"type":"simple","zh":"现在已经晚上十一点多了，你快点儿关灯睡觉吧。","pinyin":"Xiànzài yǐjīng wǎnshang shí yīdiǎn duō le, nǐ kuàidiǎnr guān dēng shuìjiào ba.","vi":"Bây giờ đã hơn 11 giờ đêm rồi, bạn mau tắt đèn đi ngủ đi."},{"type":"compound","zh":"虽然我来中国还不到一年，但是我已经去过北京、上海和西安等很多城市了。","pinyin":"Suīrán wǒ lái Zhōngguó hái búdào yì nián, dànshì wǒ yǐjīng qùguo Běijīng, Shànghǎi hé Xī'ān děng hěn duō chéngshì le.","vi":"Tuy tôi đến Trung Quốc chưa đầy một năm nhưng tôi đã từng đi qua nhiều thành phố như Bắc Kinh, Thượng Hải và Tây An."}],"related":[{"hanzi":"正在","pinyin":"zhèngzài","vi":"Đang"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"了","pinyin":"le","vi":"Rồi"}],"traditional":"已經"},{"id":"正在","hanzi":"正在","pinyin":"zhèngzài","meaning_vi":"đang","explanation":"Nhấn mạnh hành động đang diễn ra tại thời điểm nói (我正在看书).","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"他正在房间里看书。","pinyin":"Tā zhèngzài fángjiān lǐ kànshū.","vi":"Anh ấy đang đọc sách trong phòng."},{"type":"simple","zh":"刚才你给我打电话的时候，我正在厨房里帮妈妈做晚饭呢。","pinyin":"Gāngcái nǐ gěi wǒ dǎdiànhuà de shíhou, wǒ zhèngzài chúfáng lǐ bāng māma zuò wǎnfàn ne.","vi":"Vừa nãy lúc bạn gọi điện cho tôi thì tôi đang giúp mẹ nấu bữa tối trong bếp."},{"type":"compound","zh":"因为老师正在教室里给同学们讲课，所以我们进去的时候要保持安静。","pinyin":"Yīnwèi lǎoshī zhèngzài jiàoshì lǐ gěi tóngxuémen jiǎngkè, suǒyǐ wǒmen jìnqù de shíhou yào bǎochí ānjìng.","vi":"Vì thầy giáo đang giảng bài cho các bạn học trong lớp nên lúc bước vào chúng ta phải giữ trật tự."}],"related":[{"hanzi":"在","pinyin":"zài","vi":"Đang/Ở"},{"hanzi":"已经","pinyin":"yǐjīng","vi":"Đã"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"着","pinyin":"zhe","vi":"Đang"},{"hanzi":"呢","pinyin":"ne","vi":"Đấy/Nhỉ"}]},{"id":"马上","hanzi":"马上","pinyin":"mǎshàng","meaning_vi":"lập tức, ngay bây giờ","explanation":"马 (ngựa) + 上 (lên) → phi ngựa đi ngay, chỉ thời gian rất ngắn sắp tới.","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"⚡","examples":[{"type":"basic","zh":"我马上就到学校了。","pinyin":"Wǒ mǎshàng jiù dào xuéxiào le.","vi":"Tôi sắp đến trường ngay đây."},{"type":"simple","zh":"电影马上就要开始了，大家快点儿进去吧！","pinyin":"Diànyǐng mǎshàng jiùyào kāishǐ le, dàjiā kuàidiǎnr jìnqù ba!","vi":"Phim sắp bắt đầu ngay rồi, mọi người mau vào đi!"},{"type":"compound","zh":"妈妈一听到弟弟生病发烧的消息，马上放下手里的工作赶去了医院。","pinyin":"Māma yì tīngdào dìdi shēngbìng fāshāo de xiāoxi, mǎshàng fàngxià shǒulǐ de gōngzuò gǎn qùle yīyuàn.","vi":"Mẹ vừa nghe tin em trai bị ốm sốt liền lập tức gác lại công việc trên tay chạy ngay tới bệnh viện."}],"related":[{"hanzi":"立刻","pinyin":"lìkè","vi":"Lập tức"},{"hanzi":"就","pinyin":"jiù","vi":"Liền/Ngay"},{"hanzi":"快","pinyin":"kuài","vi":"Nhanh/Sắp"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"骑","pinyin":"qí","vi":"Cưỡi"}],"traditional":"馬上"},{"id":"刚才","hanzi":"刚才","pinyin":"gāngcái","meaning_vi":"vừa nãy, lúc nãy","explanation":"Danh từ/phó từ chỉ thời gian vừa mới trôi qua (他刚才出去了).","hsk_level":2,"tags":["danh-tu","thoi-gian"],"image":"⏮️","examples":[{"type":"basic","zh":"他刚才出去了。","pinyin":"Tā gāngcái chūqù le.","vi":"Anh ấy vừa nãy đi ra ngoài rồi."},{"type":"simple","zh":"刚才王老师来办公室找过你，让你回来以后给他回个电话。","pinyin":"Gāngcái Wáng lǎoshī lái bàngōngshì zhǎoguo nǐ, ràng nǐ huílái yǐhòu gěi tā huí ge diànhuà.","vi":"Vừa nãy thầy Vương có tới văn phòng tìm bạn, dặn bạn về thì gọi lại cho thầy một cuộc."},{"type":"compound","zh":"我刚才明明把手机放在桌子上了，怎么一转眼就找不到了呢？","pinyin":"Wǒ gāngcái míngmíng bǎshǒu jī fàng zài zhuōzi shang le, zěnme yìzhuǎnyǎn jiù zhǎobúdàole ne?","vi":"Vừa nãy rõ ràng tôi đặt điện thoại trên bàn mà sao chớp mắt một cái đã không tìm thấy nữa rồi nhỉ?"}],"related":[{"hanzi":"刚刚","pinyin":"gānggāng","vi":"Vừa mới"},{"hanzi":"现在","pinyin":"xiànzài","vi":"Bây giờ"},{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"Sau này"},{"hanzi":"才","pinyin":"cái","vi":"Mới"}],"traditional":"剛才"},{"id":"以前","hanzi":"以前","pinyin":"yǐqián","meaning_vi":"trước đây, trước khi","explanation":"以 + 前 (trước). Chỉ quá khứ nói chung hoặc thời điểm trước một hành động.","hsk_level":2,"tags":["danh-tu","thoi-gian"],"image":"⏪","examples":[{"type":"basic","zh":"我以前住在北京。","pinyin":"Wǒ yǐqián zhùzài Běijīng.","vi":"Trước đây tôi sống ở Bắc Kinh."},{"type":"simple","zh":"每天晚上睡觉以前，我都会喝一杯热牛奶并看半个小时书。","pinyin":"Měitiān wǎnshang shuìjiào yǐqián, wǒ dōuhuì hē yì bēi rè niúnǎi bìng kàn bàn ge xiǎoshí shū.","vi":"Mỗi tối trước khi đi ngủ, tôi đều uống một cốc sữa nóng và đọc sách nửa tiếng."},{"type":"compound","zh":"虽然我以前从来没有学过游泳，但是在教练的帮助下我很快就学会了。","pinyin":"Suīrán wǒ yǐqián cónglái méiyǒu xuéguo yóuyǒng, dànshì zài jiàoliàn de bāngzhù xià wǒ hěn kuài jiù xuéhuì le.","vi":"Tuy trước đây tôi chưa từng học bơi bao giờ nhưng dưới sự hướng dẫn của huấn luyện viên tôi đã học được rất nhanh."}],"related":[{"hanzi":"以后","pinyin":"yǐhòu","vi":"sau này"},{"hanzi":"从前","pinyin":"cóngqián","vi":"trước kia"},{"hanzi":"过去","pinyin":"guòqù","vi":"quá khứ"},{"hanzi":"已经","pinyin":"yǐjīng","vi":"đã"}]},{"id":"以后","hanzi":"以后","pinyin":"yǐhòu","meaning_vi":"sau này, sau khi","explanation":"以 + 后 (sau). Chỉ tương lai nói chung hoặc thời điểm sau một hành động.","hsk_level":2,"tags":["danh-tu","thoi-gian"],"image":"⏩","examples":[{"type":"basic","zh":"下课以后我们去吃饭吧。","pinyin":"Xiàkè yǐhòu wǒmen qù chīfàn ba.","vi":"Sau khi tan học chúng ta đi ăn cơm nhé."},{"type":"simple","zh":"大学毕业以后，我想去中国的一家跨国公司工作。","pinyin":"Dàxué bìyè yǐhòu, wǒ xiǎng qù Zhōngguó de yìjiā kuàguógōngsī gōngzuò.","vi":"Sau khi tốt nghiệp đại học, tôi muốn làm việc tại một công ty đa quốc gia ở Trung Quốc."},{"type":"compound","zh":"来到中国留学以后，我不仅提高了汉语水平，而且还交到了很多好朋友。","pinyin":"Láidào Zhōngguó liúxué yǐhòu, wǒ bùjǐn tígāole Hànyǔ shuǐpíng, érqiě hái jiāo dàole hěn duō hǎopéngyou.","vi":"Sau khi đến Trung Quốc du học, tôi không chỉ nâng cao trình độ tiếng Trung mà còn kết giao được nhiều bạn tốt."}],"related":[{"hanzi":"以前","pinyin":"yǐqián","vi":"Trước đây"},{"hanzi":"后","pinyin":"hòu","vi":"Sau"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"最后","pinyin":"zuìhòu","vi":"Cuối cùng"},{"hanzi":"将来","pinyin":"jiānglái","vi":"Tương lai"}],"traditional":"以後"},{"id":"经常","hanzi":"经常","pinyin":"jīngcháng","meaning_vi":"thường xuyên","explanation":"经 + 常 (thường). Biểu thị tần suất xảy ra cao.","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"🔁","examples":[{"type":"basic","zh":"我经常去图书馆看书。","pinyin":"Wǒ jīngcháng qù túshūguǎn kànshū.","vi":"Tôi thường xuyên đến thư viện đọc sách."},{"type":"simple","zh":"周末的时候，我和哥哥经常一起去体育馆打篮球或者游泳。","pinyin":"Zhōumò de shíhou, wǒ hé gēge jīngcháng yìqǐ qù tǐyùguǎn dǎlánqiú huòzhě yóuyǒng.","vi":"Vào cuối tuần, tôi và anh trai thường xuyên cùng đến nhà thi đấu chơi bóng rổ hoặc bơi lội."},{"type":"compound","zh":"因为爸爸的工作需要经常去外地出差，所以他每个月只有几天在家。","pinyin":"Yīnwèi bàba de gōngzuò xūyào jīngcháng qù wàidì chūchāi, suǒyǐ tā měi geyuè zhǐyǒu jǐtiān zài jiā.","vi":"Vì công việc của bố cần thường xuyên đi công tác xa nên mỗi tháng bố chỉ ở nhà có mấy ngày."}],"related":[{"hanzi":"总是","pinyin":"zǒngshì","vi":"Luôn luôn"},{"hanzi":"有时","pinyin":"yǒushí","vi":"Thỉnh thoảng"},{"hanzi":"经过","pinyin":"jīngguò","vi":"Đi qua"},{"hanzi":"非常","pinyin":"fēicháng","vi":"Vô cùng"},{"hanzi":"一般","pinyin":"yìbān","vi":"Thường thường"}],"traditional":"經常"},{"id":"总是","hanzi":"总是","pinyin":"zǒngshì","meaning_vi":"luôn luôn, lúc nào cũng","explanation":"总 (tổng/luôn) + 是 (là).","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"♾️","examples":[{"type":"basic","zh":"他总是迟到。","pinyin":"Tā zǒngshì chídào.","vi":"Anh ấy lúc nào cũng đến muộn."},{"type":"simple","zh":"王老师对学生非常有耐心，每次回答问题时脸上总是带着微笑。","pinyin":"Wáng lǎoshī duì xuésheng fēicháng yǒu nàixīn, měi cì huídá wèntí shí liǎn shang zǒngshì dàizhe wēixiào.","vi":"Thầy Vương đối với học sinh vô cùng kiên nhẫn, mỗi lần trả lời câu hỏi trên mặt luôn nở nụ cười."},{"type":"compound","zh":"虽然妈妈每天工作都很忙，但是她总是把家里收拾得干干净净的。","pinyin":"Suīrán māma měitiān gōngzuò dōu hěn máng, dànshì tā zǒngshì bǎ jiālǐ shōushi de gān gānjìng jìng de.","vi":"Tuy mỗi ngày mẹ làm việc đều rất bận nhưng mẹ luôn dọn dẹp nhà cửa sạch sẽ tinh tươm."}],"related":[{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"有时","pinyin":"yǒushí","vi":"Thỉnh thoảng"},{"hanzi":"一直","pinyin":"yìzhí","vi":"Suốt/Luôn"},{"hanzi":"是","pinyin":"shì","vi":"Là"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"}],"traditional":"總是"},{"id":"有时","hanzi":"有时","pinyin":"yǒushí","meaning_vi":"có lúc, thỉnh thoảng","explanation":"有 (có) + 时 (lúc). Dạng rút gọn của 有时候.","hsk_level":2,"tags":["pho-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"我有时坐地铁上班。","pinyin":"Wǒ yǒushí zuò dìtiě shàngbān.","vi":"Thỉnh thoảng tôi đi tàu điện ngầm đi làm."},{"type":"simple","zh":"周末我一般在家里休息，有时也会和朋友一起去看电影。","pinyin":"Zhōumò wǒ yìbān zài jiālǐ xiūxi, yǒushí yě huì hé péngyou yìqǐ qù kàndiànyǐng.","vi":"Cuối tuần tôi thường nghỉ ngơi ở nhà, thỉnh thoảng cũng đi xem phim cùng bạn bè."},{"type":"compound","zh":"北京春天的天气变化很快，有时上午还是晴天，下午就刮起大风了。","pinyin":"Běijīng chūntiān de tiānqì biànhuà hěn kuài, yǒushí shàngwǔ háishi qíngtiān, xiàwǔ jiù guā qǐ dàfēng le.","vi":"Thời tiết mùa xuân ở Bắc Kinh thay đổi rất nhanh, có lúc buổi sáng vẫn nắng đẹp mà buổi chiều đã nổi gió lớn rồi."}],"related":[{"hanzi":"有时候","pinyin":"yǒushíhou","vi":"Có lúc"},{"hanzi":"经常","pinyin":"jīngcháng","vi":"Thường xuyên"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"Luôn luôn"},{"hanzi":"时间","pinyin":"shíjiān","vi":"Thời gian"},{"hanzi":"偶尔","pinyin":"ǒu'ěr","vi":"Thi thoảng"}],"traditional":"有時"},{"id":"突然","hanzi":"突然","pinyin":"tūrán","meaning_vi":"đột nhiên, bỗng nhiên","explanation":"突 (xông ra) + 然.","hsk_level":2,"tags":["pho-tu","tinh-tu"],"image":"⚡","examples":[{"type":"basic","zh":"外面突然下雨了。","pinyin":"Wàimiàn tūrán xiàyǔ le.","vi":"Bên ngoài đột nhiên đổ mưa rồi."},{"type":"simple","zh":"我们正在公园里散步，天空突然暗了下来，紧接着就下起了大雨。","pinyin":"Wǒmen zhèngzài gōngyuán lǐ sànbù, tiānkōng tūrán ànle xiàlái, jǐnjiēzhe jiù xià qǐle dàyǔ.","vi":"Chúng tôi đang đi dạo trong công viên thì bầu trời đột nhiên tối sầm lại, ngay sau đó liền đổ mưa lớn."},{"type":"compound","zh":"因为今天早上我的电脑突然坏了，所以我只好借同事的电脑完成报告。","pinyin":"Yīnwèi jīntiān zǎoshang wǒ de diànnǎo tūrán huàile, suǒyǐ wǒ zhǐhǎo jiè tóngshì de diànnǎo wánchéng bàogào.","vi":"Vì sáng nay máy tính của tôi đột nhiên bị hỏng nên tôi đành mượn máy tính của đồng nghiệp để hoàn thành báo cáo."}],"related":[{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"Lập tức"},{"hanzi":"忽然","pinyin":"hūrán","vi":"Bỗng nhiên"},{"hanzi":"变化","pinyin":"biànhuà","vi":"Thay đổi"},{"hanzi":"意外","pinyin":"yìwài","vi":"Bất ngờ"}]},{"id":"必须","hanzi":"必须","pinyin":"bìxū","meaning_vi":"nhất định phải, bắt buộc","explanation":"必 (tất yếu) + 须 (cần phải).","hsk_level":2,"tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"我们必须努力学习。","pinyin":"Wǒmen bìxū nǔlì xuéxí.","vi":"Chúng ta nhất định phải nỗ lực học tập."},{"type":"simple","zh":"坐飞机出国旅游的时候，大家必须随身带好自己的有效护照。","pinyin":"Zuòfēijī chūguó lǚyóu de shíhou, dàjiā bìxū suíshēndài hǎo zìjǐ de yǒuxiào hùzhào.","vi":"Khi đi máy bay du lịch nước ngoài, mọi người bắt buộc phải mang theo hộ chiếu còn hiệu lực bên mình."},{"type":"compound","zh":"为了保护大家的身体健康，医院规定进入病房时必须戴好口罩。","pinyin":"Wèile bǎohù dàjiā de shēntǐ jiànkāng, yīyuàn guīdìng jìnrù bìngfáng shí bìxū dài hǎo kǒuzhào.","vi":"Để bảo vệ sức khỏe của mọi người, bệnh viện quy định khi vào phòng bệnh bắt buộc phải đeo khẩu trang."}],"related":[{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"需要","pinyin":"xūyào","vi":"Cần"},{"hanzi":"要","pinyin":"yào","vi":"Phải/Cần"},{"hanzi":"应该","pinyin":"yīnggāi","vi":"Nên"},{"hanzi":"必要","pinyin":"bìyào","vi":"Cần thiết"}],"traditional":"必須"},{"id":"一定","hanzi":"一定","pinyin":"yídìng","meaning_vi":"nhất định, chắc chắn","explanation":"一 (một) + 定 (quyết định).","hsk_level":2,"tags":["pho-tu","tinh-tu"],"image":"💯","examples":[{"type":"basic","zh":"我明天一定去。","pinyin":"Wǒ míngtiān yídìng qù.","vi":"Ngày mai tôi nhất định sẽ đi."},{"type":"simple","zh":"只要你每天坚持练习说汉语，你的口语水平一定会越来越好。","pinyin":"Zhǐyào nǐ měitiān jiānchí liànxí shuō Hànyǔ, nǐ de kǒuyǔ shuǐpíng yídìng huì yuèláiyuè hǎo.","vi":"Chỉ cần mỗi ngày bạn kiên trì luyện nói tiếng Trung thì trình độ khẩu ngữ của bạn nhất định sẽ ngày càng tốt hơn."},{"type":"compound","zh":"虽然这次考试的题目很难，但是我相信凭你的努力一定能考出好成绩。","pinyin":"Suīrán zhè cì kǎoshì de tímù hěn nán, dànshì wǒ xiāngxìn píng nǐ de nǔlì yídìng néng kǎo chū hǎo chéngjì.","vi":"Tuy đề thi lần này rất khó nhưng tôi tin với sự nỗ lực của bạn nhất định sẽ thi được điểm cao."}],"related":[{"hanzi":"必须","pinyin":"bìxū","vi":"Bắt buộc"},{"hanzi":"决定","pinyin":"juédìng","vi":"Quyết định"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có thể"},{"hanzi":"一","pinyin":"yī","vi":"Một"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"Khẳng định"}]},{"id":"可能","hanzi":"可能","pinyin":"kěnéng","meaning_vi":"có thể, có lẽ","explanation":"可 (có thể) + 能 (khả năng). Biểu thị sự phỏng đoán.","hsk_level":2,"tags":["pho-tu","dong-tu"],"image":"🤔","examples":[{"type":"basic","zh":"今天下午可能会下雨。","pinyin":"Jīntiān xiàwǔ kěnéng huì xiàyǔ.","vi":"Chiều nay có lẽ sẽ mưa."},{"type":"simple","zh":"天上飘来了这么多乌云，看样子今天下午很可能会下大雨。","pinyin":"Tiānshang piāo láile zhème duō wūyún, kànyàngzi jīntiān xiàwǔ hěn kěnéng huì xià dàyǔ.","vi":"Trên trời kéo đến nhiều mây đen thế này, xem chừng chiều nay rất có thể sẽ mưa to."},{"type":"compound","zh":"因为今天路上堵车很严重，所以我可能要晚十分钟才能到饭店。","pinyin":"Yīnwèi jīntiān lùshang dǔchē hěn yánzhòng, suǒyǐ wǒ kěnéng yào wǎn shí fēnzhōng cáinéng dào fàndiàn.","vi":"Vì hôm nay trên đường tắc xe nghiêm trọng nên tôi có thể sẽ đến nhà hàng muộn 10 phút."}],"related":[{"hanzi":"能","pinyin":"néng","vi":"Có thể"},{"hanzi":"可以","pinyin":"kěyǐ","vi":"Có thể"},{"hanzi":"一定","pinyin":"yídìng","vi":"Nhất định"},{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"会","pinyin":"huì","vi":"Sẽ"}]},{"id":"大概","hanzi":"大概","pinyin":"dàgài","meaning_vi":"khoảng chừng, đại khái","explanation":"大 (lớn) + 概 (khái quát).","hsk_level":2,"tags":["pho-tu"],"image":"📊","examples":[{"type":"basic","zh":"他大概二十五岁。","pinyin":"Tā dàgài èr shíwǔ suì.","vi":"Anh ấy khoảng chừng 25 tuổi."},{"type":"simple","zh":"从我家坐地铁去机场，路上大概需要四十五分钟左右。","pinyin":"Cóng wǒ jiā zuò dìtiě qù jīchǎng, lùshang dàgài xūyào sì shíwǔ fēnzhōng zuǒyòu.","vi":"Đi tàu điện ngầm từ nhà tôi ra sân bay mất khoảng chừng 45 phút."},{"type":"compound","zh":"虽然这篇文章里有一些生词我不认识，但是我大概看懂了它的意思。","pinyin":"Suīrán zhè piān wénzhāng lǐ yǒuyìxiē shēngcí wǒ bú rènshi, dànshì wǒ dàgài kàndǒngle tā de yìsi.","vi":"Tuy trong bài văn này có một số từ mới tôi không biết nhưng tôi đại khái đã đọc hiểu ý của nó."}],"related":[{"hanzi":"可能","pinyin":"kěnéng","vi":"Có lẽ"},{"hanzi":"左右","pinyin":"zuǒyòu","vi":"Khoảng chừng"},{"hanzi":"大","pinyin":"dà","vi":"Lớn"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"Xấp xỉ"},{"hanzi":"几乎","pinyin":"jīhū","vi":"Hầu như"}]},{"id":"几乎","hanzi":"几乎","pinyin":"jīhū","meaning_vi":"hầu như, gần như","explanation":"几 (cơ – gần, sắp) + 乎 (hồ – trợ từ) → gần như, hầu như; cũng nghĩa suýt nữa. Ví dụ 几乎所有人 (hầu như tất cả mọi người).","hsk_level":2,"tags":["pho-tu"],"image":"🤏","examples":[{"type":"basic","zh":"我几乎每天都运动。","pinyin":"Wǒ jīhū měitiān dōu yùndòng.","vi":"Tôi hầu như ngày nào cũng vận động."},{"type":"simple","zh":"全班二十五个同学几乎都去过北京长城参观。","pinyin":"Quánbān èr shíwǔ ge tóngxué jīhū dōu qùguo Běijīng Chángchéng cānguān.","vi":"Hầu như tất cả 25 bạn học trong lớp đều đã từng đi tham quan Vạn Lý Trường Thành ở Bắc Kinh."},{"type":"compound","zh":"因为昨天晚上一直在复习功课，所以我几乎一整夜都没有睡觉。","pinyin":"Yīnwèi zuótiān wǎnshang yìzhí zài fùxí gōngkè, suǒyǐ wǒ jīhū yì zhěngyè dōu méiyǒu shuìjiào.","vi":"Vì tối hôm qua ôn bài suốt nên tôi hầu như thức trắng cả đêm không ngủ."}],"related":[{"hanzi":"大概","pinyin":"dàgài","vi":"Khoảng chừng"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"Gần như"},{"hanzi":"几","pinyin":"jǐ","vi":"Mấy"},{"hanzi":"全部","pinyin":"quánbù","vi":"Toàn bộ"},{"hanzi":"完全","pinyin":"wánquán","vi":"Hoàn toàn"}],"traditional":"幾乎"},{"id":"其实","hanzi":"其实","pinyin":"qíshí","meaning_vi":"thực ra, kỳ thực","explanation":"其 (đó) + 实 (sự thật).","hsk_level":2,"tags":["pho-tu"],"image":"💡","examples":[{"type":"basic","zh":"其实汉语并不难。","pinyin":"Qíshí Hànyǔ bìng bùnán.","vi":"Thực ra tiếng Trung không hề khó."},{"type":"simple","zh":"表面上看起来他很严肃，其实他是一个非常幽默热情的人。","pinyin":"Biǎomiànshang kànqǐlái tā hěn yánsù, qíshí tā shì yí ge fēicháng yōumò rèqíng de rén.","vi":"Bề ngoài trông anh ấy có vẻ nghiêm nghị, thực ra anh ấy là một người vô cùng hài hước và nhiệt tình."},{"type":"compound","zh":"很多人以为学写汉字很难，其实只要掌握了偏旁部首就非常容易记住。","pinyin":"Hěn duō rén yǐwéi xué xiě hànzì hěn nán, qíshí zhǐyào zhǎngwòle piānpángbùshǒu jiù fēicháng róngyì jìzhù.","vi":"Nhiều người cứ tưởng học viết chữ Hán rất khó, thực ra chỉ cần nắm vững bộ thủ thì sẽ rất dễ nhớ."}],"related":[{"hanzi":"以为","pinyin":"yǐwéi","vi":"Tưởng rằng"},{"hanzi":"实际","pinyin":"shíjì","vi":"Thực tế"},{"hanzi":"真","pinyin":"zhēn","vi":"Thật"},{"hanzi":"其他","pinyin":"qítā","vi":"Khác"},{"hanzi":"实在","pinyin":"shízài","vi":"Thật sự"}],"traditional":"其實"},{"id":"虽然","hanzi":"虽然","pinyin":"suīrán","meaning_vi":"tuy rằng, mặc dù","explanation":"Thường dùng với 但是 / 可是 để tạo câu phức chuyển ngoặt.","hsk_level":2,"tags":["lien-tu"],"image":"↩️","examples":[{"type":"basic","zh":"虽然很累，但是很开心。","pinyin":"Suīrán hěn lèi, dànshì hěn kāixīn.","vi":"Tuy rất mệt nhưng rất vui."},{"type":"simple","zh":"虽然今天外面下着大雪，但是同学们还是准时到教室上课了。","pinyin":"Suīrán jīntiān wàimiàn xiàzhe Dàxuě, dànshì tóngxuémen háishi zhǔnshí dào jiàoshì shàngkè le.","vi":"Tuy hôm nay bên ngoài đang có tuyết rơi lớn nhưng các bạn học vẫn đến lớp học đúng giờ."},{"type":"compound","zh":"虽然我学习汉语的时间只有半年，但是我已经能用汉语和中国人聊天了。","pinyin":"Suīrán wǒ xuéxí Hànyǔ de shíjiān zhǐyǒu bàn nián, dànshì wǒ yǐjīng néng yòng Hànyǔ hé Zhōngguórén liáotiān le.","vi":"Tuy thời gian tôi học tiếng Trung mới chỉ nửa năm nhưng tôi đã có thể dùng tiếng Trung trò chuyện với người Trung Quốc rồi."}],"related":[{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"可是","pinyin":"kěshì","vi":"Nhưng mà"},{"hanzi":"突然","pinyin":"tūrán","vi":"Đột nhiên"},{"hanzi":"然后","pinyin":"ránhòu","vi":"Sau đó"},{"hanzi":"不过","pinyin":"búguò","vi":"Tuy nhiên"}],"traditional":"雖然"},{"id":"可是","hanzi":"可是","pinyin":"kěshì","meaning_vi":"nhưng, nhưng mà","explanation":"Tương đương 但是, dùng phổ biến trong văn nói.","hsk_level":2,"tags":["lien-tu"],"image":"↔️","examples":[{"type":"basic","zh":"我想去，可是没时间。","pinyin":"Wǒ xiǎng qù, kěshì méi shíjiān.","vi":"Tôi muốn đi nhưng không có thời gian."},{"type":"simple","zh":"这件白色的裙子非常漂亮，可是价格太贵了，我买不起。","pinyin":"Zhè jiàn báisè de qúnzi fēicháng piàoliang, kěshì jiàgé tài guì le, wǒ mǎibùqǐ.","vi":"Chiếc váy màu trắng này rất đẹp nhưng giá đắt quá, tôi không mua nổi."},{"type":"compound","zh":"我本来打算周末去公园爬山，可是天气预报说周末会有大暴雨。","pinyin":"Wǒ běnlái dǎsuàn zhōumò qù gōngyuán páshān, kěshì tiānqì yùbào shuō zhōumò huì yǒu dà bàoyǔ.","vi":"Tôi vốn định cuối tuần đi công viên leo núi nhưng dự báo thời tiết nói cuối tuần sẽ có mưa lớn."}],"related":[{"hanzi":"但是","pinyin":"dànshì","vi":"Nhưng"},{"hanzi":"虽然","pinyin":"suīrán","vi":"Tuy rằng"},{"hanzi":"可以","pinyin":"kěyǐ","vi":"Có thể"},{"hanzi":"可能","pinyin":"kěnéng","vi":"Có lẽ"},{"hanzi":"不过","pinyin":"búguò","vi":"Tuy nhiên"}]},{"id":"如果","hanzi":"如果","pinyin":"rúguǒ","meaning_vi":"nếu, nếu như","explanation":"Thường đi cặp với 就 (如果...就... - nếu... thì...).","hsk_level":2,"tags":["lien-tu"],"image":"❓","examples":[{"type":"basic","zh":"如果下雨，我就不去了。","pinyin":"Rúguǒ xiàyǔ, wǒ jiù bú qù le.","vi":"Nếu trời mưa thì tôi sẽ không đi nữa."},{"type":"simple","zh":"如果你明天上午有时间，欢迎来我家喝茶聊天。","pinyin":"Rúguǒ nǐ míngtiān shàngwǔ yǒu shíjiān, huānyíng lái wǒ jiā hēchá liáotiān.","vi":"Nếu sáng mai bạn có thời gian, hoan nghênh đến nhà tôi uống trà trò chuyện."},{"type":"compound","zh":"如果在学习汉语的过程中遇到任何困难，你都可以随时来办公室找我。","pinyin":"Rúguǒ zài xuéxí Hànyǔ de guòchéng zhōng yùdào rènhé kùnnan, nǐ dōu kěyǐ suíshí lái bàngōngshì zhǎo wǒ.","vi":"Nếu trong quá trình học tiếng Trung gặp bất kỳ khó khăn nào, bạn đều có thể đến văn phòng tìm tôi bất cứ lúc nào."}],"related":[{"hanzi":"就","pinyin":"jiù","vi":"Thì/Liền"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"Trái cây"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"Quả táo"},{"hanzi":"假如","pinyin":"jiǎrú","vi":"Giả sử"},{"hanzi":"要是","pinyin":"yàoshi","vi":"Nếu như"}]},{"id":"或者","hanzi":"或者","pinyin":"huòzhě","meaning_vi":"hoặc là","explanation":"Dùng trong câu trần thuật để nêu khả năng lựa chọn (khác với 还是 dùng trong câu hỏi).","hsk_level":2,"tags":["lien-tu"],"image":"🔀","examples":[{"type":"basic","zh":"我喜欢喝茶或者咖啡。","pinyin":"Wǒ xǐhuan hēchá huòzhě kāfēi.","vi":"Tôi thích uống trà hoặc cà phê."},{"type":"simple","zh":"周末的时候，我经常去图书馆看书，或者和朋友去电影院看电影。","pinyin":"Zhōumò de shíhou, wǒ jīngcháng qù túshūguǎn kànshū, huòzhě hé péngyou qù diànyǐngyuàn kàndiànyǐng.","vi":"Vào cuối tuần, tôi thường đến thư viện đọc sách, hoặc cùng bạn bè đi rạp xem phim."},{"type":"compound","zh":"从这里去机场，你可以选择坐地铁，或者直接打一辆出租车过去。","pinyin":"Cóng zhèlǐ qù jīchǎng, nǐ kěyǐ xuǎnzé zuò dìtiě, huòzhě zhíjiē dǎ yí liàng chūzūchē guòqù.","vi":"Từ đây ra sân bay, bạn có thể chọn đi tàu điện ngầm, hoặc bắt thẳng một chiếc taxi qua đó."}],"related":[{"hanzi":"还是","pinyin":"háishi","vi":"Hay là (câu hỏi)"},{"hanzi":"和","pinyin":"hé","vi":"Và"},{"hanzi":"跟","pinyin":"gēn","vi":"Cùng với"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"Lựa chọn"},{"hanzi":"记者","pinyin":"jìzhě","vi":"Nhà báo"}]}];
